                            if destination_rect.height() != rect.height()
                                || destination_rect.width() != rect.width()
                            {
                                return Err(OmError::invalid_argument(
                                    "Range.Copy Destination must be a single cell or match the source range size",
                                ));
                            }
                            destination_rect
