                                moved_chart.id = temporary_chart_id;
                                moved_chart.workbook_id = runtime.loaded.state.model.id;
                                moved_chart.raw_part_uri = None;
                                moved_chart.dirty = true;
                                runtime
                                    .loaded
                                    .state
