    fn dispatch_get_series_collection(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        axis_group_filter: Option<ChartAxisGroup>,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("SeriesCollection", member) {
            self.focus_member_supported("SeriesCollection", member, false)?;
        }

        match member {
            "Count" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "SeriesCollection.Count does not accept arguments",
                    ));
                }
                let chart = self.chart_model(workbook, chart_id)?;
                let count = chart
                    .series
                    .iter()
                    .filter(|series| {
                        axis_group_filter
                            .map(|axis_group| series.axis_group == axis_group)
                            .unwrap_or(true)
                    })
                    .count();
                Ok(OmValue::Number(count as f64))
            }
            "Item" => self.dispatch_invoke_series_collection(
                workbook,
                chart_id,
                axis_group_filter,
                chart_object_parent,
                member,
                args,
            ),
            "Creator" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "SeriesCollection.Creator does not accept arguments",
                    ));
                }
                self.chart_model(workbook, chart_id)?;
                Ok(OmValue::Number(f64::from(XL_CREATOR_CODE)))
            }
            "Application" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "SeriesCollection.Application does not accept arguments",
                    ));
                }
                Ok(OmValue::Object(self.root_application()))
            }
            "Parent" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "SeriesCollection.Parent does not accept arguments",
                    ));
                }
                Ok(OmValue::Object(
                    self.register_chart_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        chart_object_parent,
                    ),
                ))
            }
            _ => Err(OmError::unsupported(format!(
                "SeriesCollection.{member} is not implemented"
            ))),
        }
    }

    fn dispatch_invoke_series_collection(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        axis_group_filter: Option<ChartAxisGroup>,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("SeriesCollection", member) {
            self.focus_member_supported("SeriesCollection", member, false)?;
        }

        match member {
            "Item" => {
                let [index] = args else {
                    return Err(OmError::invalid_argument(
                        "SeriesCollection.Item expects a single 1-based index or series name",
                    ));
                };
                let index = match index {
                    OmValue::Number(_) => {
                        let index = coerce_u32_arg(index, "SeriesCollection.Item index")? as usize;
                        let chart = self.chart_model(workbook, chart_id)?;
                        let matching_indices = chart
                            .series
                            .iter()
                            .enumerate()
                            .filter_map(|(series_index, series)| {
                                axis_group_filter
                                    .map(|axis_group| series.axis_group == axis_group)
                                    .unwrap_or(true)
                                    .then_some(series_index)
                            })
                            .collect::<Vec<_>>();
                        if index == 0 || index > matching_indices.len() {
                            return Err(OmError::invalid_argument(
                                "SeriesCollection.Item index is out of bounds",
                            ));
                        }
                        matching_indices[index - 1]
                    }
                    OmValue::Text(name) => {
                        let lookup = name.trim();
                        let state = &self.runtime_workbook(workbook)?.loaded.state;
                        let chart = state.charts.get(&chart_id).ok_or_else(|| {
                            OmError::new(OmErrorCode::NotFound, "chart not found")
                        })?;
                        let mut matched_index = None;
                        for (series_index, series) in chart.series.iter().enumerate() {
                            if axis_group_filter
                                .map(|axis_group| series.axis_group != axis_group)
                                .unwrap_or(false)
                            {
                                continue;
                            }
                            let Some(source) = series.name.as_ref() else {
                                continue;
                            };
                            let raw = source.raw.text.trim();
                            let raw_without_equals = raw.trim_start_matches('=');
                            let display_name = chart_source_value_text_for_index(state, source, 0);
                            let formula_name = chart_source_expr_text(Some(source));
                            if raw.eq_ignore_ascii_case(lookup)
                                || raw_without_equals.eq_ignore_ascii_case(lookup)
                                || display_name
                                    .as_deref()
                                    .is_some_and(|value| value.eq_ignore_ascii_case(lookup))
                                || formula_name
                                    .as_deref()
                                    .is_some_and(|value| value.eq_ignore_ascii_case(lookup))
                            {
                                matched_index = Some(series_index);
                                break;
                            }
                        }
                        matched_index.ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::NotFound,
                                "SeriesCollection.Item series name not found",
                            )
                        })?
                    }
                    _ => {
                        return Err(OmError::type_mismatch(
                            "SeriesCollection.Item expects a numeric index or series name",
                        ));
                    }
                };
                Ok(OmValue::Object(
                    self.register_series_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        index,
                        chart_object_parent,
                    ),
                ))
            }
            "NewSeries" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "SeriesCollection.NewSeries does not accept arguments",
                    ));
                }
                let axis_group = axis_group_filter.unwrap_or(ChartAxisGroup::Primary);
                if axis_group == ChartAxisGroup::Secondary {
                    self.set_chart_axis_presence(
                        workbook,
                        chart_id,
                        XL_VALUE,
                        ChartAxisGroup::Secondary,
                        true,
                    )?;
                }
                let series_index = {
                    let runtime = self.runtime_workbook_mut(workbook)?;
                    if runtime.read_only {
                        return Err(OmError::new(
                            OmErrorCode::InvalidState,
                            "cannot modify a read-only workbook",
                        ));
                    }
                    let chart = runtime
                        .loaded
                        .state
                        .charts
                        .get_mut(&chart_id)
                        .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart not found"))?;
                    let series_index = chart.series.len();
                    chart.series.push(SeriesModel {
                        name: None,
                        x_values: None,
                        values: None,
                        bubble_size: None,
                        bar_shape: None,
                        smooth: None,
                        marker_style: None,
                        marker_size: None,
                        invert_if_negative: None,
                        points: BTreeMap::new(),
                        data_labels: None,
                        point_data_labels: BTreeMap::new(),
                        order: u32::try_from(series_index).ok(),
                        axis_group,
                    });
                    if let Some(plot_order) = series_index
                        .checked_add(1)
                        .and_then(|index| u32::try_from(index).ok())
                    {
                        update_series_plot_order(&mut chart.series, series_index, plot_order);
                    }
                    chart.dirty = true;
                    runtime.dirty = true;
                    series_index
                };
                Ok(OmValue::Object(
                    self.register_series_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        series_index,
                        chart_object_parent,
                    ),
                ))
            }
            "Add" => {
                if args.is_empty() || args.len() > 5 {
                    return Err(OmError::invalid_argument(
                        "SeriesCollection.Add expects Source and optional Rowcol, SeriesLabels, CategoryLabels, and Replace arguments",
                    ));
                }
                let plot_by =
                    chart_plot_by_from_optional_arg(args.get(1), "SeriesCollection.Add Rowcol")?;
                let series_labels = args
                    .get(2)
                    .map(|value| {
                        coerce_optional_bool_arg(value, false, "SeriesCollection.Add SeriesLabels")
                    })
                    .transpose()?
                    .unwrap_or(false);
                let category_labels = args
                    .get(3)
                    .map(|value| {
                        coerce_optional_bool_arg(
                            value,
                            false,
                            "SeriesCollection.Add CategoryLabels",
                        )
                    })
                    .transpose()?
                    .unwrap_or(false);
                let replace = args
                    .get(4)
                    .map(|value| {
                        coerce_optional_bool_arg(value, false, "SeriesCollection.Add Replace")
                    })
                    .transpose()?
                    .unwrap_or(false);
                let source_range =
                    self.chart_source_range_from_arg(workbook, &args[0], "SeriesCollection.Add")?;
                let existing_series_len = self.chart_model(workbook, chart_id)?.series.len();
                let mut new_series = self.chart_series_models_for_range_source(
                    workbook,
                    &source_range,
                    plot_by,
                    existing_series_len,
                    series_labels,
                    category_labels,
                )?;
                if let Some(axis_group) = axis_group_filter {
                    if axis_group == ChartAxisGroup::Secondary {
                        self.set_chart_axis_presence(
                            workbook,
                            chart_id,
                            XL_VALUE,
                            ChartAxisGroup::Secondary,
                            true,
                        )?;
                    }
                    for series in &mut new_series {
                        series.axis_group = axis_group;
                    }
                }
                let replacement_category_sources = if replace {
                    if !category_labels {
                        return Err(OmError::invalid_argument(
                            "SeriesCollection.Add Replace requires CategoryLabels",
                        ));
                    }
                    let category_sources = new_series
                        .iter()
                        .filter_map(|series| series.x_values.clone())
                        .collect::<Vec<_>>();
                    if category_sources.is_empty() {
                        return Err(OmError::invalid_argument(
                            "SeriesCollection.Add Replace requires category label source data",
                        ));
                    }
                    Some(category_sources)
                } else {
                    None
                };
                let first_new_series_index = {
                    let runtime = self.runtime_workbook_mut(workbook)?;
                    if runtime.read_only {
                        return Err(OmError::new(
                            OmErrorCode::InvalidState,
                            "cannot modify a read-only workbook",
                        ));
                    }
                    let chart = runtime
                        .loaded
                        .state
                        .charts
                        .get_mut(&chart_id)
                        .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "chart not found"))?;
                    if let Some(category_sources) = replacement_category_sources
                        && !chart.series.is_empty()
                    {
                        let first_category_source = &category_sources[0];
                        if category_sources
                            .iter()
                            .all(|source| source.raw.text == first_category_source.raw.text)
                        {
                            for series in &mut chart.series {
                                series.x_values = Some(first_category_source.clone());
                            }
                        } else if category_sources.len() == chart.series.len() {
                            for (series, category_source) in
                                chart.series.iter_mut().zip(category_sources.iter())
                            {
                                series.x_values = Some(category_source.clone());
                            }
                        } else {
                            return Err(OmError::unsupported(
                                "SeriesCollection.Add Replace with multiple category label ranges requires one range or one range per existing series",
                            ));
                        }
                    }
                    let first_new_series_index = chart.series.len();
                    chart.series.append(&mut new_series);
                    chart.dirty = true;
                    runtime.dirty = true;
                    first_new_series_index
                };
                Ok(OmValue::Object(
                    self.register_series_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        first_new_series_index,
                        chart_object_parent,
                    ),
                ))
            }
            _ => Err(OmError::unsupported(format!(
                "SeriesCollection.{member} is not implemented as a method"
            ))),
        }
    }

    fn chart_source_range_from_arg(
        &self,
        workbook: WorkbookHandle,
        value: &OmValue,
        owner: &str,
    ) -> OmResult<RangeSet> {
        match value {
            OmValue::Object(handle) => match self.runtime_object(*handle)? {
                RuntimeObjectKind::Range {
                    workbook: range_workbook,
                    range,
                    ..
                } => {
                    if range_workbook != workbook {
                        return Err(OmError::unsupported(format!(
                            "{owner} cross-workbook ranges are not supported"
                        )));
                    }
                    for area in range.areas() {
                        if matches!(area.scope, SheetScope::Multi3D { .. }) {
                            return Err(OmError::unsupported(format!(
                                "{owner} 3D ranges are not supported"
                            )));
                        }
                    }
                    Ok(range)
                }
                _ => Err(OmError::type_mismatch(format!(
                    "{owner} Source expects a Range object"
                ))),
            },
            _ => Err(OmError::type_mismatch(format!(
                "{owner} Source expects a Range object"
            ))),
        }
    }

    fn chart_series_models_for_range_source(
        &self,
        workbook: WorkbookHandle,
        source_range: &RangeSet,
        plot_by: Option<i32>,
        first_order: usize,
        series_labels: bool,
        category_labels: bool,
    ) -> OmResult<Vec<SeriesModel>> {
        let workbook_id = self.workbook_model(workbook)?.id;
        let mut new_series = Vec::new();
        let plot_by = if plot_by.is_none() && (series_labels || category_labels) {
            Some(XL_PLOT_BY_COLUMNS)
        } else {
            plot_by
        };
        let mut make_series = |name: Option<ChartSourceExpr>,
                               x_values: Option<ChartSourceExpr>,
                               values: ChartSourceExpr| {
            let order = u32::try_from(first_order + new_series.len()).ok();
            new_series.push(SeriesModel {
                name,
                x_values,
                values: Some(values),
                bubble_size: None,
                bar_shape: None,
                smooth: None,
                marker_style: None,
                marker_size: None,
                invert_if_negative: None,
                points: BTreeMap::new(),
                data_labels: None,
                point_data_labels: BTreeMap::new(),
                order,
                axis_group: ChartAxisGroup::Primary,
            });
        };
        match plot_by {
            Some(XL_PLOT_BY_ROWS) => {
                for area in source_range.areas() {
                    let SheetScope::Single(source_sheet_id) = area.scope else {
                        unreachable!("3D ranges were rejected above");
                    };
                    let worksheet_name = self
                        .worksheet_model(workbook, source_sheet_id)?
                        .name
                        .clone();
                    let data_row_first = if category_labels {
                        area.rect.row_first.checked_add(1).ok_or_else(|| {
                            OmError::invalid_argument(
                                "SeriesCollection.Add category labels leave no data rows",
                            )
                        })?
                    } else {
                        area.rect.row_first
                    };
                    let data_col_first = if series_labels {
                        area.rect.col_first.checked_add(1).ok_or_else(|| {
                            OmError::invalid_argument(
                                "SeriesCollection.Add series labels leave no data columns",
                            )
                        })?
                    } else {
                        area.rect.col_first
                    };
                    if data_row_first > area.rect.row_last {
                        return Err(OmError::invalid_argument(
                            "SeriesCollection.Add category labels leave no data rows",
                        ));
                    }
                    if data_col_first > area.rect.col_last {
                        return Err(OmError::invalid_argument(
                            "SeriesCollection.Add series labels leave no data columns",
                        ));
                    }
                    let x_values = if category_labels {
                        Some(chart_source_expr_for_range(
                            workbook_id,
                            source_sheet_id,
                            Rect {
                                row_first: area.rect.row_first,
                                row_last: area.rect.row_first,
                                col_first: data_col_first,
                                col_last: area.rect.col_last,
                            },
                            &worksheet_name,
                        )?)
                    } else {
                        None
                    };
                    for row in data_row_first..=area.rect.row_last {
                        let name = if series_labels {
                            Some(chart_source_expr_for_range(
                                workbook_id,
                                source_sheet_id,
                                Rect {
                                    row_first: row,
                                    row_last: row,
                                    col_first: area.rect.col_first,
                                    col_last: area.rect.col_first,
                                },
                                &worksheet_name,
                            )?)
                        } else {
                            None
                        };
                        let values_rect = Rect {
                            row_first: row,
                            row_last: row,
                            col_first: data_col_first,
                            col_last: area.rect.col_last,
                        };
                        make_series(
                            name,
                            x_values.clone(),
                            chart_source_expr_for_range(
                                workbook_id,
                                source_sheet_id,
                                values_rect,
                                &worksheet_name,
                            )?,
                        );
                    }
                }
            }
            Some(XL_PLOT_BY_COLUMNS) => {
                for area in source_range.areas() {
                    let SheetScope::Single(source_sheet_id) = area.scope else {
                        unreachable!("3D ranges were rejected above");
                    };
                    let worksheet_name = self
                        .worksheet_model(workbook, source_sheet_id)?
                        .name
                        .clone();
                    let data_row_first = if series_labels {
                        area.rect.row_first.checked_add(1).ok_or_else(|| {
                            OmError::invalid_argument(
                                "SeriesCollection.Add series labels leave no data rows",
                            )
                        })?
                    } else {
                        area.rect.row_first
                    };
                    let data_col_first = if category_labels {
                        area.rect.col_first.checked_add(1).ok_or_else(|| {
                            OmError::invalid_argument(
                                "SeriesCollection.Add category labels leave no data columns",
                            )
                        })?
                    } else {
                        area.rect.col_first
                    };
                    if data_row_first > area.rect.row_last {
                        return Err(OmError::invalid_argument(
                            "SeriesCollection.Add series labels leave no data rows",
                        ));
                    }
                    if data_col_first > area.rect.col_last {
                        return Err(OmError::invalid_argument(
                            "SeriesCollection.Add category labels leave no data columns",
                        ));
                    }
                    let x_values = if category_labels {
                        Some(chart_source_expr_for_range(
                            workbook_id,
                            source_sheet_id,
                            Rect {
                                row_first: data_row_first,
                                row_last: area.rect.row_last,
                                col_first: area.rect.col_first,
                                col_last: area.rect.col_first,
                            },
                            &worksheet_name,
                        )?)
                    } else {
                        None
                    };
                    for col in data_col_first..=area.rect.col_last {
                        let name = if series_labels {
                            Some(chart_source_expr_for_range(
                                workbook_id,
                                source_sheet_id,
                                Rect {
                                    row_first: area.rect.row_first,
                                    row_last: area.rect.row_first,
                                    col_first: col,
                                    col_last: col,
                                },
                                &worksheet_name,
                            )?)
                        } else {
                            None
                        };
                        let values_rect = Rect {
                            row_first: data_row_first,
                            row_last: area.rect.row_last,
                            col_first: col,
                            col_last: col,
                        };
                        make_series(
                            name,
                            x_values.clone(),
                            chart_source_expr_for_range(
                                workbook_id,
                                source_sheet_id,
                                values_rect,
                                &worksheet_name,
                            )?,
                        );
                    }
                }
            }
            Some(_) => unreachable!("unsupported PlotBy was rejected"),
            None => {
                let mut areas = Vec::with_capacity(source_range.len());
                for area in source_range.areas() {
                    let SheetScope::Single(source_sheet_id) = area.scope else {
                        unreachable!("3D ranges were rejected above");
                    };
                    let worksheet_name = self
                        .worksheet_model(workbook, source_sheet_id)?
                        .name
                        .clone();
                    areas.push((source_sheet_id, area.rect, worksheet_name));
                }
                make_series(
                    None,
                    None,
                    chart_source_expr_for_range_areas(workbook_id, areas)?,
                );
            }
        }
        Ok(new_series)
    }

    fn dispatch_get_series(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("Series", member) {
            self.focus_member_supported("Series", member, false)?;
        }

        if !args.is_empty() && member != "DataLabels" && member != "Points" {
            return Err(OmError::invalid_argument(format!(
                "Series.{member} does not accept arguments"
            )));
        }

        match member {
            "Name" => Ok(chart_source_expr_text(
                self.series_model(workbook, chart_id, series_index)?
                    .name
                    .as_ref(),
            )
            .map(OmValue::Text)
            .unwrap_or(OmValue::Empty)),
            "Format" => {
                self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Object(self.register_object(
                    RuntimeObjectKind::ChartFormat {
                        workbook,
                        parent: ChartFormatParent::Series {
                            chart_id,
                            series_index,
                            chart_object_parent,
                        },
                    },
                )))
            }
            "ChartType" => {
                let chart = self.chart_model(workbook, chart_id)?;
                if chart.series.get(series_index).is_none() {
                    return Err(OmError::new(OmErrorCode::NotFound, "series not found"));
                }
                Ok(OmValue::Number(f64::from(chart_type_to_excel_value(
                    &chart.chart_type,
                )?)))
            }
            "Values" => Ok(chart_source_expr_text(
                self.series_model(workbook, chart_id, series_index)?
                    .values
                    .as_ref(),
            )
            .map(OmValue::Text)
            .unwrap_or(OmValue::Empty)),
            "XValues" => Ok(chart_source_expr_text(
                self.series_model(workbook, chart_id, series_index)?
                    .x_values
                    .as_ref(),
            )
            .map(OmValue::Text)
            .unwrap_or(OmValue::Empty)),
            "BubbleSizes" => Ok(chart_source_expr_text(
                self.series_model(workbook, chart_id, series_index)?
                    .bubble_size
                    .as_ref(),
            )
            .map(OmValue::Text)
            .unwrap_or(OmValue::Empty)),
            "BarShape" => {
                let chart = self.chart_model(workbook, chart_id)?;
                ensure_chart_supports_bar_shape(&chart.chart_type)?;
                let series = chart
                    .series
                    .get(series_index)
                    .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "series not found"))?;
                Ok(OmValue::Number(f64::from(
                    series
                        .bar_shape
                        .or_else(|| chart_effective_bar_shape(chart))
                        .map(chart_bar_shape_to_excel_value)
                        .unwrap_or(XL_BOX),
                )))
            }
            "Smooth" => {
                let chart = self.chart_model(workbook, chart_id)?;
                if !chart_type_supports_series_smooth(&chart.chart_type) {
                    return Err(OmError::unsupported(
                        "Series.Smooth is only supported for line and scatter chart types",
                    ));
                }
                let series = chart
                    .series
                    .get(series_index)
                    .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "series not found"))?;
                Ok(OmValue::Bool(series.smooth.unwrap_or_else(|| {
                    chart_type_default_series_smooth(&chart.chart_type)
                })))
            }
            "MarkerStyle" => {
                let chart = self.chart_model(workbook, chart_id)?;
                if !chart_type_supports_series_marker(&chart.chart_type) {
                    return Err(OmError::unsupported(
                        "Series.MarkerStyle is only supported for line, scatter, and radar chart types",
                    ));
                }
                let series = chart
                    .series
                    .get(series_index)
                    .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "series not found"))?;
                Ok(OmValue::Number(f64::from(
                    series
                        .marker_style
                        .map(chart_marker_style_to_excel_value)
                        .unwrap_or(XL_MARKER_STYLE_AUTOMATIC),
                )))
            }
            "MarkerSize" => {
                let chart = self.chart_model(workbook, chart_id)?;
                if !chart_type_supports_series_marker(&chart.chart_type) {
                    return Err(OmError::unsupported(
                        "Series.MarkerSize is only supported for line, scatter, and radar chart types",
                    ));
                }
                let series = chart
                    .series
                    .get(series_index)
                    .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "series not found"))?;
                Ok(OmValue::Number(f64::from(series.marker_size.unwrap_or(5))))
            }
            "InvertIfNegative" => {
                let series = self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Bool(series.invert_if_negative.unwrap_or(false)))
            }
            "Formula" => {
                let series = self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Text(series_formula_text(series, series_index)))
            }
            "AxisGroup" => {
                let series = self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Number(f64::from(match series.axis_group {
                    ChartAxisGroup::Primary => XL_PRIMARY,
                    ChartAxisGroup::Secondary => XL_SECONDARY,
                })))
            }
            "HasDataLabels" => Ok(OmValue::Bool(chart_data_labels_visible(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                ),
            ))),
            "HasLeaderLines" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.has_leader_lines)
                .unwrap_or(false),
            )),
            "DataLabels" => {
                self.series_model(workbook, chart_id, series_index)?;
                let handle = self.register_data_labels_handle_with_chart_object_parent_origin(
                    workbook,
                    chart_id,
                    series_index,
                    chart_object_parent,
                );
                if args.is_empty() {
                    Ok(OmValue::Object(handle))
                } else {
                    self.dispatch_invoke(handle, "Item", args)
                }
            }
            "Points" => {
                self.series_model(workbook, chart_id, series_index)?;
                let handle = self.register_points_handle_with_chart_object_parent_origin(
                    workbook,
                    chart_id,
                    series_index,
                    chart_object_parent,
                );
                if args.is_empty() {
                    Ok(OmValue::Object(handle))
                } else {
                    self.dispatch_invoke(handle, "Item", args)
                }
            }
            "PlotOrder" => Ok(OmValue::Number(f64::from(series_plot_order(
                self.series_model(workbook, chart_id, series_index)?,
                series_index,
            )))),
            "Creator" => Ok(OmValue::Number(f64::from(XL_CREATOR_CODE))),
            "Application" => Ok(OmValue::Object(self.root_application())),
            "Parent" => Ok(OmValue::Object(
                self.register_series_collection_handle_with_chart_object_parent_origin(
                    workbook,
                    chart_id,
                    chart_object_parent,
                ),
            )),
            _ => Err(OmError::unsupported(format!(
                "Series.{member} is not implemented"
            ))),
        }
    }

    fn dispatch_get_data_labels(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("DataLabels", member) {
            self.focus_member_supported("DataLabels", member, false)?;
        }

        if !args.is_empty() && member != "Item" {
            return Err(OmError::invalid_argument(format!(
                "DataLabels.{member} does not accept arguments"
            )));
        }

        match member {
            "Item" => self.dispatch_invoke_data_labels(
                workbook,
                chart_id,
                series_index,
                chart_object_parent,
                member,
                args,
            ),
            "Name" => Ok(OmValue::Text("Data Labels".to_string())),
            "Format" => {
                self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Object(self.register_object(
                    RuntimeObjectKind::ChartFormat {
                        workbook,
                        parent: ChartFormatParent::DataLabels {
                            chart_id,
                            series_index,
                            chart_object_parent,
                        },
                    },
                )))
            }
            "Count" => {
                let chart = self.chart_model(workbook, chart_id)?;
                if chart.series.get(series_index).is_none() {
                    return Err(OmError::new(OmErrorCode::NotFound, "series not found"));
                }
                Ok(OmValue::Number(
                    chart_data_labels_count_for_chart_series(chart, series_index) as f64,
                ))
            }
            "Type" => Ok(OmValue::Number(f64::from(
                chart_data_labels_type_to_excel_value(chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )),
            ))),
            "ShowLegendKey" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.show_legend_key)
                .unwrap_or(false),
            )),
            "HasLeaderLines" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.has_leader_lines)
                .unwrap_or(false),
            )),
            "ShowSeriesName" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.show_series_name)
                .unwrap_or(false),
            )),
            "ShowCategoryName" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.show_category_name)
                .unwrap_or(false),
            )),
            "ShowValue" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.show_value)
                .unwrap_or(false),
            )),
            "ShowPercentage" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.show_percentage)
                .unwrap_or(false),
            )),
            "ShowBubbleSize" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.show_bubble_size)
                .unwrap_or(false),
            )),
            "NumberFormat" | "NumberFormatLocal" => Ok(OmValue::Text(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.number_format.clone())
                .unwrap_or_else(|| "General".to_string()),
            )),
            "NumberFormatLinked" => Ok(OmValue::Bool(
                chart_series_effective_data_labels(
                    self.chart_model(workbook, chart_id)?,
                    series_index,
                )
                .and_then(|labels| labels.number_format_linked)
                .unwrap_or(true),
            )),
            "Position" => Ok(OmValue::Number(f64::from(
                chart_data_label_position_to_excel_value(
                    chart_series_effective_data_labels(
                        self.chart_model(workbook, chart_id)?,
                        series_index,
                    )
                    .and_then(|labels| labels.position)
                    .unwrap_or(ChartDataLabelPosition::BestFit),
                ),
            ))),
            "Separator" => Ok(chart_series_effective_data_labels(
                self.chart_model(workbook, chart_id)?,
                series_index,
            )
            .and_then(|labels| labels.separator.clone())
            .map(OmValue::Text)
            .unwrap_or(OmValue::Empty)),
            "Creator" => Ok(OmValue::Number(f64::from(XL_CREATOR_CODE))),
            "Application" => Ok(OmValue::Object(self.root_application())),
            "Parent" => Ok(OmValue::Object(
                self.register_series_handle_with_chart_object_parent_origin(
                    workbook,
                    chart_id,
                    series_index,
                    chart_object_parent,
                ),
            )),
            _ => Err(OmError::unsupported(format!(
                "DataLabels.{member} is not implemented"
            ))),
        }
    }

    fn dispatch_invoke_data_labels(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("DataLabels", member) {
            self.focus_member_supported("DataLabels", member, false)?;
        }

        match member {
            "Item" => {
                let [index] = args else {
                    return Err(OmError::invalid_argument(
                        "DataLabels.Item expects a single 1-based index",
                    ));
                };
                let index = coerce_u32_arg(index, "DataLabels.Item index")? as usize;
                let chart = self.chart_model(workbook, chart_id)?;
                if chart.series.get(series_index).is_none() {
                    return Err(OmError::new(OmErrorCode::NotFound, "series not found"));
                }
                let label_count = chart_data_labels_count_for_chart_series(chart, series_index);
                if index == 0 || index > label_count {
                    return Err(OmError::invalid_argument(
                        "DataLabels.Item index is out of bounds",
                    ));
                }
                Ok(OmValue::Object(
                    self.register_data_label_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        series_index,
                        index - 1,
                        chart_object_parent,
                    ),
                ))
            }
            _ => Err(OmError::unsupported(format!(
                "DataLabels.{member} is not implemented as a method"
            ))),
        }
    }

    fn dispatch_get_data_label(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        point_index: usize,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("DataLabel", member) {
            self.focus_member_supported("DataLabel", member, false)?;
        }

        if !args.is_empty() {
            return Err(OmError::invalid_argument(format!(
                "DataLabel.{member} does not accept arguments"
            )));
        }
        let data_labels = self
            .validate_data_label_index(workbook, chart_id, series_index, point_index)?
            .cloned();

        match member {
            "Name" => Ok(OmValue::Text(format!("Data Label {}", point_index + 1))),
            "Format" => Ok(OmValue::Object(self.register_object(
                RuntimeObjectKind::ChartFormat {
                    workbook,
                    parent: ChartFormatParent::DataLabel {
                        chart_id,
                        series_index,
                        point_index,
                        chart_object_parent,
                    },
                },
            ))),
            "Index" => Ok(OmValue::Number((point_index + 1) as f64)),
            "Type" => Ok(OmValue::Number(f64::from(
                chart_data_labels_type_to_excel_value(data_labels.as_ref()),
            ))),
            "ShowLegendKey" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.show_legend_key)
                    .unwrap_or(false),
            )),
            "HasLeaderLines" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.has_leader_lines)
                    .unwrap_or(false),
            )),
            "ShowSeriesName" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.show_series_name)
                    .unwrap_or(false),
            )),
            "ShowCategoryName" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.show_category_name)
                    .unwrap_or(false),
            )),
            "ShowValue" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.show_value)
                    .unwrap_or(false),
            )),
            "ShowPercentage" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.show_percentage)
                    .unwrap_or(false),
            )),
            "ShowBubbleSize" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.show_bubble_size)
                    .unwrap_or(false),
            )),
            "NumberFormat" | "NumberFormatLocal" => Ok(OmValue::Text(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.number_format.clone())
                    .unwrap_or_else(|| "General".to_string()),
            )),
            "NumberFormatLinked" => Ok(OmValue::Bool(
                data_labels
                    .as_ref()
                    .and_then(|labels| labels.number_format_linked)
                    .unwrap_or(true),
            )),
            "Position" => Ok(OmValue::Number(f64::from(
                chart_data_label_position_to_excel_value(
                    data_labels
                        .as_ref()
                        .and_then(|labels| labels.position)
                        .unwrap_or(ChartDataLabelPosition::BestFit),
                ),
            ))),
            "Separator" => Ok(data_labels
                .as_ref()
                .and_then(|labels| labels.separator.clone())
                .map(OmValue::Text)
                .unwrap_or(OmValue::Empty)),
            "Creator" => Ok(OmValue::Number(f64::from(XL_CREATOR_CODE))),
            "Application" => Ok(OmValue::Object(self.root_application())),
            "Parent" => Ok(OmValue::Object(
                self.register_data_labels_handle_with_chart_object_parent_origin(
                    workbook,
                    chart_id,
                    series_index,
                    chart_object_parent,
                ),
            )),
            _ => Err(OmError::unsupported(format!(
                "DataLabel.{member} is not implemented"
            ))),
        }
    }

    fn dispatch_get_points(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("Points", member) {
            self.focus_member_supported("Points", member, false)?;
        }

        match member {
            "Count" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Points.Count does not accept arguments",
                    ));
                }
                Ok(OmValue::Number(chart_series_point_count(self.series_model(
                    workbook,
                    chart_id,
                    series_index,
                )?) as f64))
            }
            "Item" => self.dispatch_invoke_points(
                workbook,
                chart_id,
                series_index,
                chart_object_parent,
                member,
                args,
            ),
            "Creator" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Points.Creator does not accept arguments",
                    ));
                }
                self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Number(f64::from(XL_CREATOR_CODE)))
            }
            "Application" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Points.Application does not accept arguments",
                    ));
                }
                self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Object(self.root_application()))
            }
            "Parent" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Points.Parent does not accept arguments",
                    ));
                }
                self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Object(
                    self.register_series_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        series_index,
                        chart_object_parent,
                    ),
                ))
            }
            _ => Err(OmError::unsupported(format!(
                "Points.{member} is not implemented"
            ))),
        }
    }

    fn dispatch_invoke_points(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("Points", member) {
            self.focus_member_supported("Points", member, false)?;
        }

        match member {
            "Item" => {
                let [index] = args else {
                    return Err(OmError::invalid_argument(
                        "Points.Item expects a single 1-based index",
                    ));
                };
                let index = coerce_u32_arg(index, "Points.Item index")? as usize;
                let point_count = chart_series_point_count(self.series_model(
                    workbook,
                    chart_id,
                    series_index,
                )?);
                if index == 0 || index > point_count {
                    return Err(OmError::invalid_argument(
                        "Points.Item index is out of bounds",
                    ));
                }
                Ok(OmValue::Object(
                    self.register_point_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        series_index,
                        index - 1,
                        chart_object_parent,
                    ),
                ))
            }
            _ => Err(OmError::unsupported(format!(
                "Points.{member} is not implemented as a method"
            ))),
        }
    }

    fn dispatch_get_point(
        &mut self,
        workbook: WorkbookHandle,
        chart_id: ChartId,
        series_index: usize,
        point_index: usize,
        chart_object_parent: Option<ChartObjectsParent>,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if self.focus_member_declared("Point", member) {
            self.focus_member_supported("Point", member, false)?;
        }

        if !args.is_empty() {
            return Err(OmError::invalid_argument(format!(
                "Point.{member} does not accept arguments"
            )));
        }
        self.validate_point_index(workbook, chart_id, series_index, point_index)?;

        match member {
            "Name" => Ok(OmValue::Text(format!("Point {}", point_index + 1))),
            "Format" => Ok(OmValue::Object(self.register_object(
                RuntimeObjectKind::ChartFormat {
                    workbook,
                    parent: ChartFormatParent::Point {
                        chart_id,
                        series_index,
                        point_index,
                        chart_object_parent,
                    },
                },
            ))),
            "Index" => Ok(OmValue::Number((point_index + 1) as f64)),
            "Explosion" => {
                let point_index = u32::try_from(point_index).map_err(|_| {
                    OmError::invalid_argument("Point.Explosion index is out of bounds")
                })?;
                let series = self.series_model(workbook, chart_id, series_index)?;
                Ok(OmValue::Number(f64::from(
                    series
                        .points
                        .get(&point_index)
                        .and_then(|point| point.explosion)
                        .unwrap_or(0),
                )))
            }
            "HasDataLabel" => {
                self.validate_point_index(workbook, chart_id, series_index, point_index)?;
                Ok(OmValue::Bool(chart_data_labels_visible(
                    chart_point_effective_data_labels(
                        self.chart_model(workbook, chart_id)?,
                        series_index,
                        point_index,
                    ),
                )))
            }
            "DataLabel" => {
                self.validate_data_label_index(workbook, chart_id, series_index, point_index)?;
                Ok(OmValue::Object(
                    self.register_data_label_handle_with_chart_object_parent_origin(
                        workbook,
                        chart_id,
                        series_index,
                        point_index,
                        chart_object_parent,
                    ),
                ))
            }
            "Creator" => Ok(OmValue::Number(f64::from(XL_CREATOR_CODE))),
            "Application" => Ok(OmValue::Object(self.root_application())),
            "Parent" => Ok(OmValue::Object(
                self.register_points_handle_with_chart_object_parent_origin(
                    workbook,
                    chart_id,
                    series_index,
                    chart_object_parent,
                ),
            )),
            _ => Err(OmError::unsupported(format!(
                "Point.{member} is not implemented"
            ))),
        }
    }

    fn range_set_address(
        &mut self,
        workbook: WorkbookHandle,
        range: &RangeSet,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        if args.len() > 5 {
            return Err(OmError::invalid_argument(
                "Range.Address accepts optional RowAbsolute, ColumnAbsolute, ReferenceStyle, External, and RelativeTo arguments",
            ));
        }
        let row_absolute = args
            .first()
            .map(|value| coerce_optional_bool_arg(value, true, "Range.Address row absolute"))
            .transpose()?
            .unwrap_or(true);
        let column_absolute = args
            .get(1)
            .map(|value| coerce_optional_bool_arg(value, true, "Range.Address column absolute"))
            .transpose()?
            .unwrap_or(true);
        let reference_style = args
            .get(2)
            .map(coerce_optional_reference_style_arg)
            .transpose()?
            .unwrap_or(RangeAddressReferenceStyle::A1);
        let external = args
            .get(3)
            .map(|value| coerce_optional_bool_arg(value, false, "Range.Address external"))
            .transpose()?
            .unwrap_or(false);
        let relative_to = match args.get(4) {
            None => None,
            Some(value) if om_value_is_omitted(value) => None,
            Some(OmValue::Object(handle)) => match self.runtime_object(*handle)? {
                RuntimeObjectKind::Range { range, .. } => {
                    let (_, relative_rect) = Self::range_set_first_area(&range)?;
                    Some((relative_rect.row_first, relative_rect.col_first))
                }
                _ => {
                    return Err(OmError::type_mismatch(
                        "Range.Address RelativeTo expects a Range object when provided",
                    ));
                }
            },
            Some(_) => {
                return Err(OmError::type_mismatch(
                    "Range.Address RelativeTo expects a Range object when provided",
                ));
            }
        };

        let workbook_name = if external {
            Some(self.workbook_model(workbook)?.display_name.clone())
        } else {
            None
        };
        let mut common_sheet_id = None;
        let mut spans_multiple_sheets = false;
        for area in range.areas() {
            let SheetScope::Single(sheet_id) = area.scope else {
                return Err(OmError::unsupported(
                    "3D range handles are not supported by Range.Address yet",
                ));
            };
            match common_sheet_id {
                Some(existing_sheet_id) if existing_sheet_id != sheet_id => {
                    spans_multiple_sheets = true;
                    break;
                }
                Some(_) => {}
                None => common_sheet_id = Some(sheet_id),
            }
        }
        let mut parts = Vec::with_capacity(range.areas().len());
        for area in range.areas() {
            let SheetScope::Single(sheet_id) = area.scope else {
                return Err(OmError::unsupported(
                    "3D range handles are not supported by Range.Address yet",
                ));
            };
            let mut address = match reference_style {
                RangeAddressReferenceStyle::A1 => {
                    format_rect_address_with_flags(area.rect, row_absolute, column_absolute)
                }
                RangeAddressReferenceStyle::R1C1 => {
                    let (base_row, base_col) =
                        relative_to.unwrap_or((area.rect.row_first, area.rect.col_first));
                    format_rect_r1c1_address_with_flags(
                        area.rect,
                        row_absolute,
                        column_absolute,
                        base_row,
                        base_col,
                    )
                }
            };
            if let Some(workbook_name) = workbook_name.as_ref() {
                let worksheet_name = self.worksheet_model(workbook, sheet_id)?.name.clone();
                address.insert_str(
                    0,
                    format_external_address_qualifier(workbook_name, &worksheet_name).as_str(),
                );
            } else if spans_multiple_sheets {
                let worksheet_name = self.worksheet_model(workbook, sheet_id)?.name.clone();
                address.insert_str(0, formula_sheet_address_qualifier(&worksheet_name).as_str());
            }
            parts.push(address);
        }

        Ok(OmValue::Text(parts.join(",")))
    }

    fn dispatch_set_range(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        rect: Rect,
        _projection: RangeProjection,
        member: &str,
        value: OmValue,
        args: &[OmValue],
    ) -> OmResult<()> {
        self.focus_member_supported("Range", member, true)?;
        if !args.is_empty() {
            return Err(OmError::invalid_argument(format!(
                "Range.{member} does not accept index arguments"
            )));
        }

        match member {
            "Value" | "Value2" | "Formula" | "FormulaR1C1" | "Formula2" | "Formula2R1C1"
            | "FormulaLocal" | "FormulaR1C1Local" | "Formula2Local" | "Formula2R1C1Local" => {
                let values = match value {
                    OmValue::Array(array) => array,
                    scalar => OmArray::new(
                        rect.height() as usize,
                        rect.width() as usize,
                        vec![scalar; rect.height() as usize * rect.width() as usize],
                    )?,
                };
                if matches!(
                    member,
                    "Formula" | "Formula2" | "FormulaLocal" | "Formula2Local"
                ) {
                    self.set_range_formulas(SetRangeValuesSpec {
                        workbook,
                        range: self.range_ref(workbook, sheet_id, rect)?,
                        values,
                    })?;
                } else if matches!(
                    member,
                    "FormulaR1C1" | "Formula2R1C1" | "FormulaR1C1Local" | "Formula2R1C1Local"
                ) {
                    if values.rows != rect.height() as usize || values.cols != rect.width() as usize
                    {
                        return Err(OmError::invalid_argument(format!(
                            "range dimensions {}x{} do not match formula matrix {}x{}",
                            rect.height(),
                            rect.width(),
                            values.rows,
                            values.cols,
                        )));
                    }

                    let mut updates = Vec::with_capacity(values.values.len());
                    for row_offset in 0..values.rows {
                        for col_offset in 0..values.cols {
                            let row = rect.row_first + row_offset as u32;
                            let col = rect.col_first + col_offset as u32;
                            let value =
                                values.values[row_offset * values.cols + col_offset].clone();
                            let (cell_value, formula) = match value {
                                OmValue::Text(text) => {
                                    if let Some(formula_text) = text.strip_prefix('=') {
                                        (
                                            CellValue::Blank,
                                            Some(FormulaSource {
                                                text: formula_text.to_string(),
                                                is_r1c1: true,
                                            }),
                                        )
                                    } else {
                                        (CellValue::Text(text), None)
                                    }
                                }
                                other => (CellValue::try_from(other)?, None),
                            };
                            updates.push(((row, col), cell_value, formula));
                        }
                    }

                    let runtime = self.runtime_workbook_mut(workbook)?;
                    if runtime.read_only {
                        return Err(OmError::new(
                            OmErrorCode::InvalidState,
                            "cannot modify a read-only workbook",
                        ));
                    }
                    let worksheet = runtime
                        .loaded
                        .state
                        .worksheet_data_for_sheet_mut(sheet_id)?;
                    for (key, cell_value, formula) in updates {
                        if let Some(existing) = worksheet.cells.get_mut(&key) {
                            if existing.value == cell_value && existing.formula == formula {
                                continue;
                            }

                            existing.value = cell_value;
                            existing.formula = formula;
                            if matches!(existing.value, CellValue::Blank)
                                && existing.style_id.is_none()
                                && existing.formula.is_none()
                            {
                                worksheet.cells.remove(&key);
                            }
                            worksheet.dirty = true;
                            worksheet.dirty_cells.insert(key);
                            continue;
                        }

                        if !matches!(cell_value, CellValue::Blank) || formula.is_some() {
                            worksheet.cells.insert(
                                key,
                                excel_model::CellData {
                                    value: cell_value,
                                    formula,
                                    style_id: None,
                                },
                            );
                            worksheet.dirty = true;
                            worksheet.dirty_cells.insert(key);
                        }
                    }
                } else {
                    self.set_range_values(SetRangeValuesSpec {
                        workbook,
                        range: self.range_ref(workbook, sheet_id, rect)?,
                        values,
                    })?;
                }
                Ok(())
            }
            _ => Err(OmError::unsupported(format!(
                "Range.{member} is not writable"
            ))),
        }
    }

    fn dispatch_invoke_workbook(
        &mut self,
        workbook: WorkbookHandle,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        self.focus_member_supported("Workbook", member, false)?;

        match member {
            "Activate" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Workbook.Activate does not accept arguments",
                    ));
                }
                let selection = self.default_selection(workbook)?;
                self.set_selection(workbook, selection.sheet_id, selection.rect);
                Ok(OmValue::Empty)
            }
            "Save" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Workbook.Save does not accept arguments",
                    ));
                }
                let format = self.workbook_model(workbook)?.format;
                let bytes = self.save_workbook(
                    workbook,
                    SaveWorkbookSpec {
                        format,
                        profile: ExcelProfile::Excel365,
                        lossless: true,
                    },
                )?;
                if let Some(path) = self.runtime_workbook(workbook)?.source_path.as_ref() {
                    fs::write(path, &bytes).map_err(|error| {
                        OmError::new(
                            OmErrorCode::Io,
                            format!("failed to write workbook {}: {error}", path.display()),
                        )
                    })?;
                    self.clear_workbook_dirty_state(workbook)?;
                }
                Ok(OmValue::Empty)
            }
            "SaveAs" => {
                if args.is_empty() || args.len() > 12 {
                    return Err(OmError::invalid_argument(
                        "Workbook.SaveAs expects Filename and up to 11 optional arguments",
                    ));
                }
                let path = match &args[0] {
                    OmValue::Text(path) => PathBuf::from(path),
                    _ => {
                        return Err(OmError::type_mismatch(
                            "Workbook.SaveAs expects a string filename",
                        ));
                    }
                };
                let format = match args.get(1) {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => {
                        file_format_from_path(&path)
                            .unwrap_or(self.workbook_model(workbook)?.format)
                    }
                    Some(OmValue::Number(format)) => {
                        if !format.is_finite()
                            || format.fract() != 0.0
                            || *format < i32::MIN as f64
                            || *format > i32::MAX as f64
                        {
                            return Err(OmError::invalid_argument(
                                "Workbook.SaveAs FileFormat expects an integral XlFileFormat value",
                            ));
                        }
                        match *format as i32 {
                            XL_OPEN_XML_WORKBOOK => FileFormat::Xlsx,
                            XL_OPEN_XML_WORKBOOK_MACRO_ENABLED => FileFormat::Xlsm,
                            XL_OPEN_XML_TEMPLATE => FileFormat::Xltx,
                            XL_OPEN_XML_TEMPLATE_MACRO_ENABLED => FileFormat::Xltm,
                            XL_OPEN_XML_STRICT_WORKBOOK => FileFormat::StrictXlsx,
                            other => {
                                return Err(OmError::unsupported(format!(
                                    "Workbook.SaveAs FileFormat {other} is not implemented",
                                )));
                            }
                        }
                    }
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Workbook.SaveAs FileFormat expects a numeric XlFileFormat value when provided",
                        ));
                    }
                };
                validate_optional_text_arg(args, 2, "Workbook.SaveAs Password")?;
                validate_optional_text_arg(args, 3, "Workbook.SaveAs WriteResPassword")?;
                validate_optional_bool_arg(args, 4, "Workbook.SaveAs ReadOnlyRecommended")?;
                validate_optional_bool_arg(args, 5, "Workbook.SaveAs CreateBackup")?;
                validate_optional_integer_arg(args, 6, "Workbook.SaveAs AccessMode")?;
                validate_optional_integer_arg(args, 7, "Workbook.SaveAs ConflictResolution")?;
                validate_optional_bool_arg(args, 8, "Workbook.SaveAs AddToMru")?;
                validate_optional_integer_arg(args, 9, "Workbook.SaveAs TextCodepage")?;
                validate_optional_integer_arg(args, 10, "Workbook.SaveAs TextVisualLayout")?;
                validate_optional_bool_arg(args, 11, "Workbook.SaveAs Local")?;
                let bytes = self.save_workbook(
                    workbook,
                    SaveWorkbookSpec {
                        format,
                        profile: ExcelProfile::Excel365,
                        lossless: true,
                    },
                )?;
                fs::write(&path, &bytes).map_err(|error| {
                    OmError::new(
                        OmErrorCode::Io,
                        format!("failed to write workbook {}: {error}", path.display()),
                    )
                })?;
                let display_name = path
                    .file_name()
                    .and_then(|value| value.to_str())
                    .filter(|value| !value.is_empty())
                    .map(str::to_owned);
                {
                    let runtime = self.runtime_workbook_mut(workbook)?;
                    runtime.source_path = Some(path);
                    runtime.loaded = retag_loaded_workbook_format(&runtime.loaded, format)?;
                    if let Some(display_name) = display_name {
                        runtime.loaded.state.model.display_name = display_name;
                    }
                }
                self.clear_workbook_dirty_state(workbook)?;
                Ok(OmValue::Empty)
            }
            "SaveCopyAs" => {
                if args.len() != 1 {
                    return Err(OmError::invalid_argument(
                        "Workbook.SaveCopyAs expects a single filename argument",
                    ));
                }
                let path = match &args[0] {
                    OmValue::Text(path) => PathBuf::from(path),
                    _ => {
                        return Err(OmError::type_mismatch(
                            "Workbook.SaveCopyAs expects a string filename",
                        ));
                    }
                };
                let format = self.workbook_model(workbook)?.format;
                let bytes = self.save_workbook(
                    workbook,
                    SaveWorkbookSpec {
                        format,
                        profile: ExcelProfile::Excel365,
                        lossless: true,
                    },
                )?;
                fs::write(&path, &bytes).map_err(|error| {
                    OmError::new(
                        OmErrorCode::Io,
                        format!("failed to write workbook copy {}: {error}", path.display()),
                    )
                })?;
                Ok(OmValue::Empty)
            }
            "RefreshAll" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Workbook.RefreshAll does not accept arguments",
                    ));
                }
                Ok(OmValue::Empty)
            }
            "CheckSpelling" => {
                validate_check_spelling_args(args, "Workbook")?;
                self.runtime_workbook(workbook)?;
                Ok(OmValue::Empty)
            }
            "ExportAsFixedFormat" => {
                validate_export_as_fixed_format_args(args, "Workbook")?;
                self.runtime_workbook(workbook)?;
                Ok(OmValue::Empty)
            }
            "PrintPreview" => {
                validate_print_preview_args(args, "Workbook")?;
                self.runtime_workbook(workbook)?;
                Ok(OmValue::Empty)
            }
            "PrintOut" => {
                validate_print_out_args(args, "Workbook")?;
                self.runtime_workbook(workbook)?;
                Ok(OmValue::Empty)
            }
            "Close" => {
                if args.len() > 3 {
                    return Err(OmError::invalid_argument(
                        "Workbook.Close accepts at most SaveChanges, Filename, and RouteWorkbook arguments",
                    ));
                }
                let save_changes = match args.first() {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => false,
                    Some(OmValue::Bool(save_changes)) => *save_changes,
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Workbook.Close SaveChanges expects a boolean when provided",
                        ));
                    }
                };
                let filename = match args.get(1) {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => None,
                    Some(OmValue::Text(path)) => Some(PathBuf::from(path)),
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Workbook.Close Filename expects a string when provided",
                        ));
                    }
                };
                match args.get(2) {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => {}
                    Some(OmValue::Bool(_)) => {}
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Workbook.Close RouteWorkbook expects a boolean when provided",
                        ));
                    }
                }
                if save_changes {
                    let filename_format = filename
                        .as_ref()
                        .and_then(|path| file_format_from_path(path));
                    let format = match filename_format {
                        Some(format) => format,
                        None => self.workbook_model(workbook)?.format,
                    };
                    let bytes = self.save_workbook(
                        workbook,
                        SaveWorkbookSpec {
                            format,
                            profile: ExcelProfile::Excel365,
                            lossless: true,
                        },
                    )?;
                    let save_path = if let Some(path) = filename.as_ref() {
                        Some(path.clone())
                    } else {
                        self.runtime_workbook(workbook)?.source_path.clone()
                    };
                    if let Some(path) = save_path.as_ref() {
                        fs::write(path, &bytes).map_err(|error| {
                            OmError::new(
                                OmErrorCode::Io,
                                format!("failed to write workbook {}: {error}", path.display()),
                            )
                        })?;
                    }
                }
                self.close_workbook(workbook)?;
                Ok(OmValue::Empty)
            }
            _ => Err(OmError::unsupported(format!(
                "Workbook.{member} is not implemented as a method"
            ))),
        }
    }

    fn evaluate_formula_expression(
        &self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        expression: &str,
        context: &str,
    ) -> OmResult<OmValue> {
        let state = &self.runtime_workbook(workbook)?.loaded.state;
        let mut evaluator = FormulaEvaluator::new(state);
        match evaluator.evaluate_formula_text(sheet_id, expression, None) {
            Ok(value) => Ok(OmValue::from(value)),
            Err(error) => match error.into_cell_value() {
                Some(value) => Ok(OmValue::from(value)),
                None => Err(OmError::unsupported(format!(
                    "{context} formula is not supported"
                ))),
            },
        }
    }

    fn dispatch_invoke_application(&mut self, member: &str, args: &[OmValue]) -> OmResult<OmValue> {
        self.focus_member_supported("Application", member, false)?;

        match member {
            "Quit" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Application.Quit does not accept arguments",
                    ));
                }
                let workbooks = self
                    .workbooks
                    .keys()
                    .copied()
                    .map(|handle| WorkbookHandle(ObjectHandle(handle)))
                    .collect::<Vec<_>>();
                for workbook in workbooks {
                    self.close_workbook(workbook)?;
                }
                Ok(OmValue::Empty)
            }
            "Calculate" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Application.Calculate does not accept arguments",
                    ));
                }
                self.calculate_all_open_workbooks()?;
                Ok(OmValue::Empty)
            }
            "CalculateFull" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Application.CalculateFull does not accept arguments",
                    ));
                }
                self.calculate_all_open_workbooks()?;
                Ok(OmValue::Empty)
            }
            "CalculateFullRebuild" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Application.CalculateFullRebuild does not accept arguments",
                    ));
                }
                let workbooks = self
                    .workbooks
                    .keys()
                    .copied()
                    .map(|handle| WorkbookHandle(ObjectHandle(handle)))
                    .collect::<Vec<_>>();
                for workbook in workbooks {
                    if self.invalidate_workbook_calc_chain(workbook)? {
                        self.runtime_workbook_mut(workbook)?.dirty = true;
                    }
                    self.calculate_workbook_formulas(workbook)?;
                }
                Ok(OmValue::Empty)
            }
            "Evaluate" => {
                let expression = coerce_evaluate_expression_arg(args, "Application.Evaluate")?;
                let Some(active_workbook) = self.active_workbook else {
                    return Err(OmError::invalid_state("application has no active workbook"));
                };
                let sheet_id = self.active_sheet_id(active_workbook)?;
                self.evaluate_formula_expression(
                    active_workbook,
                    sheet_id,
                    expression,
                    "Application.Evaluate",
                )
            }
            "Goto" => {
                if args.len() > 2 {
                    return Err(OmError::invalid_argument(
                        "Application.Goto accepts at most reference and scroll arguments",
                    ));
                }

                match args.get(1) {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => {}
                    Some(OmValue::Bool(_)) => {}
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Application.Goto scroll expects a boolean when provided",
                        ));
                    }
                }

                let (workbook, range) = match args.first() {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => {
                        self.last_goto_range.clone().ok_or_else(|| {
                            OmError::invalid_state(
                                "Application.Goto without a reference requires a prior Application.Goto selection",
                            )
                        })?
                    }
                    Some(OmValue::Text(reference)) => {
                        self.resolve_application_range_text(reference)?
                    }
                    Some(OmValue::Object(handle)) => match self.runtime_object(*handle)? {
                        RuntimeObjectKind::Range {
                            workbook, range, ..
                        } => (workbook, range),
                        _ => {
                            return Err(OmError::type_mismatch(
                                "Application.Goto expects a Range object or A1-style text reference",
                            ));
                        }
                    },
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Application.Goto expects a Range object or A1-style text reference",
                        ));
                    }
                };

                self.ensure_range_set_targets_grid_worksheets(
                    workbook,
                    &range,
                    "Application.Goto",
                )?;
                let (sheet_id, rect) = Self::range_set_first_area(&range)?;
                self.set_range_selection(workbook, range.clone(), "Application.Goto")?;
                self.last_goto_selection = Some(RuntimeSelection {
                    workbook,
                    sheet_id,
                    rect,
                });
                self.last_goto_range = Some((workbook, range));
                Ok(OmValue::Empty)
            }
            "Range" => match args {
                [OmValue::Text(reference)] => {
                    let (workbook, range) = self.resolve_application_range_text(reference)?;
                    self.ensure_range_set_targets_grid_worksheets(
                        workbook,
                        &range,
                        "Application.Range",
                    )?;
                    self.remember_range_selection(workbook, &range, "Application.Range")?;
                    Ok(OmValue::Object(
                        self.register_range_set_handle(workbook, range).0,
                    ))
                }
                _ => {
                    let Some(active_workbook) = self.active_workbook else {
                        return Err(OmError::invalid_state("application has no active workbook"));
                    };
                    let sheet_id = self.active_sheet_id(active_workbook)?;
                    self.dispatch_invoke_worksheet(active_workbook, sheet_id, "Range", args)
                }
            },
            "Intersect" => {
                if !(2..=30).contains(&args.len()) {
                    return Err(OmError::invalid_argument(
                        "Application.Intersect expects 2 to 30 range arguments",
                    ));
                }

                let parse_range = |value: &OmValue,
                                   label: &str,
                                   runtime: &ExcelRuntime|
                 -> OmResult<(WorkbookHandle, RangeSet)> {
                    match value {
                        OmValue::Object(handle) => match runtime.runtime_object(*handle)? {
                            RuntimeObjectKind::Range {
                                workbook, range, ..
                            } => Ok((workbook, range)),
                            _ => Err(OmError::type_mismatch(format!(
                                "Application.Intersect {label} expects range objects"
                            ))),
                        },
                        _ => Err(OmError::type_mismatch(format!(
                            "Application.Intersect {label} expects range objects"
                        ))),
                    }
                };

                let (workbook, first_range) = parse_range(&args[0], "Arg1", self)?;
                let (sheet_id, mut current_rects) =
                    Self::range_set_single_sheet_rects(&first_range)?;
                for (index, arg) in args.iter().enumerate().skip(1) {
                    let (next_workbook, next_range) =
                        parse_range(arg, &format!("Arg{}", index + 1), self)?;
                    let (next_sheet_id, next_rects) =
                        Self::range_set_single_sheet_rects(&next_range)?;
                    if next_workbook != workbook || next_sheet_id != sheet_id {
                        return Err(OmError::invalid_argument(
                            "Application.Intersect expects ranges from the same worksheet",
                        ));
                    }
                    let mut intersections = Vec::new();
                    for left in &current_rects {
                        for right in &next_rects {
                            let row_first = left.row_first.max(right.row_first);
                            let row_last = left.row_last.min(right.row_last);
                            let col_first = left.col_first.max(right.col_first);
                            let col_last = left.col_last.min(right.col_last);
                            if row_first <= row_last && col_first <= col_last {
                                intersections.push(Rect {
                                    row_first,
                                    row_last,
                                    col_first,
                                    col_last,
                                });
                            }
                        }
                    }
                    current_rects = intersections;
                    if current_rects.is_empty() {
                        return Ok(OmValue::Empty);
                    }
                }

                let workbook_id = self.workbook_model(workbook)?.id;
                let areas = current_rects
                    .into_iter()
                    .map(|rect| RangeArea::new(SheetScope::Single(sheet_id), rect))
                    .collect::<OmResult<Vec<_>>>()?;

                Ok(OmValue::Object(
                    self.register_range_set_handle(workbook, RangeSet::new(workbook_id, areas)?)
                        .0,
                ))
            }
            "Union" => {
                if !(2..=30).contains(&args.len()) {
                    return Err(OmError::invalid_argument(
                        "Application.Union expects 2 to 30 range arguments",
                    ));
                }

                let parse_range = |value: &OmValue,
                                   label: &str,
                                   runtime: &ExcelRuntime|
                 -> OmResult<(WorkbookHandle, RangeSet)> {
                    match value {
                        OmValue::Object(handle) => match runtime.runtime_object(*handle)? {
                            RuntimeObjectKind::Range {
                                workbook, range, ..
                            } => Ok((workbook, range)),
                            _ => Err(OmError::type_mismatch(format!(
                                "Application.Union {label} expects range objects"
                            ))),
                        },
                        _ => Err(OmError::type_mismatch(format!(
                            "Application.Union {label} expects range objects"
                        ))),
                    }
                };

                let (workbook, first_range) = parse_range(&args[0], "Arg1", self)?;
                let (sheet_id, first_rects) = Self::range_set_single_sheet_rects(&first_range)?;
                let workbook_id = self.workbook_model(workbook)?.id;
                let mut areas = first_rects
                    .into_iter()
                    .map(|rect| RangeArea::new(SheetScope::Single(sheet_id), rect))
                    .collect::<OmResult<Vec<_>>>()?;
                for (index, arg) in args.iter().enumerate().skip(1) {
                    let (next_workbook, next_range) =
                        parse_range(arg, &format!("Arg{}", index + 1), self)?;
                    let (next_sheet_id, next_rects) =
                        Self::range_set_single_sheet_rects(&next_range)?;
                    if next_workbook != workbook || next_sheet_id != sheet_id {
                        return Err(OmError::invalid_argument(
                            "Application.Union expects ranges from the same worksheet",
                        ));
                    }
                    for rect in next_rects {
                        areas.push(RangeArea::new(SheetScope::Single(sheet_id), rect)?);
                    }
                }

                Ok(OmValue::Object(
                    self.register_range_set_handle(workbook, RangeSet::new(workbook_id, areas)?)
                        .0,
                ))
            }
            _ => Err(OmError::unsupported(format!(
                "Application.{member} is not implemented as a method"
            ))),
        }
    }

    fn dispatch_invoke_workbooks(&mut self, member: &str, args: &[OmValue]) -> OmResult<OmValue> {
        self.focus_member_supported("Workbooks", member, false)?;

        match member {
            "Add" => {
                if args.len() > 1 {
                    return Err(OmError::invalid_argument(
                        "Workbooks.Add accepts at most a single Template argument",
                    ));
                }
                let workbook = match args.first() {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => {
                        self.create_workbook()?
                    }
                    Some(OmValue::Number(template)) => {
                        let template = RuntimeSheetTemplate::from_xl_wba_template(*template)
                            .ok_or_else(|| {
                                OmError::unsupported(
                                    "Workbooks.Add supports numeric XlWBATemplate values xlWBATWorksheet, xlWBATChart, xlWBATExcel4MacroSheet, and xlWBATExcel4IntlMacroSheet",
                                )
                            })?;
                        self.create_workbook_from_template_kind(template)?
                    }
                    Some(OmValue::Text(path)) => {
                        let workbook_name = self.allocate_created_workbook_name();
                        self.open_detached_workbook_from_path(path, Some(workbook_name))?
                    }
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Workbooks.Add Template expects an XlWBATemplate numeric value or template path when provided",
                        ));
                    }
                };
                Ok(OmValue::Object(workbook.0))
            }
            "Open" => {
                if args.is_empty() || args.len() > 15 {
                    return Err(OmError::invalid_argument(
                        "Workbooks.Open expects Filename and up to 14 optional arguments",
                    ));
                }
                let path = match &args[0] {
                    OmValue::Text(path) => path,
                    _ => {
                        return Err(OmError::type_mismatch(
                            "Workbooks.Open expects a string filename",
                        ));
                    }
                };
                match args.get(1) {
                    None => {}
                    Some(value) if om_value_is_omitted(value) => {}
                    Some(OmValue::Bool(_)) => {}
                    Some(OmValue::Number(value)) => {
                        if !value.is_finite()
                            || value.fract() != 0.0
                            || *value < i32::MIN as f64
                            || *value > i32::MAX as f64
                        {
                            return Err(OmError::invalid_argument(
                                "Workbooks.Open UpdateLinks expects an integer numeric value when provided",
                            ));
                        }
                    }
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Workbooks.Open UpdateLinks expects a boolean or numeric value when provided",
                        ));
                    }
                }
                let read_only = match args.get(2) {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => false,
                    Some(OmValue::Bool(read_only)) => *read_only,
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Workbooks.Open ReadOnly expects a boolean value when provided",
                        ));
                    }
                };
                validate_optional_integer_arg(args, 3, "Workbooks.Open Format")?;
                validate_optional_text_arg(args, 4, "Workbooks.Open Password")?;
                validate_optional_text_arg(args, 5, "Workbooks.Open WriteResPassword")?;
                validate_optional_bool_arg(args, 6, "Workbooks.Open IgnoreReadOnlyRecommended")?;
                validate_optional_integer_arg(args, 7, "Workbooks.Open Origin")?;
                validate_optional_text_arg(args, 8, "Workbooks.Open Delimiter")?;
                validate_optional_bool_arg(args, 9, "Workbooks.Open Editable")?;
                validate_optional_bool_arg(args, 10, "Workbooks.Open Notify")?;
                validate_optional_integer_arg(args, 11, "Workbooks.Open Converter")?;
                validate_optional_bool_arg(args, 12, "Workbooks.Open AddToMru")?;
                validate_optional_bool_arg(args, 13, "Workbooks.Open Local")?;
                validate_optional_integer_arg(args, 14, "Workbooks.Open CorruptLoad")?;
                let bytes = fs::read(path).map_err(|error| {
                    OmError::new(
                        OmErrorCode::Io,
                        format!("failed to read workbook {path}: {error}"),
                    )
                })?;
                let display_name = Path::new(path)
                    .file_name()
                    .and_then(|value| value.to_str())
                    .map(str::to_owned);
                Ok(OmValue::Object(
                    self.open_workbook_with_display_name(
                        OpenWorkbookSpec {
                            bytes,
                            format_hint: None,
                            profile: ExcelProfile::Excel365,
                            read_only,
                        },
                        display_name,
                        Some(PathBuf::from(path)),
                    )?
                    .0,
                ))
            }
            "Item" => self.resolve_workbook_item(args),
            "Close" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Workbooks.Close does not accept arguments",
                    ));
                }
                let workbook_handles = self
                    .workbooks
                    .keys()
                    .copied()
                    .map(|id| WorkbookHandle(ObjectHandle(id)))
                    .collect::<Vec<_>>();
                for workbook in workbook_handles {
                    self.close_workbook(workbook)?;
                }
                Ok(OmValue::Empty)
            }
            _ => Err(OmError::unsupported(format!(
                "Workbooks.{member} is not implemented as a method"
            ))),
        }
    }

    fn dispatch_invoke_sheet_collection(
        &mut self,
        workbook: WorkbookHandle,
        collection_kind: RuntimeSheetCollectionKind,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        self.focus_member_supported("Worksheets", member, false)?;

        let collection_name = collection_kind.member_name();
        match member {
            "Add" if collection_kind != RuntimeSheetCollectionKind::Charts => {
                Ok(OmValue::Object(self.add_worksheet(workbook, args)?.0))
            }
            "Add" => {
                if args.len() > 3 {
                    return Err(OmError::invalid_argument(
                        "Charts.Add accepts at most Before, After, and Count arguments",
                    ));
                }
                let add_args = [
                    args.first().cloned().unwrap_or(OmValue::Missing),
                    args.get(1).cloned().unwrap_or(OmValue::Missing),
                    args.get(2).cloned().unwrap_or(OmValue::Missing),
                    OmValue::Number(f64::from(XL_SHEET_TYPE_CHART)),
                ];
                let added_sheet = self.add_worksheet(workbook, &add_args)?;
                let RuntimeObjectKind::Worksheet { sheet_id, .. } =
                    self.runtime_object(added_sheet.0)?
                else {
                    return Err(OmError::new(
                        OmErrorCode::InvalidState,
                        "Charts.Add did not create a chart sheet",
                    ));
                };
                let chart_id = self
                    .runtime_workbook(workbook)?
                    .loaded
                    .state
                    .chart_sheets
                    .get(&sheet_id)
                    .map(|binding| binding.chart_id)
                    .ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::InvalidState,
                            "Charts.Add created a sheet without a chart binding",
                        )
                    })?;
                Ok(OmValue::Object(
                    self.register_chart_handle(workbook, chart_id),
                ))
            }
            "Delete" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(format!(
                        "{collection_name}.Delete does not accept arguments"
                    )));
                }
                let sheet_ids = self.sheet_collection_ids_in_order(workbook, collection_kind)?;
                if sheet_ids.is_empty() {
                    return Ok(OmValue::Bool(true));
                }
                self.ensure_sheet_block_can_be_deleted_from_workbook(
                    workbook,
                    sheet_ids.as_slice(),
                )?;
                if self.display_alerts {
                    return Ok(OmValue::Bool(false));
                }
                for sheet_id in sheet_ids {
                    self.delete_worksheet(workbook, sheet_id, false)?;
                }
                Ok(OmValue::Bool(true))
            }
            "Copy" => {
                if args.len() > 2 {
                    return Err(OmError::invalid_argument(format!(
                        "{collection_name}.Copy accepts at most Before and After arguments"
                    )));
                }
                let sheet_ids = self.sheet_collection_ids_in_order(workbook, collection_kind)?;
                if sheet_ids.is_empty() {
                    return Err(OmError::new(
                        OmErrorCode::NotFound,
                        format!("{collection_name} collection is empty"),
                    ));
                }
                if let Some((target_workbook, base_insertion_index)) = self
                    .worksheet_placement_target(
                        workbook,
                        args.first(),
                        args.get(1),
                        &format!("{collection_name}.Copy"),
                    )?
                {
                    let copied_sheet_ids = self.copy_sheet_block_to_workbook(
                        workbook,
                        sheet_ids.as_slice(),
                        target_workbook,
                        base_insertion_index,
                        &format!("{collection_name}.Copy"),
                    )?;
                    if let Some(active_sheet_id) = copied_sheet_ids.first().copied() {
                        self.set_selection(
                            target_workbook,
                            active_sheet_id,
                            Rect::single_cell(1, 1),
                        );
                    }
                    return Ok(OmValue::Empty);
                }

                self.create_workbook_from_sheet_block(
                    workbook,
                    sheet_ids.as_slice(),
                    &format!("{collection_name}.Copy"),
                )?;
                Ok(OmValue::Empty)
            }
            "Move" => {
                if args.len() > 2 {
                    return Err(OmError::invalid_argument(format!(
                        "{collection_name}.Move accepts at most Before and After arguments"
                    )));
                }
                let sheet_ids = self.sheet_collection_ids_in_order(workbook, collection_kind)?;
                if sheet_ids.is_empty() {
                    return Err(OmError::new(
                        OmErrorCode::NotFound,
                        format!("{collection_name} collection is empty"),
                    ));
                }
                let placement_target = self.worksheet_placement_target(
                    workbook,
                    args.first(),
                    args.get(1),
                    &format!("{collection_name}.Move"),
                )?;
                let (source_read_only, source_sheet_count) = {
                    let runtime = self.runtime_workbook(workbook)?;
                    (runtime.read_only, runtime.loaded.state.worksheets.len())
                };
                if source_read_only {
                    return Err(OmError::new(
                        OmErrorCode::InvalidState,
                        "cannot modify a read-only workbook",
                    ));
                }

                if let Some((target_workbook, base_insertion_index)) = placement_target {
                    if target_workbook == workbook {
                        let moving_sheet_ids = sheet_ids.iter().copied().collect::<BTreeSet<_>>();
                        let active_sheet_id = sheet_ids[0];
                        {
                            let runtime = self.runtime_workbook_mut(workbook)?;
                            let target_index =
                                base_insertion_index.min(runtime.loaded.state.worksheets.len());
                            let removed_before = runtime
                                .loaded
                                .state
                                .worksheets
                                .iter()
                                .take(target_index)
                                .filter(|worksheet| moving_sheet_ids.contains(&worksheet.id))
                                .count();
                            let mut moving_sheets = Vec::with_capacity(sheet_ids.len());
                            let mut remaining_sheets = Vec::with_capacity(
                                runtime
                                    .loaded
                                    .state
                                    .worksheets
                                    .len()
                                    .saturating_sub(sheet_ids.len()),
                            );
                            for worksheet in runtime.loaded.state.worksheets.drain(..) {
                                if moving_sheet_ids.contains(&worksheet.id) {
                                    moving_sheets.push(worksheet);
                                } else {
                                    remaining_sheets.push(worksheet);
                                }
                            }
                            if moving_sheets.is_empty() {
                                return Err(OmError::new(
                                    OmErrorCode::InvalidState,
                                    format!("{collection_name}.Move found no sheets to move"),
                                ));
                            }
                            let adjusted_index = target_index
                                .saturating_sub(removed_before)
                                .min(remaining_sheets.len());
                            for (offset, worksheet) in moving_sheets.into_iter().enumerate() {
                                remaining_sheets.insert(adjusted_index + offset, worksheet);
                            }
                            runtime.loaded.state.worksheets = remaining_sheets;
                            let workbook_xml = runtime
                                .loaded
                                .package
                                .part(WORKBOOK_PART_NAME)
                                .ok_or_else(|| {
                                    OmError::new(
                                        OmErrorCode::Parse,
                                        format!("workbook package is missing {WORKBOOK_PART_NAME}"),
                                    )
                                })?
                                .bytes
                                .clone();
                            runtime.loaded.package.replace_part_bytes(
                                WORKBOOK_PART_NAME,
                                reorder_workbook_sheet_entries(
                                    workbook_xml.as_slice(),
                                    &runtime.loaded.state.worksheets,
                                )?,
                            )?;
                            runtime.dirty = true;
                        }
                        self.set_selection(workbook, active_sheet_id, Rect::single_cell(1, 1));
                        return Ok(OmValue::Empty);
                    }

                    let copied_sheet_ids = self.copy_sheet_block_to_workbook(
                        workbook,
                        sheet_ids.as_slice(),
                        target_workbook,
                        base_insertion_index,
                        &format!("{collection_name}.Move"),
                    )?;
                    if source_sheet_count > sheet_ids.len() {
                        self.ensure_sheet_block_can_be_deleted_from_workbook(
                            workbook,
                            sheet_ids.as_slice(),
                        )?;
                        for sheet_id in sheet_ids {
                            self.delete_worksheet(workbook, sheet_id, false)?;
                        }
                    } else {
                        self.close_workbook(workbook)?;
                    }
                    if let Some(active_sheet_id) = copied_sheet_ids.first().copied() {
                        self.set_selection(
                            target_workbook,
                            active_sheet_id,
                            Rect::single_cell(1, 1),
                        );
                    }
                    return Ok(OmValue::Empty);
                }

                let (moved_workbook, moved_sheet_ids) = self.create_workbook_from_sheet_block(
                    workbook,
                    sheet_ids.as_slice(),
                    &format!("{collection_name}.Move"),
                )?;
                if source_sheet_count > sheet_ids.len() {
                    self.ensure_sheet_block_can_be_deleted_from_workbook(
                        workbook,
                        sheet_ids.as_slice(),
                    )?;
                    for sheet_id in sheet_ids {
                        self.delete_worksheet(workbook, sheet_id, false)?;
                    }
                } else {
                    self.close_workbook(workbook)?;
                }
                if let Some(active_sheet_id) = moved_sheet_ids.first().copied() {
                    self.set_selection(moved_workbook, active_sheet_id, Rect::single_cell(1, 1));
                }
                Ok(OmValue::Empty)
            }
            "PrintPreview" | "PrintOut" => {
                match member {
                    "PrintPreview" => validate_print_preview_args(args, collection_name)?,
                    "PrintOut" => validate_print_out_args(args, collection_name)?,
                    _ => unreachable!("sheet collection print method branch"),
                }
                if collection_kind == RuntimeSheetCollectionKind::Charts {
                    let chart_ids = {
                        let runtime = self.runtime_workbook(workbook)?;
                        runtime
                            .loaded
                            .state
                            .worksheets
                            .iter()
                            .filter(|worksheet| worksheet.kind == SheetKind::ChartSheet)
                            .map(|worksheet| {
                                runtime
                                    .loaded
                                    .state
                                    .chart_sheets
                                    .get(&worksheet.id)
                                    .map(|binding| binding.chart_id)
                                    .ok_or_else(|| {
                                        OmError::new(
                                            OmErrorCode::InvalidState,
                                            "chart sheet is missing a chart binding",
                                        )
                                    })
                            })
                            .collect::<OmResult<Vec<_>>>()?
                    };
                    for chart_id in chart_ids {
                        self.chart_model(workbook, chart_id)?;
                    }
                } else {
                    self.runtime_workbook(workbook)?;
                }
                Ok(OmValue::Empty)
            }
            "Select" => {
                if args.len() > 1 {
                    return Err(OmError::invalid_argument(format!(
                        "{collection_name}.Select accepts at most a Replace argument"
                    )));
                }
                if let Some(value) = args.first()
                    && !om_value_is_omitted(value)
                {
                    coerce_optional_bool_arg(
                        value,
                        true,
                        &format!("{collection_name}.Select Replace"),
                    )?;
                }
                let sheet_id = self
                    .sheet_collection_ids_in_order(workbook, collection_kind)?
                    .first()
                    .copied()
                    .ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::NotFound,
                            format!("{collection_name} collection is empty"),
                        )
                    })?;
                self.ensure_worksheet_visible(
                    workbook,
                    sheet_id,
                    &format!("{collection_name}.Select"),
                )?;
                self.set_selection(workbook, sheet_id, Rect::single_cell(1, 1));
                Ok(OmValue::Empty)
            }
            "Item" => self.resolve_sheet_collection_item(workbook, collection_kind, args),
            _ => Err(OmError::unsupported(format!(
                "{collection_name}.{member} is not implemented as a method"
            ))),
        }
    }

    fn sheet_collection_ids_in_order(
        &self,
        workbook: WorkbookHandle,
        collection_kind: RuntimeSheetCollectionKind,
    ) -> OmResult<Vec<SheetId>> {
        let runtime = self.runtime_workbook(workbook)?;
        Ok(runtime
            .loaded
            .state
            .worksheets
            .iter()
            .filter(|worksheet| collection_kind.includes(worksheet.kind))
            .map(|worksheet| worksheet.id)
            .collect())
    }

    fn ensure_sheet_block_can_be_deleted_from_workbook(
        &self,
        workbook: WorkbookHandle,
        sheet_ids: &[SheetId],
    ) -> OmResult<()> {
        let runtime = self.runtime_workbook(workbook)?;
        if runtime.read_only {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot modify a read-only workbook",
            ));
        }
        if sheet_ids.is_empty() {
            return Ok(());
        }
        let deleting_sheet_ids = sheet_ids.iter().copied().collect::<BTreeSet<_>>();
        if runtime.loaded.state.worksheets.len() <= deleting_sheet_ids.len() {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot delete every sheet in a workbook",
            ));
        }
        let visible_sheet_remains = runtime.loaded.state.worksheets.iter().any(|worksheet| {
            worksheet.visibility == SheetVisibility::Visible
                && !deleting_sheet_ids.contains(&worksheet.id)
        });
        if !visible_sheet_remains {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot delete the last visible worksheet in a workbook",
            ));
        }
        Ok(())
    }

    fn copy_sheet_block_to_workbook(
        &mut self,
        workbook: WorkbookHandle,
        sheet_ids: &[SheetId],
        target_workbook: WorkbookHandle,
        base_insertion_index: usize,
        operation: &str,
    ) -> OmResult<Vec<SheetId>> {
        let mut copied_sheet_ids = Vec::with_capacity(sheet_ids.len());
        for (offset, sheet_id) in sheet_ids.iter().copied().enumerate() {
            let insertion_index = base_insertion_index.checked_add(offset).ok_or_else(|| {
                OmError::invalid_argument(format!("{operation} target index is too large"))
            })?;
            let copied_sheet = self.copy_basic_worksheet_to_workbook(
                workbook,
                sheet_id,
                target_workbook,
                insertion_index,
            )?;
            let RuntimeObjectKind::Worksheet {
                sheet_id: copied_sheet_id,
                ..
            } = self.runtime_object(copied_sheet.0)?
            else {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    format!("{operation} did not create a sheet"),
                ));
            };
            copied_sheet_ids.push(copied_sheet_id);
        }
        Ok(copied_sheet_ids)
    }

    fn create_workbook_from_sheet_block(
        &mut self,
        workbook: WorkbookHandle,
        sheet_ids: &[SheetId],
        operation: &str,
    ) -> OmResult<(WorkbookHandle, Vec<SheetId>)> {
        let source_sheet_names = sheet_ids
            .iter()
            .copied()
            .map(|sheet_id| {
                self.worksheet_model(workbook, sheet_id)
                    .map(|worksheet| worksheet.name.clone())
            })
            .collect::<OmResult<Vec<_>>>()?;
        let copied_workbook = self.create_workbook()?;
        let default_sheet_id = self
            .runtime_workbook(copied_workbook)?
            .loaded
            .state
            .worksheets
            .first()
            .map(|worksheet| worksheet.id)
            .ok_or_else(|| OmError::new(OmErrorCode::InvalidState, "workbook has no worksheets"))?;
        let base_insertion_index = self
            .runtime_workbook(copied_workbook)?
            .loaded
            .state
            .worksheets
            .len();
        let copied_sheet_ids = self.copy_sheet_block_to_workbook(
            workbook,
            sheet_ids,
            copied_workbook,
            base_insertion_index,
            operation,
        )?;
        self.delete_worksheet(copied_workbook, default_sheet_id, false)?;
        for (copied_sheet_id, source_name) in copied_sheet_ids
            .iter()
            .copied()
            .zip(source_sheet_names.into_iter())
        {
            let copied_sheet = self.register_worksheet_handle(copied_workbook, copied_sheet_id);
            self.dispatch_set(copied_sheet.0, "Name", OmValue::Text(source_name), &[])?;
        }
        let active_sheet_id = copied_sheet_ids
            .first()
            .copied()
            .ok_or_else(|| OmError::new(OmErrorCode::InvalidState, "no sheets copied"))?;
        self.set_selection(copied_workbook, active_sheet_id, Rect::single_cell(1, 1));
        Ok((copied_workbook, copied_sheet_ids))
    }

    fn worksheet_placement_index(
        &self,
        workbook: WorkbookHandle,
        before: Option<&OmValue>,
        after: Option<&OmValue>,
        operation: &str,
    ) -> OmResult<Option<usize>> {
        if matches!(before, Some(value) if !om_value_is_omitted(value))
            && matches!(after, Some(value) if !om_value_is_omitted(value))
        {
            return Err(OmError::invalid_argument(format!(
                "{operation} cannot specify both Before and After"
            )));
        }
        if let Some(value) = before.filter(|value| !om_value_is_omitted(value)) {
            let worksheet_index = match value {
                OmValue::Object(handle) => {
                    let (target_workbook, sheet_id) =
                        self.placement_sheet_object(*handle, operation, "Before")?;
                    if target_workbook != workbook {
                        return Err(OmError::invalid_argument(format!(
                            "{operation} Before sheet must belong to the same workbook"
                        )));
                    }
                    self.runtime_workbook(workbook)?
                        .loaded
                        .state
                        .worksheets
                        .iter()
                        .position(|worksheet| worksheet.id == sheet_id)
                }
                OmValue::Number(index) => {
                    let label = format!("{operation} Before index");
                    let index = coerce_positive_index(*index, &label)?;
                    Some(index as usize - 1)
                }
                OmValue::Text(name) => self
                    .runtime_workbook(workbook)?
                    .loaded
                    .state
                    .worksheets
                    .iter()
                    .position(|worksheet| worksheet.name.eq_ignore_ascii_case(name)),
                _ => {
                    return Err(OmError::type_mismatch(format!(
                        "{operation} Before expects a Worksheet object, numeric index, or worksheet name when provided"
                    )));
                }
            };
            return worksheet_index
                .map(Some)
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"));
        }
        if let Some(value) = after.filter(|value| !om_value_is_omitted(value)) {
            let worksheet_index = match value {
                OmValue::Object(handle) => {
                    let (target_workbook, sheet_id) =
                        self.placement_sheet_object(*handle, operation, "After")?;
                    if target_workbook != workbook {
                        return Err(OmError::invalid_argument(format!(
                            "{operation} After sheet must belong to the same workbook"
                        )));
                    }
                    self.runtime_workbook(workbook)?
                        .loaded
                        .state
                        .worksheets
                        .iter()
                        .position(|worksheet| worksheet.id == sheet_id)
                }
                OmValue::Number(index) => {
                    let label = format!("{operation} After index");
                    let index = coerce_positive_index(*index, &label)?;
                    Some(index as usize - 1)
                }
                OmValue::Text(name) => self
                    .runtime_workbook(workbook)?
                    .loaded
                    .state
                    .worksheets
                    .iter()
                    .position(|worksheet| worksheet.name.eq_ignore_ascii_case(name)),
                _ => {
                    return Err(OmError::type_mismatch(format!(
                        "{operation} After expects a Worksheet object, numeric index, or worksheet name when provided"
                    )));
                }
            };
            return worksheet_index
                .map(|index| Some(index + 1))
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"));
        }

        Ok(None)
    }

    fn worksheet_placement_target(
        &self,
        workbook: WorkbookHandle,
        before: Option<&OmValue>,
        after: Option<&OmValue>,
        operation: &str,
    ) -> OmResult<Option<(WorkbookHandle, usize)>> {
        if matches!(before, Some(value) if !om_value_is_omitted(value))
            && matches!(after, Some(value) if !om_value_is_omitted(value))
        {
            return Err(OmError::invalid_argument(format!(
                "{operation} cannot specify both Before and After"
            )));
        }
        if let Some(value) = before.filter(|value| !om_value_is_omitted(value)) {
            let (target_workbook, worksheet_index) = match value {
                OmValue::Object(handle) => {
                    let (target_workbook, sheet_id) =
                        self.placement_sheet_object(*handle, operation, "Before")?;
                    (
                        target_workbook,
                        self.runtime_workbook(target_workbook)?
                            .loaded
                            .state
                            .worksheets
                            .iter()
                            .position(|worksheet| worksheet.id == sheet_id),
                    )
                }
                OmValue::Number(index) => {
                    let label = format!("{operation} Before index");
                    let index = coerce_positive_index(*index, &label)?;
                    (workbook, Some(index as usize - 1))
                }
                OmValue::Text(name) => (
                    workbook,
                    self.runtime_workbook(workbook)?
                        .loaded
                        .state
                        .worksheets
                        .iter()
                        .position(|worksheet| worksheet.name.eq_ignore_ascii_case(name)),
                ),
                _ => {
                    return Err(OmError::type_mismatch(format!(
                        "{operation} Before expects a Worksheet object, numeric index, or worksheet name when provided"
                    )));
                }
            };
            return worksheet_index
                .map(|index| Some((target_workbook, index)))
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"));
        }
        if let Some(value) = after.filter(|value| !om_value_is_omitted(value)) {
            let (target_workbook, worksheet_index) = match value {
                OmValue::Object(handle) => {
                    let (target_workbook, sheet_id) =
                        self.placement_sheet_object(*handle, operation, "After")?;
                    (
                        target_workbook,
                        self.runtime_workbook(target_workbook)?
                            .loaded
                            .state
                            .worksheets
                            .iter()
                            .position(|worksheet| worksheet.id == sheet_id),
                    )
                }
                OmValue::Number(index) => {
                    let label = format!("{operation} After index");
                    let index = coerce_positive_index(*index, &label)?;
                    (workbook, Some(index as usize - 1))
                }
                OmValue::Text(name) => (
                    workbook,
                    self.runtime_workbook(workbook)?
                        .loaded
                        .state
                        .worksheets
                        .iter()
                        .position(|worksheet| worksheet.name.eq_ignore_ascii_case(name)),
                ),
                _ => {
                    return Err(OmError::type_mismatch(format!(
                        "{operation} After expects a Worksheet object, numeric index, or worksheet name when provided"
                    )));
                }
            };
            return worksheet_index
                .map(|index| Some((target_workbook, index + 1)))
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"));
        }

        Ok(None)
    }

    fn placement_sheet_object(
        &self,
        handle: ObjectHandle,
        operation: &str,
        position_label: &str,
    ) -> OmResult<(WorkbookHandle, SheetId)> {
        match self.runtime_object(handle)? {
            RuntimeObjectKind::Worksheet { workbook, sheet_id } => Ok((workbook, sheet_id)),
            RuntimeObjectKind::Chart {
                workbook, chart_id, ..
            } => {
                let Some(sheet_id) = self.chart_sheet_id_for_chart(workbook, chart_id)? else {
                    return Err(OmError::type_mismatch(format!(
                        "{operation} {position_label} expects a Worksheet or chart sheet object, numeric index, or worksheet name when provided"
                    )));
                };
                Ok((workbook, sheet_id))
            }
            _ => Err(OmError::type_mismatch(format!(
                "{operation} {position_label} expects a Worksheet or chart sheet object, numeric index, or worksheet name when provided"
            ))),
        }
    }

    fn add_worksheet(
        &mut self,
        workbook: WorkbookHandle,
        args: &[OmValue],
    ) -> OmResult<WorksheetHandle> {
        if args.len() > 4 {
            return Err(OmError::invalid_argument(
                "Worksheets.Add accepts at most Before, After, Count, and Type arguments",
            ));
        }
        let count = match args.get(2) {
            None => 1usize,
            Some(value) => match value {
                OmValue::Missing | OmValue::Empty | OmValue::Null => 1usize,
                OmValue::Number(count)
                    if count.is_finite()
                        && count.fract() == 0.0
                        && *count >= 1.0
                        && *count <= usize::MAX as f64 =>
                {
                    *count as usize
                }
                OmValue::Number(_) => {
                    return Err(OmError::invalid_argument(
                        "Worksheets.Add Count must be a positive integer",
                    ));
                }
                _ => {
                    return Err(OmError::type_mismatch(
                        "Worksheets.Add Count expects a numeric value when provided",
                    ));
                }
            },
        };
        let (template_path, sheet_template) = match args.get(3) {
            None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => {
                (None, RuntimeSheetTemplate::Worksheet)
            }
            Some(OmValue::Number(sheet_type)) => {
                let sheet_template = RuntimeSheetTemplate::from_xl_sheet_type(*sheet_type)
                    .ok_or_else(|| {
                        OmError::unsupported(
                            "Worksheets.Add supports numeric XlSheetType values xlWorksheet, xlChart, xlExcel4MacroSheet, and xlExcel4IntlMacroSheet",
                        )
                    })?;
                (None, sheet_template)
            }
            Some(OmValue::Text(path)) => (Some(path.as_str()), RuntimeSheetTemplate::Worksheet),
            Some(_) => {
                return Err(OmError::type_mismatch(
                    "Worksheets.Add Type expects an XlSheetType numeric value or template path when provided",
                ));
            }
        };

        let base_insertion_index = self
            .worksheet_placement_index(workbook, args.first(), args.get(1), "Worksheets.Add")?
            .unwrap_or_else(|| {
                self.selection
                    .filter(|selection| selection.workbook == workbook)
                    .and_then(|selection| {
                        self.runtime_workbook(workbook)
                            .ok()?
                            .loaded
                            .state
                            .worksheets
                            .iter()
                            .position(|worksheet| worksheet.id == selection.sheet_id)
                    })
                    .unwrap_or(0)
            });

        if let Some(template_path) = template_path {
            let template_display_name = Path::new(template_path)
                .file_name()
                .and_then(|value| value.to_str())
                .map(str::to_owned);
            let template_workbook =
                self.open_detached_workbook_from_path(template_path, template_display_name)?;
            let result = (|| {
                let template_sheet_id = self
                    .runtime_workbook(template_workbook)?
                    .loaded
                    .state
                    .worksheets
                    .first()
                    .map(|worksheet| worksheet.id)
                    .ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::InvalidState,
                            "worksheet template workbook has no worksheets",
                        )
                    })?;
                let mut last_sheet = None;
                for offset in 0..count {
                    let insertion_index =
                        base_insertion_index.checked_add(offset).ok_or_else(|| {
                            OmError::invalid_argument("Worksheets.Add Count is too large")
                        })?;
                    last_sheet = Some(self.copy_basic_worksheet_to_workbook(
                        template_workbook,
                        template_sheet_id,
                        workbook,
                        insertion_index,
                    )?);
                }
                Ok(last_sheet.expect("Worksheets.Add count should be positive"))
            })();
            let close_result = self.close_workbook(template_workbook);
            return match (result, close_result) {
                (Ok(value), Ok(())) => Ok(value),
                (Ok(_), Err(error)) => Err(error),
                (Err(error), _) => Err(error),
            };
        }

        let mut last_sheet_id = None;
        for offset in 0..count {
            let insertion_index = base_insertion_index
                .checked_add(offset)
                .ok_or_else(|| OmError::invalid_argument("Worksheets.Add Count is too large"))?;
            let sheet_id = {
                let runtime = self.runtime_workbook_mut(workbook)?;
                if runtime.read_only {
                    return Err(OmError::new(
                        OmErrorCode::InvalidState,
                        "cannot modify a read-only workbook",
                    ));
                }

                let workbook_xml = runtime
                    .loaded
                    .package
                    .part(WORKBOOK_PART_NAME)
                    .ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::Parse,
                            format!("workbook package is missing {WORKBOOK_PART_NAME}"),
                        )
                    })?
                    .bytes
                    .clone();
                let content_types_xml = runtime
                    .loaded
                    .package
                    .part(CONTENT_TYPES_PART_NAME)
                    .ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::Parse,
                            format!("workbook package is missing {CONTENT_TYPES_PART_NAME}"),
                        )
                    })?
                    .bytes
                    .clone();
                let workbook_rels_part = runtime.loaded.package.part(WORKBOOK_RELS_PART_NAME);
                let workbook_rels_xml = workbook_rels_part
                    .map(|part| part.bytes.clone())
                    .unwrap_or_else(|| {
                        br#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
</Relationships>"#
                            .to_vec()
                    });
                let workbook_rels_compression = workbook_rels_part
                    .map(|part| part.compression)
                    .unwrap_or(CompressionMethod::Stored);
                let worksheet_compression = runtime
                    .loaded
                    .package
                    .parts()
                    .iter()
                    .find(|part| {
                        part.name.starts_with("xl/worksheets/") && part.name.ends_with(".xml")
                    })
                    .map(|part| part.compression)
                    .unwrap_or(CompressionMethod::Stored);

                let worksheet_name = unique_worksheet_name_with_prefix(
                    &runtime.loaded.state.worksheets,
                    sheet_template.worksheet_name_prefix(),
                );
                let sheet_id = SheetId(
                    runtime
                        .loaded
                        .state
                        .worksheets
                        .iter()
                        .map(|worksheet| worksheet.id.0)
                        .max()
                        .unwrap_or(0)
                        + 1,
                );
                let mut used_relationship_ids = BTreeSet::new();
                let mut reader = Reader::from_reader(Cursor::new(workbook_rels_xml.as_slice()));
                reader.config_mut().trim_text(true);
                let mut buffer = Vec::new();
                loop {
                    match reader.read_event_into(&mut buffer) {
                        Ok(Event::Start(element)) | Ok(Event::Empty(element))
                            if xml_local_name(element.name().as_ref()) == b"Relationship" =>
                        {
                            for attr in element.attributes() {
                                let attr = attr.map_err(runtime_xml_error)?;
                                if attr.key.as_ref() != b"Id" {
                                    continue;
                                }
                                used_relationship_ids.insert(
                                    attr.decode_and_unescape_value(reader.decoder())
                                        .map_err(runtime_xml_error)?
                                        .into_owned(),
                                );
                            }
                        }
                        Ok(Event::Eof) => break,
                        Ok(_) => {}
                        Err(error) => return Err(runtime_xml_error(error)),
                    }
                    buffer.clear();
                }

                let relationship_id = (1..)
                    .map(|index| format!("rId{index}"))
                    .find(|candidate| !used_relationship_ids.contains(candidate))
                    .expect("workbook relationship id");
                let sheet_kind = sheet_template.sheet_kind();
                let mut used_part_names = runtime
                    .loaded
                    .package
                    .parts()
                    .iter()
                    .map(|part| part.name.clone())
                    .collect::<BTreeSet<_>>();
                let (part_uri, sheet_part_content_type, workbook_relationship_type) =
                    if sheet_template == RuntimeSheetTemplate::Chart {
                        (
                            next_available_sequential_part_uri(
                                &mut used_part_names,
                                "xl/chartsheets/sheet",
                                ".xml",
                            ),
                            CHARTSHEET_PART_CONTENT_TYPE,
                            CHARTSHEET_RELATIONSHIP_TYPE,
                        )
                    } else {
                        (
                            next_available_sequential_part_uri(
                                &mut used_part_names,
                                "xl/worksheets/sheet",
                                ".xml",
                            ),
                            WORKSHEET_PART_CONTENT_TYPE,
                            WORKSHEET_RELATIONSHIP_TYPE,
                        )
                    };
                let relationship_target = part_uri
                    .strip_prefix("xl/")
                    .unwrap_or(part_uri.as_str())
                    .to_string();
                let mut content_types_xml = append_content_type_override_if_missing(
                    content_types_xml.as_slice(),
                    part_uri.as_str(),
                    sheet_part_content_type,
                )?;

                let mut chart_sheet_assets = None;
                let sheet_xml = if sheet_template == RuntimeSheetTemplate::Chart {
                    let chart_id = ChartId(
                        runtime
                            .loaded
                            .state
                            .charts
                            .keys()
                            .map(|chart_id| chart_id.0)
                            .max()
                            .unwrap_or_default()
                            + 1,
                    );
                    let drawing_id = DrawingId(
                        runtime
                            .loaded
                            .state
                            .drawings
                            .keys()
                            .map(|drawing_id| drawing_id.0)
                            .max()
                            .unwrap_or_default()
                            + 1,
                    );
                    let chart_object_id = ChartObjectId(
                        runtime
                            .loaded
                            .state
                            .drawings
                            .values()
                            .flat_map(|drawing| drawing.objects.iter())
                            .filter_map(|object| match object {
                                DrawingObjectModel::ChartFrame(chart_object) => {
                                    Some(chart_object.id.0)
                                }
                                DrawingObjectModel::UnsupportedRaw { id, .. } => Some(id.0),
                            })
                            .max()
                            .unwrap_or_default()
                            + 1,
                    );
                    let drawing_part_uri = next_available_sequential_part_uri(
                        &mut used_part_names,
                        "xl/drawings/drawing",
                        ".xml",
                    );
                    let drawing_rels_part_uri =
                        worksheet_relationships_part_uri_for(drawing_part_uri.as_str());
                    used_part_names.insert(drawing_rels_part_uri.clone());
                    let chart_part_uri = next_available_sequential_part_uri(
                        &mut used_part_names,
                        "xl/charts/chart",
                        ".xml",
                    );
                    let chartsheet_rels_part_uri =
                        worksheet_relationships_part_uri_for(part_uri.as_str());
                    used_part_names.insert(chartsheet_rels_part_uri.clone());
                    let sheet_drawing_relationship_id = "rId1";
                    let drawing_chart_relationship_id = "rId1";
                    let chart_object_name = "Chart 1";
                    let escaped_chart_object_name = partial_escape(chart_object_name).to_string();
                    let chart = ChartModel {
                        id: chart_id,
                        workbook_id: runtime.loaded.state.model.id,
                        chart_type: ChartType::Bar,
                        style: None,
                        series: Vec::new(),
                        title: None,
                        legend: None,
                        axes: default_chart_axes(),
                        vary_by_categories: None,
                        gap_width: None,
                        gap_depth: None,
                        overlap: None,
                        bar_shape: None,
                        has_series_lines: None,
                        has_drop_lines: None,
                        has_hi_lo_lines: None,
                        has_up_down_bars: None,
                        first_slice_angle: None,
                        explosion: None,
                        bubble_scale: None,
                        show_negative_bubbles: None,
                        has_3d_shading: None,
                        doughnut_hole_size: None,
                        second_plot_size: None,
                        size_represents: None,
                        split_type: None,
                        split_value: None,
                        data_labels: None,
                        data_table: None,
                        data_table_dirty: false,
                        show_data_labels_over_maximum: None,
                        display_blanks_as: None,
                        plot_visible_only: None,
                        view_3d: None,
                        view_3d_dirty: false,
                        rounded_corners: None,
                        protection: None,
                        protection_dirty: false,
                        raw_part_uri: Some(chart_part_uri.clone()),
                        dirty: false,
                    };
                    let drawing = DrawingModel {
                        id: drawing_id,
                        workbook_id: runtime.loaded.state.model.id,
                        host_sheet_id: sheet_id,
                        objects: vec![DrawingObjectModel::ChartFrame(ChartObjectModel {
                            id: chart_object_id,
                            anchor_attrs: BTreeMap::new(),
                            position_attrs: BTreeMap::new(),
                            extents_attrs: BTreeMap::new(),
                            marker_attrs: Default::default(),
                            graphic_frame_attrs: BTreeMap::new(),
                            graphic_frame_transform_xml: None,
                            graphic_data_attrs: BTreeMap::new(),
                            graphic_data_child_xmls: Vec::new(),
                            chart_reference_attrs: BTreeMap::new(),
                            non_visual_frame_attrs: BTreeMap::new(),
                            graphic_attrs: BTreeMap::new(),
                            non_visual_id: u32::try_from(chart_object_id.0).ok(),
                            non_visual_attrs: BTreeMap::new(),
                            non_visual_child_xml: None,
                            non_visual_frame_properties_xml: None,
                            client_data_attrs: BTreeMap::new(),
                            client_data_xml: None,
                            anchor_extension_xmls: Vec::new(),
                            workbook_id: runtime.loaded.state.model.id,
                            host_sheet_id: sheet_id,
                            chart_id,
                            name: chart_object_name.to_string(),
                            anchor: Some(DrawingAnchor::Absolute(AbsoluteAnchor {
                                position: PointEmu {
                                    x: office_common::Emu(0),
                                    y: office_common::Emu(0),
                                },
                                extents: SizeEmu {
                                    cx: office_common::Emu(5_486_400),
                                    cy: office_common::Emu(3_200_400),
                                },
                            })),
                            placement: ObjectPlacement::FreeFloating,
                            z_order: Some(0),
                            raw_binding: Some(format!(
                                "{drawing_part_uri}#{drawing_chart_relationship_id}"
                            )),
                            dirty: false,
                        })],
                        raw_part_uri: Some(drawing_part_uri.clone()),
                        dirty: false,
                    };

                    runtime.loaded.package.add_part(OpcPart {
                        name: chartsheet_rels_part_uri,
                        content_type: Some(RELATIONSHIPS_PART_CONTENT_TYPE.to_string()),
                        compression: worksheet_compression,
                        bytes: format!(
                            r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="{sheet_drawing_relationship_id}" Type="{DRAWING_RELATIONSHIP_TYPE}" Target="{}"/>
</Relationships>"#,
                            relative_relationship_target(&part_uri, &drawing_part_uri)
                        )
                        .into_bytes(),
                    })?;
                    runtime.loaded.package.add_part(OpcPart {
                        name: drawing_rels_part_uri,
                        content_type: Some(RELATIONSHIPS_PART_CONTENT_TYPE.to_string()),
                        compression: worksheet_compression,
                        bytes: format!(
                            r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="{drawing_chart_relationship_id}" Type="{CHART_RELATIONSHIP_TYPE}" Target="{}"/>
</Relationships>"#,
                            relative_relationship_target(&drawing_part_uri, &chart_part_uri)
                        )
                        .into_bytes(),
                    })?;
                    runtime.loaded.package.add_part(OpcPart {
                        name: drawing_part_uri.clone(),
                        content_type: Some(DRAWING_PART_CONTENT_TYPE.to_string()),
                        compression: worksheet_compression,
                        bytes: format!(
                            r#"<?xml version="1.0" encoding="UTF-8"?>
<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <xdr:absoluteAnchor>
    <xdr:pos x="0" y="0"/>
    <xdr:ext cx="5486400" cy="3200400"/>
    <xdr:graphicFrame>
      <xdr:nvGraphicFramePr><xdr:cNvPr id="{}" name="{escaped_chart_object_name}"/></xdr:nvGraphicFramePr>
      <a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart r:id="{drawing_chart_relationship_id}"/></a:graphicData></a:graphic>
    </xdr:graphicFrame>
    <xdr:clientData/>
  </xdr:absoluteAnchor>
</xdr:wsDr>"#,
                            chart_object_id.0
                        )
                        .into_bytes(),
                    })?;
                    runtime.loaded.package.add_part(OpcPart {
                        name: chart_part_uri.clone(),
                        content_type: Some(CHART_PART_CONTENT_TYPE.to_string()),
                        compression: worksheet_compression,
                        bytes: serialize_chart_model_xml(&chart)?,
                    })?;
                    content_types_xml = append_content_type_override_if_missing(
                        content_types_xml.as_slice(),
                        drawing_part_uri.as_str(),
                        DRAWING_PART_CONTENT_TYPE,
                    )?;
                    content_types_xml = append_content_type_override_if_missing(
                        content_types_xml.as_slice(),
                        chart_part_uri.as_str(),
                        CHART_PART_CONTENT_TYPE,
                    )?;
                    chart_sheet_assets = Some((chart, drawing));
                    format!(
                        r#"<?xml version="1.0" encoding="UTF-8"?>
<chartsheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <drawing r:id="{sheet_drawing_relationship_id}"/>
</chartsheet>"#
                    )
                    .into_bytes()
                } else {
                    blank_worksheet_xml_bytes()
                };

                runtime
                    .loaded
                    .package
                    .replace_part_bytes(CONTENT_TYPES_PART_NAME, content_types_xml)?;
                runtime.loaded.package.replace_part_bytes(
                    WORKBOOK_PART_NAME,
                    insert_sheet_into_workbook_xml(
                        workbook_xml.as_slice(),
                        insertion_index,
                        worksheet_name.as_str(),
                        sheet_id,
                        relationship_id.as_str(),
                    )?,
                )?;
                let updated_workbook_rels = append_empty_xml_child_before_container_end(
                    workbook_rels_xml.as_slice(),
                    b"Relationships",
                    {
                        let mut element = BytesStart::new("Relationship");
                        element.push_attribute(("Id", relationship_id.as_str()));
                        element.push_attribute(("Type", workbook_relationship_type));
                        element.push_attribute(("Target", relationship_target.as_str()));
                        element
                    },
                )?;
                if runtime.loaded.package.contains(WORKBOOK_RELS_PART_NAME) {
                    runtime
                        .loaded
                        .package
                        .replace_part_bytes(WORKBOOK_RELS_PART_NAME, updated_workbook_rels)?;
                } else {
                    runtime.loaded.package.add_part(OpcPart {
                        name: WORKBOOK_RELS_PART_NAME.to_string(),
                        content_type: Some(
                            "application/vnd.openxmlformats-package.relationships+xml".to_string(),
                        ),
                        compression: workbook_rels_compression,
                        bytes: updated_workbook_rels,
                    })?;
                }
                runtime.loaded.package.add_part(OpcPart {
                    name: part_uri.clone(),
                    content_type: Some(sheet_part_content_type.to_string()),
                    compression: worksheet_compression,
                    bytes: sheet_xml.clone(),
                })?;
                if let Some((chart, drawing)) = chart_sheet_assets {
                    let chart_id = chart.id;
                    let drawing_id = drawing.id;
                    runtime.loaded.state.charts.insert(chart_id, chart);
                    runtime.loaded.state.drawings.insert(drawing_id, drawing);
                    runtime.loaded.state.chart_sheets.insert(
                        sheet_id,
                        ChartSheetBinding {
                            sheet_id,
                            chart_id,
                            drawing_id: Some(drawing_id),
                            raw_part_uri: Some(part_uri.clone()),
                        },
                    );
                }

                runtime.loaded.state.worksheets.insert(
                    insertion_index.min(runtime.loaded.state.worksheets.len()),
                    WorksheetModel {
                        id: sheet_id,
                        workbook_id: runtime.loaded.state.model.id,
                        name: worksheet_name,
                        kind: sheet_kind,
                        visibility: SheetVisibility::Visible,
                        relationship_id: Some(relationship_id),
                        part_uri: Some(part_uri.clone()),
                    },
                );
                runtime.loaded.state.worksheet_data.insert(
                    sheet_id,
                    WorksheetData {
                        source_xml: sheet_xml,
                        ..WorksheetData::default()
                    },
                );
                if sheet_kind != SheetKind::ChartSheet {
                    runtime.loaded.worksheet_support_parts.insert(
                        sheet_id,
                        WorksheetSupportParts {
                            worksheet_part_uri: Some(part_uri),
                            relationships_part_uri: None,
                            relationships_part_source_bytes: None,
                            relationships_summary: None,
                            hyperlinks_part_summary: None,
                            comment_part_uris: Vec::new(),
                            comment_anchor_refs: BTreeMap::new(),
                            comment_part_source_bytes: BTreeMap::new(),
                            comment_summaries: BTreeMap::new(),
                            vml_drawing_part_uris: Vec::new(),
                            vml_drawing_part_source_bytes: BTreeMap::new(),
                            vml_drawing_summaries: BTreeMap::new(),
                            hyperlink_summaries: Vec::new(),
                            hyperlink_refs: Vec::new(),
                            hyperlink_bindings: Vec::new(),
                            hyperlink_relationship_ids: Vec::new(),
                            legacy_drawing_relationships: Vec::new(),
                            legacy_drawing_relationship_ids: Vec::new(),
                            legacy_drawing_summaries: Vec::new(),
                            comment_relationships: Vec::new(),
                            comment_relationship_ids: Vec::new(),
                        },
                    );
                }
                runtime.dirty = true;

                sheet_id
            };
            last_sheet_id = Some(sheet_id);
        }

        let sheet_id = last_sheet_id.expect("Worksheets.Add count should be positive");

        self.invalidate_workbook_calc_chain(workbook)?;
        self.set_selection(workbook, sheet_id, Rect::single_cell(1, 1));
        Ok(self.register_worksheet_handle(workbook, sheet_id))
    }

    fn spawn_single_sheet_workbook_from_source(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        selection_rect: Rect,
    ) -> OmResult<WorkbookHandle> {
        let (detected_format, source_sheet_ids) = {
            let runtime = self.runtime_workbook(workbook)?;
            (
                runtime.loaded.detected_format,
                runtime
                    .loaded
                    .state
                    .worksheets
                    .iter()
                    .map(|worksheet| worksheet.id)
                    .collect::<Vec<_>>(),
            )
        };
        let source_bytes = self.save_workbook(
            workbook,
            SaveWorkbookSpec {
                format: detected_format,
                profile: ExcelProfile::Excel365,
                lossless: true,
            },
        )?;

        let workbook_name = format!("Book{}", self.next_created_workbook_index);
        self.next_created_workbook_index += 1;
        let copied_workbook = self.open_workbook_with_display_name(
            OpenWorkbookSpec {
                bytes: source_bytes,
                format_hint: Some(detected_format),
                profile: ExcelProfile::Excel365,
                read_only: false,
            },
            Some(workbook_name),
            None,
        )?;
        for other_sheet_id in source_sheet_ids
            .iter()
            .copied()
            .filter(|other_sheet_id| *other_sheet_id != sheet_id)
        {
            self.delete_worksheet(copied_workbook, other_sheet_id, false)?;
        }
        self.runtime_workbook_mut(copied_workbook)?.dirty = true;
        self.set_selection(copied_workbook, sheet_id, selection_rect);
        Ok(copied_workbook)
    }

    fn copy_basic_worksheet_to_workbook(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        target_workbook: WorkbookHandle,
        insertion_index: usize,
    ) -> OmResult<WorksheetHandle> {
        if self.worksheet_model(workbook, sheet_id)?.kind == SheetKind::ChartSheet {
            let result = (|| {
                let (source_name, source_visibility, source_chart, source_chart_support_parts) = {
                    let runtime = self.runtime_workbook(workbook)?;
                    let worksheet = runtime
                        .loaded
                        .state
                        .worksheets
                        .iter()
                        .find(|worksheet| worksheet.id == sheet_id)
                        .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"))?;
                    let chart_binding = runtime
                        .loaded
                        .state
                        .chart_sheets
                        .get(&sheet_id)
                        .ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::InvalidState,
                                "chart sheet is missing a chart binding",
                            )
                        })?;
                    let chart = runtime
                        .loaded
                        .state
                        .charts
                        .get(&chart_binding.chart_id)
                        .ok_or_else(|| {
                            OmError::new(OmErrorCode::InvalidState, "chart sheet chart is missing")
                        })?
                        .clone();
                    let source_chart_support_parts = chart
                        .raw_part_uri
                        .as_deref()
                        .and_then(|chart_part_uri| {
                            runtime
                                .loaded
                                .sheet_drawing_support_parts
                                .get(&sheet_id)
                                .and_then(|support_parts| {
                                    support_parts.chart_summaries.get(chart_part_uri)
                                })
                        })
                        .map(|summary| {
                            summary
                                .support_relationships
                                .iter()
                                .map(|relationship| {
                                    let support_part = runtime
                                        .loaded
                                        .package
                                        .part(&relationship.target)
                                        .ok_or_else(|| {
                                            OmError::new(
                                                OmErrorCode::InvalidState,
                                                format!(
                                                    "chart support part is missing: {}",
                                                    relationship.target
                                                ),
                                            )
                                        })?;
                                    Ok((
                                        relationship.relationship_id.clone(),
                                        relationship.relationship_type.clone(),
                                        relationship.target.clone(),
                                        support_part.bytes.clone(),
                                        support_part.content_type.clone(),
                                        support_part.compression,
                                    ))
                                })
                                .collect::<OmResult<Vec<_>>>()
                        })
                        .transpose()?
                        .unwrap_or_default();
                    (
                        worksheet.name.clone(),
                        worksheet.visibility,
                        chart,
                        source_chart_support_parts,
                    )
                };

                let placement_args = {
                    let worksheets = &self
                        .runtime_workbook(target_workbook)?
                        .loaded
                        .state
                        .worksheets;
                    if insertion_index >= worksheets.len() {
                        let last_sheet_id = worksheets
                            .last()
                            .map(|worksheet| worksheet.id)
                            .ok_or_else(|| {
                                OmError::new(
                                    OmErrorCode::InvalidState,
                                    "workbook has no worksheets",
                                )
                            })?;
                        vec![
                            OmValue::Missing,
                            OmValue::Object(
                                self.register_worksheet_handle(target_workbook, last_sheet_id)
                                    .0,
                            ),
                            OmValue::Missing,
                            OmValue::Number(f64::from(XL_SHEET_TYPE_CHART)),
                        ]
                    } else {
                        let before_sheet_id = worksheets[insertion_index].id;
                        vec![
                            OmValue::Object(
                                self.register_worksheet_handle(target_workbook, before_sheet_id)
                                    .0,
                            ),
                            OmValue::Missing,
                            OmValue::Missing,
                            OmValue::Number(f64::from(XL_SHEET_TYPE_CHART)),
                        ]
                    }
                };
                let added_sheet = self.add_worksheet(target_workbook, &placement_args)?;
                let added_sheet_id = match self.runtime_object(added_sheet.0)? {
                    RuntimeObjectKind::Worksheet { sheet_id, .. } => sheet_id,
                    _ => unreachable!("worksheet handle should resolve to a worksheet object"),
                };

                {
                    let runtime = self.runtime_workbook_mut(target_workbook)?;
                    let chart_binding = runtime
                        .loaded
                        .state
                        .chart_sheets
                        .get(&added_sheet_id)
                        .cloned()
                        .ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::InvalidState,
                                "copied chart sheet is missing a chart binding",
                            )
                        })?;
                    let target_chart_raw_part_uri = runtime
                        .loaded
                        .state
                        .charts
                        .get(&chart_binding.chart_id)
                        .and_then(|chart| chart.raw_part_uri.clone());
                    let target_sheet_part_uri = runtime
                        .loaded
                        .state
                        .worksheets
                        .iter()
                        .find(|worksheet| worksheet.id == added_sheet_id)
                        .and_then(|worksheet| worksheet.part_uri.clone());
                    if let Some(target_chart_part_uri) = target_chart_raw_part_uri.as_deref()
                        && !source_chart_support_parts.is_empty()
                    {
                        let chart_rels_part_uri =
                            worksheet_relationships_part_uri_for(target_chart_part_uri);
                        let mut used_part_names = runtime
                            .loaded
                            .package
                            .parts()
                            .iter()
                            .map(|part| part.name.clone())
                            .collect::<BTreeSet<_>>();
                        used_part_names.insert(chart_rels_part_uri.clone());
                        let mut content_types_xml = runtime
                            .loaded
                            .package
                            .part(CONTENT_TYPES_PART_NAME)
                            .ok_or_else(|| {
                                OmError::new(
                                    OmErrorCode::Parse,
                                    format!(
                                        "workbook package is missing {CONTENT_TYPES_PART_NAME}"
                                    ),
                                )
                            })?
                            .bytes
                            .clone();
                        let mut content_types_dirty = false;
                        let mut relationship_xml = String::from(
                            r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">"#,
                        );
                        let mut target_support_relationships = Vec::new();
                        let mut target_support_part_bytes = BTreeMap::new();
                        for (
                            relationship_id,
                            relationship_type,
                            source_part_uri,
                            source_bytes,
                            source_content_type,
                            source_compression,
                        ) in &source_chart_support_parts
                        {
                            let file_name = source_part_uri
                                .rsplit('/')
                                .next()
                                .unwrap_or(source_part_uri.as_str());
                            let target_part_uri = if relationship_type
                                == "http://schemas.microsoft.com/office/2011/relationships/chartColorStyle"
                                || file_name.starts_with("colors")
                            {
                                next_available_sequential_part_uri(
                                    &mut used_part_names,
                                    "xl/charts/colors",
                                    ".xml",
                                )
                            } else {
                                next_available_sequential_part_uri(
                                    &mut used_part_names,
                                    "xl/charts/style",
                                    ".xml",
                                )
                            };
                            runtime.loaded.package.add_part(OpcPart {
                                name: target_part_uri.clone(),
                                content_type: source_content_type.clone(),
                                compression: *source_compression,
                                bytes: source_bytes.clone(),
                            })?;
                            if let Some(content_type) = source_content_type.as_deref() {
                                content_types_xml = append_content_type_override_if_missing(
                                    content_types_xml.as_slice(),
                                    target_part_uri.as_str(),
                                    content_type,
                                )?;
                                content_types_dirty = true;
                            }
                            let relationship_target = relative_relationship_target(
                                target_chart_part_uri,
                                &target_part_uri,
                            );
                            let escaped_relationship_id =
                                partial_escape(relationship_id.as_str()).to_string();
                            let escaped_relationship_type =
                                partial_escape(relationship_type.as_str()).to_string();
                            let escaped_relationship_target =
                                partial_escape(relationship_target.as_str()).to_string();
                            relationship_xml.push_str(&format!(
                                r#"
  <Relationship Id="{escaped_relationship_id}" Type="{escaped_relationship_type}" Target="{escaped_relationship_target}"/>"#
                            ));
                            target_support_relationships.push(ChartSupportRelationshipBinding {
                                relationship_id: relationship_id.clone(),
                                relationship_type: relationship_type.clone(),
                                target: target_part_uri.clone(),
                            });
                            target_support_part_bytes
                                .insert(target_part_uri.clone(), source_bytes.clone());
                        }
                        relationship_xml.push_str("\n</Relationships>");
                        let relationship_bytes = relationship_xml.into_bytes();
                        if runtime.loaded.package.contains(&chart_rels_part_uri) {
                            runtime.loaded.package.replace_part_bytes(
                                &chart_rels_part_uri,
                                relationship_bytes.clone(),
                            )?;
                        } else {
                            runtime.loaded.package.add_part(OpcPart {
                                name: chart_rels_part_uri.clone(),
                                content_type: Some(RELATIONSHIPS_PART_CONTENT_TYPE.to_string()),
                                compression: CompressionMethod::Stored,
                                bytes: relationship_bytes.clone(),
                            })?;
                        }
                        if content_types_dirty {
                            runtime
                                .loaded
                                .package
                                .replace_part_bytes(CONTENT_TYPES_PART_NAME, content_types_xml)?;
                        }
                        let support_parts = runtime
                            .loaded
                            .sheet_drawing_support_parts
                            .entry(added_sheet_id)
                            .or_insert_with(SheetDrawingSupportParts::default);
                        support_parts.sheet_part_uri = target_sheet_part_uri.clone();
                        if support_parts
                            .chart_part_uris
                            .iter()
                            .all(|part_uri| part_uri != target_chart_part_uri)
                        {
                            support_parts
                                .chart_part_uris
                                .push(target_chart_part_uri.to_string());
                        }
                        if let Some(target_chart_part) =
                            runtime.loaded.package.part(target_chart_part_uri)
                        {
                            support_parts.chart_part_source_bytes.insert(
                                target_chart_part_uri.to_string(),
                                target_chart_part.bytes.clone(),
                            );
                        }
                        if support_parts
                            .chart_relationships_part_uris
                            .iter()
                            .all(|part_uri| part_uri != &chart_rels_part_uri)
                        {
                            support_parts
                                .chart_relationships_part_uris
                                .push(chart_rels_part_uri.clone());
                        }
                        support_parts
                            .chart_relationships_part_source_bytes
                            .insert(chart_rels_part_uri.clone(), relationship_bytes);
                        for (target_part_uri, bytes) in target_support_part_bytes {
                            if support_parts
                                .chart_support_part_uris
                                .iter()
                                .all(|part_uri| part_uri != &target_part_uri)
                            {
                                support_parts
                                    .chart_support_part_uris
                                    .push(target_part_uri.clone());
                            }
                            support_parts
                                .chart_support_part_source_bytes
                                .insert(target_part_uri, bytes);
                        }
                        let chart_summary = support_parts
                            .chart_summaries
                            .entry(target_chart_part_uri.to_string())
                            .or_default();
                        chart_summary.relationships_part_uri = Some(chart_rels_part_uri);
                        chart_summary.support_relationships = target_support_relationships;
                    }
                    let mut copied_chart = source_chart;
                    copied_chart.id = chart_binding.chart_id;
                    copied_chart.workbook_id = runtime.loaded.state.model.id;
                    copied_chart.raw_part_uri = target_chart_raw_part_uri;
                    copied_chart.dirty = true;
                    runtime
                        .loaded
                        .state
                        .charts
                        .insert(chart_binding.chart_id, copied_chart);
                    if let Some(worksheet) = runtime
                        .loaded
                        .state
                        .worksheets
                        .iter_mut()
                        .find(|worksheet| worksheet.id == added_sheet_id)
                    {
                        worksheet.visibility = source_visibility;
                    }
                    runtime.dirty = true;
                }

                let copied_name = {
                    let worksheets = &self
                        .runtime_workbook(target_workbook)?
                        .loaded
                        .state
                        .worksheets;
                    if !worksheets.iter().any(|worksheet| {
                        worksheet.id != added_sheet_id
                            && worksheet.name.eq_ignore_ascii_case(source_name.as_str())
                    }) {
                        source_name.clone()
                    } else {
                        let mut suffix = 2usize;
                        loop {
                            let suffix_text = format!(" ({suffix})");
                            let base_len = 31usize.saturating_sub(suffix_text.chars().count());
                            let base = source_name.chars().take(base_len).collect::<String>();
                            let candidate = format!("{base}{suffix_text}");
                            if !worksheets.iter().any(|worksheet| {
                                worksheet.id != added_sheet_id
                                    && worksheet.name.eq_ignore_ascii_case(candidate.as_str())
                            }) {
                                break candidate;
                            }
                            suffix += 1;
                        }
                    }
                };
                self.dispatch_set(added_sheet.0, "Name", OmValue::Text(copied_name), &[])?;
                Ok(added_sheet)
            })();
            return result;
        }
        let snapshot = self.spawn_single_sheet_workbook_from_source(
            workbook,
            sheet_id,
            Rect::single_cell(1, 1),
        )?;
        let result = (|| {
            let (
                source_name,
                source_visibility,
                source_sheet_data,
                source_support_parts,
                source_relationships_part,
                source_comment_parts,
                source_vml_parts,
                source_drawings,
                source_charts,
                source_chart_raw_part_uris,
                source_has_drawing_support,
            ) = {
                let runtime = self.runtime_workbook(snapshot)?;
                let worksheet = runtime
                    .loaded
                    .state
                    .worksheets
                    .iter()
                    .find(|worksheet| worksheet.id == sheet_id)
                    .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"))?;
                let sheet_data = runtime
                    .loaded
                    .state
                    .worksheet_data_for_sheet(sheet_id)?
                    .clone();
                let support_parts = runtime
                    .loaded
                    .worksheet_support_parts
                    .get(&sheet_id)
                    .cloned()
                    .ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::InvalidState,
                            "worksheet support parts are missing",
                        )
                    })?;
                let source_has_drawing_support = runtime
                    .loaded
                    .sheet_drawing_support_parts
                    .get(&sheet_id)
                    .is_some_and(|support_parts| {
                        !support_parts.drawing_relationship_ids.is_empty()
                            || !support_parts.drawing_part_uris.is_empty()
                            || !support_parts.chart_part_uris.is_empty()
                    });
                let relationships_part = support_parts
                    .relationships_part_uri
                    .as_deref()
                    .map(|part_uri| {
                        let package_part = runtime.loaded.package.part(part_uri);
                        let mut source_bytes = support_parts
                            .relationships_part_source_bytes
                            .clone()
                            .or_else(|| package_part.map(|part| part.bytes.clone()))
                            .ok_or_else(|| {
                                OmError::new(
                                    OmErrorCode::InvalidState,
                                    "worksheet relationships part is missing",
                                )
                            })?;
                        if source_has_drawing_support {
                            source_bytes = strip_relationship_entries_by_type_or_target(
                                source_bytes.as_slice(),
                                &[DRAWING_RELATIONSHIP_TYPE],
                                &[],
                            )?;
                        }
                        Ok((
                            source_bytes,
                            package_part
                                .map(|part| part.compression)
                                .unwrap_or(CompressionMethod::Stored),
                        ))
                    })
                    .transpose()?;
                let comment_parts = support_parts
                    .comment_part_uris
                    .iter()
                    .map(|part_uri| {
                        let package_part = runtime.loaded.package.part(part_uri);
                        let source_bytes = support_parts
                            .comment_part_source_bytes
                            .get(part_uri)
                            .cloned()
                            .or_else(|| package_part.map(|part| part.bytes.clone()))
                            .ok_or_else(|| {
                                OmError::new(
                                    OmErrorCode::InvalidState,
                                    format!("worksheet comment part is missing: {part_uri}"),
                                )
                            })?;
                        Ok((
                            part_uri.clone(),
                            (
                                source_bytes,
                                package_part
                                    .map(|part| part.compression)
                                    .unwrap_or(CompressionMethod::Stored),
                            ),
                        ))
                    })
                    .collect::<OmResult<BTreeMap<_, _>>>()?;
                let vml_parts = support_parts
                    .vml_drawing_part_uris
                    .iter()
                    .map(|part_uri| {
                        let package_part = runtime.loaded.package.part(part_uri);
                        let source_bytes = support_parts
                            .vml_drawing_part_source_bytes
                            .get(part_uri)
                            .cloned()
                            .or_else(|| package_part.map(|part| part.bytes.clone()))
                            .ok_or_else(|| {
                                OmError::new(
                                    OmErrorCode::InvalidState,
                                    format!("worksheet VML drawing part is missing: {part_uri}"),
                                )
                            })?;
                        Ok((
                            part_uri.clone(),
                            (
                                source_bytes,
                                package_part
                                    .map(|part| part.compression)
                                    .unwrap_or(CompressionMethod::Stored),
                            ),
                        ))
                    })
                    .collect::<OmResult<BTreeMap<_, _>>>()?;
                let source_drawings = runtime
                    .loaded
                    .state
                    .drawings
                    .values()
                    .filter(|drawing| drawing.host_sheet_id == sheet_id)
                    .cloned()
                    .collect::<Vec<_>>();
                let source_chart_ids = source_drawings
                    .iter()
                    .flat_map(|drawing| drawing.objects.iter())
                    .filter_map(|object| match object {
                        DrawingObjectModel::ChartFrame(chart_object) => Some(chart_object.chart_id),
                        DrawingObjectModel::UnsupportedRaw { .. } => None,
                    })
                    .collect::<BTreeSet<_>>();
                let mut source_charts = BTreeMap::new();
                let mut source_chart_raw_part_uris = BTreeMap::new();
                for chart_id in source_chart_ids {
                    let chart = runtime
                        .loaded
                        .state
                        .charts
                        .get(&chart_id)
                        .ok_or_else(|| {
                            OmError::new(OmErrorCode::InvalidState, "worksheet chart is missing")
                        })?
                        .clone();
                    source_chart_raw_part_uris.insert(chart_id, chart.raw_part_uri.clone());
                    source_charts.insert(chart_id, chart);
                }
                (
                    worksheet.name.clone(),
                    worksheet.visibility,
                    sheet_data,
                    support_parts,
                    relationships_part,
                    comment_parts,
                    vml_parts,
                    source_drawings,
                    source_charts,
                    source_chart_raw_part_uris,
                    source_has_drawing_support,
                )
            };
            let source_chart_support_part_sources = source_chart_raw_part_uris
                .iter()
                .map(|(chart_id, raw_part_uri)| {
                    Ok((
                        *chart_id,
                        self.chart_support_part_sources_for_chart(
                            snapshot,
                            sheet_id,
                            raw_part_uri.as_deref(),
                        )?,
                    ))
                })
                .collect::<OmResult<BTreeMap<_, _>>>()?;

            let placement_args = {
                let worksheets = &self
                    .runtime_workbook(target_workbook)?
                    .loaded
                    .state
                    .worksheets;
                if insertion_index >= worksheets.len() {
                    let last_sheet_id = worksheets
                        .last()
                        .map(|worksheet| worksheet.id)
                        .ok_or_else(|| {
                            OmError::new(OmErrorCode::InvalidState, "workbook has no worksheets")
                        })?;
                    vec![
                        OmValue::Missing,
                        OmValue::Object(
                            self.register_worksheet_handle(target_workbook, last_sheet_id)
                                .0,
                        ),
                    ]
                } else {
                    let before_sheet_id = worksheets[insertion_index].id;
                    vec![OmValue::Object(
                        self.register_worksheet_handle(target_workbook, before_sheet_id)
                            .0,
                    )]
                }
            };
            let added_sheet = self.add_worksheet(target_workbook, &placement_args)?;
            let added_sheet_id = match self.runtime_object(added_sheet.0)? {
                RuntimeObjectKind::Worksheet { sheet_id, .. } => sheet_id,
                _ => unreachable!("worksheet handle should resolve to a worksheet object"),
            };
            let target_part_uri = self
                .worksheet_model(target_workbook, added_sheet_id)?
                .part_uri
                .clone()
                .ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::InvalidState,
                        "target worksheet is missing a part uri",
                    )
                })?;

            {
                let runtime = self.runtime_workbook_mut(target_workbook)?;
                runtime.loaded.package.replace_part_bytes(
                    target_part_uri.as_str(),
                    source_sheet_data.source_xml.clone(),
                )?;
                let target_relationships_part_uri =
                    worksheet_relationships_part_uri_for(target_part_uri.as_str());
                let mut used_part_names = runtime
                    .loaded
                    .package
                    .parts()
                    .iter()
                    .map(|part| part.name.clone())
                    .collect::<BTreeSet<_>>();
                let comment_part_uri_map = source_support_parts
                    .comment_part_uris
                    .iter()
                    .map(|part_uri| {
                        (
                            part_uri.clone(),
                            next_available_sequential_part_uri(
                                &mut used_part_names,
                                "xl/comments",
                                ".xml",
                            ),
                        )
                    })
                    .collect::<BTreeMap<_, _>>();
                let vml_part_uri_map = source_support_parts
                    .vml_drawing_part_uris
                    .iter()
                    .map(|part_uri| {
                        (
                            part_uri.clone(),
                            next_available_sequential_part_uri(
                                &mut used_part_names,
                                "xl/drawings/vmlDrawing",
                                ".vml",
                            ),
                        )
                    })
                    .collect::<BTreeMap<_, _>>();
                let rewritten_relationship_targets = source_support_parts
                    .comment_relationships
                    .iter()
                    .filter_map(|binding| {
                        comment_part_uri_map
                            .get(&binding.target)
                            .cloned()
                            .map(|target| (binding.relationship_id.clone(), target))
                    })
                    .chain(
                        source_support_parts
                            .legacy_drawing_relationships
                            .iter()
                            .filter_map(|binding| {
                                vml_part_uri_map
                                    .get(&binding.target)
                                    .cloned()
                                    .map(|target| (binding.relationship_id.clone(), target))
                            }),
                    )
                    .collect::<BTreeMap<_, _>>();
                let mut content_types_xml = runtime
                    .loaded
                    .package
                    .part(CONTENT_TYPES_PART_NAME)
                    .ok_or_else(|| {
                        OmError::new(
                            OmErrorCode::Parse,
                            format!("workbook package is missing {CONTENT_TYPES_PART_NAME}"),
                        )
                    })?
                    .bytes
                    .clone();
                for part_uri in comment_part_uri_map.values() {
                    content_types_xml = append_content_type_override_if_missing(
                        content_types_xml.as_slice(),
                        part_uri.as_str(),
                        COMMENTS_PART_CONTENT_TYPE,
                    )?;
                }
                if !vml_part_uri_map.is_empty() {
                    content_types_xml = append_content_type_default_if_missing(
                        content_types_xml.as_slice(),
                        "vml",
                        VML_DRAWING_CONTENT_TYPE,
                    )?;
                }
                runtime
                    .loaded
                    .package
                    .replace_part_bytes(CONTENT_TYPES_PART_NAME, content_types_xml)?;

                let rewritten_relationships_part =
                    if let Some((relationships_bytes, relationships_compression)) =
                        source_relationships_part.as_ref()
                    {
                        let rewritten_bytes = if rewritten_relationship_targets.is_empty() {
                            relationships_bytes.clone()
                        } else {
                            rewrite_relationship_targets(
                                relationships_bytes.as_slice(),
                                &rewritten_relationship_targets,
                                target_part_uri.as_str(),
                            )?
                        };
                        if runtime
                            .loaded
                            .package
                            .contains(&target_relationships_part_uri)
                        {
                            runtime.loaded.package.replace_part_bytes(
                                target_relationships_part_uri.as_str(),
                                rewritten_bytes.clone(),
                            )?;
                        } else {
                            runtime.loaded.package.add_part(OpcPart {
                                name: target_relationships_part_uri.clone(),
                                content_type: Some(RELATIONSHIPS_PART_CONTENT_TYPE.to_string()),
                                compression: *relationships_compression,
                                bytes: rewritten_bytes.clone(),
                            })?;
                        }
                        Some(rewritten_bytes)
                    } else {
                        None
                    };
                for (source_part_uri, target_part_uri) in &comment_part_uri_map {
                    let (part_bytes, compression) =
                        source_comment_parts.get(source_part_uri).ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::InvalidState,
                                format!("worksheet comment part is missing: {source_part_uri}"),
                            )
                        })?;
                    runtime.loaded.package.add_part(OpcPart {
                        name: target_part_uri.clone(),
                        content_type: Some(COMMENTS_PART_CONTENT_TYPE.to_string()),
                        compression: *compression,
                        bytes: part_bytes.clone(),
                    })?;
                }
                for (source_part_uri, target_part_uri) in &vml_part_uri_map {
                    let (part_bytes, compression) =
                        source_vml_parts.get(source_part_uri).ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::InvalidState,
                                format!("worksheet VML drawing part is missing: {source_part_uri}"),
                            )
                        })?;
                    runtime.loaded.package.add_part(OpcPart {
                        name: target_part_uri.clone(),
                        content_type: Some(VML_DRAWING_CONTENT_TYPE.to_string()),
                        compression: *compression,
                        bytes: part_bytes.clone(),
                    })?;
                }
                runtime
                    .loaded
                    .state
                    .worksheet_data
                    .insert(added_sheet_id, source_sheet_data);
                if let Some(worksheet) = runtime
                    .loaded
                    .state
                    .worksheets
                    .iter_mut()
                    .find(|worksheet| worksheet.id == added_sheet_id)
                {
                    worksheet.visibility = source_visibility;
                }

                let mut copied_support_parts = source_support_parts;
                copied_support_parts.worksheet_part_uri = Some(target_part_uri.clone());
                copied_support_parts.relationships_part_uri = rewritten_relationships_part
                    .as_ref()
                    .map(|_| target_relationships_part_uri);
                copied_support_parts.relationships_part_source_bytes = rewritten_relationships_part;
                if source_has_drawing_support || !rewritten_relationship_targets.is_empty() {
                    copied_support_parts.relationships_summary = None;
                }
                copied_support_parts.comment_part_uris = copied_support_parts
                    .comment_part_uris
                    .iter()
                    .map(|part_uri| {
                        comment_part_uri_map
                            .get(part_uri)
                            .cloned()
                            .unwrap_or_else(|| part_uri.clone())
                    })
                    .collect();
                copied_support_parts.comment_anchor_refs = copied_support_parts
                    .comment_anchor_refs
                    .iter()
                    .map(|(part_uri, refs)| {
                        (
                            comment_part_uri_map
                                .get(part_uri)
                                .cloned()
                                .unwrap_or_else(|| part_uri.clone()),
                            refs.clone(),
                        )
                    })
                    .collect();
                copied_support_parts.comment_part_source_bytes = copied_support_parts
                    .comment_part_source_bytes
                    .iter()
                    .map(|(part_uri, bytes)| {
                        (
                            comment_part_uri_map
                                .get(part_uri)
                                .cloned()
                                .unwrap_or_else(|| part_uri.clone()),
                            bytes.clone(),
                        )
                    })
                    .collect();
                copied_support_parts.comment_summaries = copied_support_parts
                    .comment_summaries
                    .iter()
                    .map(|(part_uri, summary)| {
                        (
                            comment_part_uri_map
                                .get(part_uri)
                                .cloned()
                                .unwrap_or_else(|| part_uri.clone()),
                            summary.clone(),
                        )
                    })
                    .collect();
                copied_support_parts.vml_drawing_part_uris = copied_support_parts
                    .vml_drawing_part_uris
                    .iter()
                    .map(|part_uri| {
                        vml_part_uri_map
                            .get(part_uri)
                            .cloned()
                            .unwrap_or_else(|| part_uri.clone())
                    })
                    .collect();
                copied_support_parts.vml_drawing_part_source_bytes = copied_support_parts
                    .vml_drawing_part_source_bytes
                    .iter()
                    .map(|(part_uri, bytes)| {
                        (
                            vml_part_uri_map
                                .get(part_uri)
                                .cloned()
                                .unwrap_or_else(|| part_uri.clone()),
                            bytes.clone(),
                        )
                    })
                    .collect();
                copied_support_parts.vml_drawing_summaries = copied_support_parts
                    .vml_drawing_summaries
                    .iter()
                    .map(|(part_uri, summary)| {
                        (
                            vml_part_uri_map
                                .get(part_uri)
                                .cloned()
                                .unwrap_or_else(|| part_uri.clone()),
                            summary.clone(),
                        )
                    })
                    .collect();
                copied_support_parts.comment_relationships = copied_support_parts
                    .comment_relationships
                    .iter()
                    .map(|binding| excel_xlsx::WorksheetRelationshipBinding {
                        relationship_id: binding.relationship_id.clone(),
                        target: comment_part_uri_map
                            .get(&binding.target)
                            .cloned()
                            .unwrap_or_else(|| binding.target.clone()),
                    })
                    .collect();
                copied_support_parts.legacy_drawing_relationships = copied_support_parts
                    .legacy_drawing_relationships
                    .iter()
                    .map(|binding| excel_xlsx::WorksheetRelationshipBinding {
                        relationship_id: binding.relationship_id.clone(),
                        target: vml_part_uri_map
                            .get(&binding.target)
                            .cloned()
                            .unwrap_or_else(|| binding.target.clone()),
                    })
                    .collect();
                runtime
                    .loaded
                    .worksheet_support_parts
                    .insert(added_sheet_id, copied_support_parts);
                if !source_drawings.is_empty() {
                    let workbook_id = runtime.loaded.state.model.id;
                    let mut next_drawing_id = runtime
                        .loaded
                        .state
                        .drawings
                        .keys()
                        .map(|drawing_id| drawing_id.0)
                        .max()
                        .unwrap_or_default()
                        + 1;
                    let mut next_chart_id = runtime
                        .loaded
                        .state
                        .charts
                        .keys()
                        .map(|chart_id| chart_id.0)
                        .max()
                        .unwrap_or_default()
                        + 1;
                    let mut next_chart_object_id = runtime
                        .loaded
                        .state
                        .drawings
                        .values()
                        .flat_map(|drawing| drawing.objects.iter())
                        .filter_map(|object| match object {
                            DrawingObjectModel::ChartFrame(chart_object) => Some(chart_object.id.0),
                            DrawingObjectModel::UnsupportedRaw { id, .. } => Some(id.0),
                        })
                        .max()
                        .unwrap_or_default()
                        + 1;
                    let mut chart_id_map = BTreeMap::<ChartId, ChartId>::new();
                    for source_drawing in &source_drawings {
                        let drawing_id = DrawingId(next_drawing_id);
                        next_drawing_id += 1;
                        let mut copied_objects = Vec::new();
                        for object in &source_drawing.objects {
                            let DrawingObjectModel::ChartFrame(source_chart_object) = object else {
                                continue;
                            };
                            let chart_id = if let Some(chart_id) =
                                chart_id_map.get(&source_chart_object.chart_id)
                            {
                                *chart_id
                            } else {
                                let chart_id = ChartId(next_chart_id);
                                next_chart_id += 1;
                                let source_chart = source_charts
                                    .get(&source_chart_object.chart_id)
                                    .ok_or_else(|| {
                                        OmError::new(
                                            OmErrorCode::InvalidState,
                                            "worksheet chart is missing",
                                        )
                                    })?;
                                let mut copied_chart = source_chart.clone();
                                copied_chart.id = chart_id;
                                copied_chart.workbook_id = workbook_id;
                                copied_chart.raw_part_uri = None;
                                copied_chart.dirty = true;
                                runtime.loaded.state.charts.insert(chart_id, copied_chart);
                                if let Some(support_sources) = source_chart_support_part_sources
                                    .get(&source_chart_object.chart_id)
                                    && !support_sources.is_empty()
                                {
                                    runtime
                                        .chart_support_part_sources
                                        .insert(chart_id, support_sources.clone());
                                }
                                chart_id_map.insert(source_chart_object.chart_id, chart_id);
                                chart_id
                            };
                            let chart_object_id = ChartObjectId(next_chart_object_id);
                            next_chart_object_id += 1;
                            let mut copied_chart_object = source_chart_object.clone();
                            copied_chart_object.id = chart_object_id;
                            copied_chart_object.workbook_id = workbook_id;
                            copied_chart_object.host_sheet_id = added_sheet_id;
                            copied_chart_object.chart_id = chart_id;
                            copied_chart_object.non_visual_id =
                                u32::try_from(chart_object_id.0).ok();
                            copied_chart_object.raw_binding = None;
                            copied_chart_object.dirty = true;
                            copied_objects
                                .push(DrawingObjectModel::ChartFrame(copied_chart_object));
                        }
                        if !copied_objects.is_empty() {
                            let mut copied_drawing = source_drawing.clone();
                            copied_drawing.id = drawing_id;
                            copied_drawing.workbook_id = workbook_id;
                            copied_drawing.host_sheet_id = added_sheet_id;
                            copied_drawing.objects = copied_objects;
                            copied_drawing.raw_part_uri = None;
                            copied_drawing.dirty = true;
                            runtime
                                .loaded
                                .state
                                .drawings
                                .insert(drawing_id, copied_drawing);
                        }
                    }
                }
            }

            let copied_name = {
                let worksheets = &self
                    .runtime_workbook(target_workbook)?
                    .loaded
                    .state
                    .worksheets;
                if !worksheets.iter().any(|worksheet| {
                    worksheet.id != added_sheet_id
                        && worksheet.name.eq_ignore_ascii_case(source_name.as_str())
                }) {
                    source_name.clone()
                } else {
                    let mut suffix = 2usize;
                    loop {
                        let suffix_text = format!(" ({suffix})");
                        let base_len = 31usize.saturating_sub(suffix_text.chars().count());
                        let base = source_name.chars().take(base_len).collect::<String>();
                        let candidate = format!("{base}{suffix_text}");
                        if !worksheets.iter().any(|worksheet| {
                            worksheet.id != added_sheet_id
                                && worksheet.name.eq_ignore_ascii_case(candidate.as_str())
                        }) {
                            break candidate;
                        }
                        suffix += 1;
                    }
                }
            };
            self.dispatch_set(added_sheet.0, "Name", OmValue::Text(copied_name), &[])?;
            Ok(added_sheet)
        })();
        let close_result = self.close_workbook(snapshot);
        match (result, close_result) {
            (Ok(value), Ok(())) => Ok(value),
            (Ok(_), Err(error)) => Err(error),
            (Err(error), _) => Err(error),
        }
    }

    fn move_worksheet(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        args: &[OmValue],
    ) -> OmResult<()> {
        if args.len() > 2 {
            return Err(OmError::invalid_argument(
                "Worksheet.Move accepts at most Before and After arguments",
            ));
        }

        let placement_target =
            self.worksheet_placement_target(workbook, args.first(), args.get(1), "Worksheet.Move")?;

        if placement_target.is_none() {
            let (read_only, source_sheet_count) = {
                let runtime = self.runtime_workbook(workbook)?;
                (runtime.read_only, runtime.loaded.state.worksheets.len())
            };
            if read_only {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "cannot modify a read-only workbook",
                ));
            }
            let selection_rect = self
                .selection
                .filter(|selection| {
                    selection.workbook == workbook && selection.sheet_id == sheet_id
                })
                .map(|selection| selection.rect)
                .unwrap_or(Rect::single_cell(1, 1));
            self.spawn_single_sheet_workbook_from_source(workbook, sheet_id, selection_rect)?;

            if source_sheet_count > 1 {
                self.delete_worksheet(workbook, sheet_id, false)?;
            } else {
                self.close_workbook(workbook)?;
            }
            return Ok(());
        }

        let (target_workbook, insertion_index) =
            placement_target.expect("Worksheet.Move placement target");
        if target_workbook != workbook {
            let (read_only, source_sheet_count) = {
                let runtime = self.runtime_workbook(workbook)?;
                (runtime.read_only, runtime.loaded.state.worksheets.len())
            };
            if read_only {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "cannot modify a read-only workbook",
                ));
            }
            self.copy_basic_worksheet_to_workbook(
                workbook,
                sheet_id,
                target_workbook,
                insertion_index,
            )?;
            if source_sheet_count > 1 {
                self.delete_worksheet(workbook, sheet_id, false)?;
            } else {
                self.close_workbook(workbook)?;
            }
            return Ok(());
        }

        let runtime = self.runtime_workbook_mut(workbook)?;
        if runtime.read_only {
            return Err(OmError::new(
                OmErrorCode::InvalidState,
                "cannot modify a read-only workbook",
            ));
        }

        let current_index = runtime
            .loaded
            .state
            .worksheets
            .iter()
            .position(|worksheet| worksheet.id == sheet_id)
            .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"))?;
        let mut target_index = insertion_index.min(runtime.loaded.state.worksheets.len());
        if target_index > current_index {
            target_index -= 1;
        }
        if target_index == current_index {
            return Ok(());
        }

        let worksheet = runtime.loaded.state.worksheets.remove(current_index);
        runtime
            .loaded
            .state
            .worksheets
            .insert(target_index, worksheet);
        let workbook_xml = runtime
            .loaded
            .package
            .part(WORKBOOK_PART_NAME)
            .ok_or_else(|| {
                OmError::new(
                    OmErrorCode::Parse,
                    format!("workbook package is missing {WORKBOOK_PART_NAME}"),
                )
            })?
            .bytes
            .clone();
        runtime.loaded.package.replace_part_bytes(
            WORKBOOK_PART_NAME,
            reorder_workbook_sheet_entries(
                workbook_xml.as_slice(),
                &runtime.loaded.state.worksheets,
            )?,
        )?;
        runtime.dirty = true;

        Ok(())
    }

    fn dispatch_invoke_worksheet(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        member: &str,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        self.focus_member_supported("Worksheet", member, false)?;
        match member {
            "Range" => {
                self.ensure_grid_worksheet(workbook, sheet_id, "Worksheet.Range")?;
                if let [OmValue::Text(reference)] = args {
                    let range = self.resolve_worksheet_range_text(workbook, sheet_id, reference)?;
                    self.remember_range_selection(workbook, &range, "Worksheet.Range")?;
                    return Ok(OmValue::Object(
                        self.register_range_set_handle(workbook, range).0,
                    ));
                }
                if let [OmValue::Object(handle)] = args {
                    match self.runtime_object(*handle)? {
                        RuntimeObjectKind::Range {
                            workbook: range_workbook,
                            range: object_range,
                            ..
                        } => {
                            let (range_sheet_id, _) =
                                Self::range_set_single_sheet_rects(&object_range)?;
                            if range_workbook != workbook || range_sheet_id != sheet_id {
                                return Err(OmError::invalid_argument(
                                    "Worksheet.Range object argument must belong to the same worksheet",
                                ));
                            }
                            self.remember_range_selection(
                                workbook,
                                &object_range,
                                "Worksheet.Range",
                            )?;
                            return Ok(OmValue::Object(
                                self.register_range_set_handle(workbook, object_range).0,
                            ));
                        }
                        _ => {
                            return Err(OmError::type_mismatch(
                                "Worksheet.Range expects A1 references or Range objects",
                            ));
                        }
                    }
                }
                let rect = match args {
                    [start, end] => {
                        let start = match start {
                            OmValue::Text(a1) => parse_rect_a1(a1)?,
                            OmValue::Object(handle) => match self.runtime_object(*handle)? {
                                RuntimeObjectKind::Range {
                                    workbook: range_workbook,
                                    range: object_range,
                                    ..
                                } => {
                                    if object_range.areas().len() != 1 {
                                        return Err(OmError::unsupported(
                                            "Worksheet.Range endpoint arguments require single-area Range objects",
                                        ));
                                    }
                                    let (range_sheet_id, rect) =
                                        Self::range_set_single_area(&object_range)?;
                                    if range_workbook != workbook || range_sheet_id != sheet_id {
                                        return Err(OmError::invalid_argument(
                                            "Worksheet.Range object arguments must belong to the same worksheet",
                                        ));
                                    }
                                    rect
                                }
                                _ => {
                                    return Err(OmError::type_mismatch(
                                        "Worksheet.Range expects A1 references or Range objects",
                                    ));
                                }
                            },
                            _ => {
                                return Err(OmError::type_mismatch(
                                    "Worksheet.Range expects A1 references or Range objects",
                                ));
                            }
                        };
                        let end = match end {
                            OmValue::Text(a1) => parse_rect_a1(a1)?,
                            OmValue::Object(handle) => match self.runtime_object(*handle)? {
                                RuntimeObjectKind::Range {
                                    workbook: range_workbook,
                                    range: object_range,
                                    ..
                                } => {
                                    if object_range.areas().len() != 1 {
                                        return Err(OmError::unsupported(
                                            "Worksheet.Range endpoint arguments require single-area Range objects",
                                        ));
                                    }
                                    let (range_sheet_id, rect) =
                                        Self::range_set_single_area(&object_range)?;
                                    if range_workbook != workbook || range_sheet_id != sheet_id {
                                        return Err(OmError::invalid_argument(
                                            "Worksheet.Range object arguments must belong to the same worksheet",
                                        ));
                                    }
                                    rect
                                }
                                _ => {
                                    return Err(OmError::type_mismatch(
                                        "Worksheet.Range expects A1 references or Range objects",
                                    ));
                                }
                            },
                            _ => {
                                return Err(OmError::type_mismatch(
                                    "Worksheet.Range expects A1 references or Range objects",
                                ));
                            }
                        };
                        Rect {
                            row_first: start.row_first.min(end.row_first),
                            row_last: start.row_last.max(end.row_last),
                            col_first: start.col_first.min(end.col_first),
                            col_last: start.col_last.max(end.col_last),
                        }
                    }
                    _ => {
                        return Err(OmError::invalid_argument(
                            "Worksheet.Range expects one A1 reference or Range object, or two A1/range endpoints",
                        ));
                    }
                };
                self.remember_selection(workbook, sheet_id, rect);
                Ok(OmValue::Object(
                    self.register_range_handle(workbook, sheet_id, rect).0,
                ))
            }
            "Activate" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Worksheet.Activate does not accept arguments",
                    ));
                }
                self.ensure_worksheet_visible(workbook, sheet_id, "Worksheet.Activate")?;
                let rect = self
                    .selection
                    .filter(|selection| {
                        selection.workbook == workbook && selection.sheet_id == sheet_id
                    })
                    .map(|selection| selection.rect)
                    .unwrap_or(Rect::single_cell(1, 1));
                self.set_selection(workbook, sheet_id, rect);
                Ok(OmValue::Empty)
            }
            "Select" => {
                match args {
                    []
                    | [OmValue::Missing | OmValue::Empty | OmValue::Null]
                    | [OmValue::Bool(_)] => {}
                    [_] => {
                        return Err(OmError::type_mismatch(
                            "Worksheet.Select Replace expects a boolean when provided",
                        ));
                    }
                    _ => {
                        return Err(OmError::invalid_argument(
                            "Worksheet.Select accepts at most one Replace argument",
                        ));
                    }
                }
                self.ensure_worksheet_visible(workbook, sheet_id, "Worksheet.Select")?;
                let rect = self
                    .selection
                    .filter(|selection| {
                        selection.workbook == workbook && selection.sheet_id == sheet_id
                    })
                    .map(|selection| selection.rect)
                    .unwrap_or(Rect::single_cell(1, 1));
                self.set_selection(workbook, sheet_id, rect);
                Ok(OmValue::Empty)
            }
            "PrintPreview" => {
                validate_print_preview_args(args, "Worksheet")?;
                self.worksheet_model(workbook, sheet_id)?;
                Ok(OmValue::Empty)
            }
            "PrintOut" => {
                validate_print_out_args(args, "Worksheet")?;
                self.worksheet_model(workbook, sheet_id)?;
                Ok(OmValue::Empty)
            }
            "CheckSpelling" => {
                validate_check_spelling_args(args, "Worksheet")?;
                self.worksheet_model(workbook, sheet_id)?;
                Ok(OmValue::Empty)
            }
            "ExportAsFixedFormat" => {
                validate_export_as_fixed_format_args(args, "Worksheet")?;
                self.worksheet_model(workbook, sheet_id)?;
                Ok(OmValue::Empty)
            }
            "Paste" => {
                self.ensure_grid_worksheet(workbook, sheet_id, "Worksheet.Paste")?;
                if args.len() > 2 {
                    return Err(OmError::invalid_argument(
                        "Worksheet.Paste accepts at most Destination and Link arguments",
                    ));
                }
                if let Some(value) = args.get(1) {
                    let link = coerce_optional_bool_arg(value, false, "Worksheet.Paste Link")?;
                    if link {
                        return Err(OmError::unsupported(
                            "Worksheet.Paste Link is not supported",
                        ));
                    }
                }
                let destination = match args.first() {
                    None | Some(OmValue::Missing | OmValue::Empty | OmValue::Null) => None,
                    Some(OmValue::Object(handle)) => {
                        let RuntimeObjectKind::Range {
                            workbook: destination_workbook,
                            range: destination_range,
                            ..
                        } = self.runtime_object(*handle)?
                        else {
                            return Err(OmError::type_mismatch(
                                "Worksheet.Paste Destination expects a Range object",
                            ));
                        };
                        if destination_range.areas().len() != 1 {
                            return Err(OmError::unsupported(
                                "Worksheet.Paste Destination requires a single-area range for cell materialization",
                            ));
                        }
                        let (destination_sheet_id, _) =
                            Self::range_set_single_area(&destination_range)?;
                        if destination_workbook != workbook || destination_sheet_id != sheet_id {
                            return Err(OmError::invalid_argument(
                                "Worksheet.Paste Destination must belong to the same worksheet",
                            ));
                        }
                        Some(*handle)
                    }
                    Some(_) => {
                        return Err(OmError::type_mismatch(
                            "Worksheet.Paste Destination expects a Range object",
                        ));
                    }
                };
                let destination = if let Some(destination) = destination {
                    destination
                } else {
                    if let Some(selection_range) = self.selection_range.as_ref()
                        && selection_range.workbook_id() == self.workbook_model(workbook)?.id
                        && let Ok((selection_sheet_id, _)) =
                            Self::range_set_single_sheet_rects(selection_range)
                        && selection_sheet_id == sheet_id
                        && selection_range.len() != 1
                    {
                        return Err(OmError::unsupported(
                            "Worksheet.Paste without a Destination requires a single-area selection",
                        ));
                    }
                    let rect = self
                        .selection
                        .filter(|selection| {
                            selection.workbook == workbook && selection.sheet_id == sheet_id
                        })
                        .map(|selection| selection.rect)
                        .unwrap_or(Rect::single_cell(1, 1));
                    self.register_range_handle(workbook, sheet_id, rect).0
                };
                self.dispatch_invoke(destination, "PasteSpecial", &[])
            }
            "PasteSpecial" => {
                self.ensure_grid_worksheet(workbook, sheet_id, "Worksheet.PasteSpecial")?;
                if args.len() > 7 {
                    return Err(OmError::invalid_argument(
                        "Worksheet.PasteSpecial accepts at most Format, Link, DisplayAsIcon, IconFileName, IconIndex, IconLabel, and NoHTMLFormatting arguments",
                    ));
                }
                validate_optional_text_arg(args, 0, "Worksheet.PasteSpecial Format")?;
                if matches!(args.first(), Some(OmValue::Text(format)) if !format.is_empty()) {
                    return Err(OmError::unsupported(
                        "Worksheet.PasteSpecial Format is not supported",
                    ));
                }
                if let Some(value) = args.get(1) {
                    let link =
                        coerce_optional_bool_arg(value, false, "Worksheet.PasteSpecial Link")?;
                    if link {
                        return Err(OmError::unsupported(
                            "Worksheet.PasteSpecial Link is not supported",
                        ));
                    }
                }
                if let Some(value) = args.get(2) {
                    let display_as_icon = coerce_optional_bool_arg(
                        value,
                        false,
                        "Worksheet.PasteSpecial DisplayAsIcon",
                    )?;
                    if display_as_icon {
                        return Err(OmError::unsupported(
                            "Worksheet.PasteSpecial DisplayAsIcon is not supported",
                        ));
                    }
                }
                validate_optional_text_arg(args, 3, "Worksheet.PasteSpecial IconFileName")?;
                if matches!(args.get(3), Some(OmValue::Text(icon_file_name)) if !icon_file_name.is_empty())
                {
                    return Err(OmError::unsupported(
                        "Worksheet.PasteSpecial IconFileName is not supported",
                    ));
                }
                validate_optional_integer_arg(args, 4, "Worksheet.PasteSpecial IconIndex")?;
                if args.get(4).is_some_and(|value| !om_value_is_omitted(value)) {
                    return Err(OmError::unsupported(
                        "Worksheet.PasteSpecial IconIndex is not supported",
                    ));
                }
                validate_optional_text_arg(args, 5, "Worksheet.PasteSpecial IconLabel")?;
                if matches!(args.get(5), Some(OmValue::Text(icon_label)) if !icon_label.is_empty())
                {
                    return Err(OmError::unsupported(
                        "Worksheet.PasteSpecial IconLabel is not supported",
                    ));
                }
                if let Some(value) = args.get(6) {
                    coerce_optional_bool_arg(
                        value,
                        false,
                        "Worksheet.PasteSpecial NoHTMLFormatting",
                    )?;
                }
                self.dispatch_invoke_worksheet(workbook, sheet_id, "Paste", &[])
            }
            "Calculate" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Worksheet.Calculate does not accept arguments",
                    ));
                }
                self.ensure_grid_worksheet(workbook, sheet_id, "Worksheet.Calculate")?;
                self.calculate_sheet_formulas(workbook, sheet_id, None)?;
                Ok(OmValue::Empty)
            }
            "Evaluate" => {
                let expression = coerce_evaluate_expression_arg(args, "Worksheet.Evaluate")?;
                self.evaluate_formula_expression(
                    workbook,
                    sheet_id,
                    expression,
                    "Worksheet.Evaluate",
                )
            }
            "Cells" => {
                self.ensure_grid_worksheet(workbook, sheet_id, "Worksheet.Cells")?;
                let (row, col) = parse_cells_args(args)?;
                let rect = Rect::single_cell(row, col);
                self.remember_selection(workbook, sheet_id, rect);
                Ok(OmValue::Object(
                    self.register_range_handle(workbook, sheet_id, rect).0,
                ))
            }
            "Copy" => {
                if args.len() > 2 {
                    return Err(OmError::invalid_argument(
                        "Worksheet.Copy accepts at most Before and After arguments",
                    ));
                }
                if let Some((target_workbook, insertion_index)) = self.worksheet_placement_target(
                    workbook,
                    args.first(),
                    args.get(1),
                    "Worksheet.Copy",
                )? {
                    self.copy_basic_worksheet_to_workbook(
                        workbook,
                        sheet_id,
                        target_workbook,
                        insertion_index,
                    )?;
                } else {
                    let rect = self
                        .selection
                        .filter(|selection| {
                            selection.workbook == workbook && selection.sheet_id == sheet_id
                        })
                        .map(|selection| selection.rect)
                        .unwrap_or(Rect::single_cell(1, 1));
                    self.spawn_single_sheet_workbook_from_source(workbook, sheet_id, rect)?;
                }
                Ok(OmValue::Empty)
            }
            "Move" => {
                self.move_worksheet(workbook, sheet_id, args)?;
                Ok(OmValue::Empty)
            }
            "Delete" => {
                if !args.is_empty() {
                    return Err(OmError::invalid_argument(
                        "Worksheet.Delete does not accept arguments",
                    ));
                }
                Ok(OmValue::Bool(
                    self.delete_worksheet(workbook, sheet_id, true)?,
                ))
            }
            _ => Err(OmError::unsupported(format!(
                "Worksheet.{member} is not implemented as a method"
            ))),
        }
    }

    fn delete_worksheet(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
        respect_display_alerts: bool,
    ) -> OmResult<bool> {
        let deleted_was_active = self.active_workbook == Some(workbook)
            && self.selection.is_some_and(|selection| {
                selection.workbook == workbook && selection.sheet_id == sheet_id
            });
        let replacement_sheet_id = {
            let runtime = self.runtime_workbook(workbook)?;
            if runtime.read_only {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "cannot modify a read-only workbook",
                ));
            }
            if runtime.loaded.state.worksheets.len() <= 1 {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "cannot delete the last worksheet in a workbook",
                ));
            }
            let worksheet_index = runtime
                .loaded
                .state
                .worksheets
                .iter()
                .position(|worksheet| worksheet.id == sheet_id)
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"))?;
            if runtime.loaded.state.worksheets[worksheet_index].visibility
                == SheetVisibility::Visible
                && runtime
                    .loaded
                    .state
                    .worksheets
                    .iter()
                    .filter(|worksheet| worksheet.visibility == SheetVisibility::Visible)
                    .count()
                    <= 1
            {
                return Err(OmError::new(
                    OmErrorCode::InvalidState,
                    "cannot delete the last visible worksheet in a workbook",
                ));
            }
            if respect_display_alerts && self.display_alerts {
                return Ok(false);
            }
            runtime
                .loaded
                .state
                .worksheets
                .iter()
                .enumerate()
                .find(|(index, worksheet)| {
                    *index != worksheet_index && worksheet.visibility == SheetVisibility::Visible
                })
                .map(|(_, worksheet)| worksheet.id)
                .or_else(|| {
                    if worksheet_index < runtime.loaded.state.worksheets.len() - 1 {
                        Some(runtime.loaded.state.worksheets[worksheet_index + 1].id)
                    } else {
                        Some(runtime.loaded.state.worksheets[worksheet_index - 1].id)
                    }
                })
                .expect("replacement worksheet should exist")
        };

        let (removed_chart_object_ids, removed_chart_ids) = {
            let runtime = self.runtime_workbook_mut(workbook)?;
            let worksheet_index = runtime
                .loaded
                .state
                .worksheets
                .iter()
                .position(|worksheet| worksheet.id == sheet_id)
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"))?;
            let removed_worksheet = runtime.loaded.state.worksheets.remove(worksheet_index);
            runtime.loaded.state.worksheet_data.remove(&sheet_id);
            let removed_support_parts = runtime.loaded.worksheet_support_parts.remove(&sheet_id);
            let removed_sheet_drawing_support_parts =
                runtime.loaded.sheet_drawing_support_parts.remove(&sheet_id);
            let removed_chart_sheet_binding = runtime.loaded.state.chart_sheets.remove(&sheet_id);
            let removed_drawing_ids = runtime
                .loaded
                .state
                .drawings
                .iter()
                .filter_map(|(drawing_id, drawing)| {
                    (drawing.host_sheet_id == sheet_id).then_some(*drawing_id)
                })
                .collect::<Vec<_>>();
            let mut removed_chart_object_ids = BTreeSet::new();
            let mut removed_chart_ids = BTreeSet::new();
            let mut drawing_chart_part_uris_to_remove = BTreeSet::<String>::new();
            for drawing_id in removed_drawing_ids {
                if let Some(drawing) = runtime.loaded.state.drawings.remove(&drawing_id) {
                    if let Some(part_uri) = drawing.raw_part_uri {
                        drawing_chart_part_uris_to_remove
                            .insert(worksheet_relationships_part_uri_for(part_uri.as_str()));
                        drawing_chart_part_uris_to_remove.insert(part_uri);
                    }
                    for object in drawing.objects {
                        if let DrawingObjectModel::ChartFrame(chart_object) = object {
                            removed_chart_object_ids.insert(chart_object.id);
                            removed_chart_ids.insert(chart_object.chart_id);
                        }
                    }
                }
            }
            if let Some(binding) = removed_chart_sheet_binding {
                removed_chart_ids.insert(binding.chart_id);
            }
            let removed_chart_ids = removed_chart_ids
                .into_iter()
                .filter(|chart_id| {
                    !runtime
                        .loaded
                        .state
                        .chart_sheets
                        .values()
                        .any(|binding| binding.chart_id == *chart_id)
                        && !runtime.loaded.state.drawings.values().any(|drawing| {
                            drawing.objects.iter().any(|object| match object {
                                DrawingObjectModel::ChartFrame(chart_object) => {
                                    chart_object.chart_id == *chart_id
                                }
                                DrawingObjectModel::UnsupportedRaw { .. } => false,
                            })
                        })
                })
                .collect::<Vec<_>>();
            let removed_chart_ids_for_handles = removed_chart_ids.clone();
            let mut removed_chart_part_uris = BTreeSet::<String>::new();
            for chart_id in removed_chart_ids {
                if let Some(chart) = runtime.loaded.state.charts.remove(&chart_id)
                    && let Some(part_uri) = chart.raw_part_uri
                {
                    removed_chart_part_uris.insert(part_uri.clone());
                    drawing_chart_part_uris_to_remove.insert(part_uri);
                }
            }
            if let Some(support_parts) = removed_sheet_drawing_support_parts.as_ref() {
                drawing_chart_part_uris_to_remove
                    .extend(support_parts.drawing_part_uris.iter().cloned());
                drawing_chart_part_uris_to_remove.extend(
                    support_parts
                        .drawing_relationships_part_uris
                        .iter()
                        .cloned(),
                );
                for chart_part_uri in &removed_chart_part_uris {
                    if let Some(summary) = support_parts.chart_summaries.get(chart_part_uri) {
                        if let Some(chart_rels_part_uri) = summary.relationships_part_uri.as_ref() {
                            drawing_chart_part_uris_to_remove.insert(chart_rels_part_uri.clone());
                        }
                        for relationship in &summary.support_relationships {
                            drawing_chart_part_uris_to_remove.insert(relationship.target.clone());
                        }
                    }
                }
            }

            let workbook_xml = runtime
                .loaded
                .package
                .part(WORKBOOK_PART_NAME)
                .ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::Parse,
                        format!("workbook package is missing {WORKBOOK_PART_NAME}"),
                    )
                })?
                .bytes
                .clone();
            runtime.loaded.package.replace_part_bytes(
                WORKBOOK_PART_NAME,
                strip_workbook_sheet_entry(
                    workbook_xml.as_slice(),
                    sheet_id,
                    removed_worksheet.relationship_id.as_deref(),
                )?,
            )?;

            let workbook_rels_part_name = runtime
                .loaded
                .support_parts
                .workbook_relationships_part_uri
                .clone()
                .unwrap_or_else(|| WORKBOOK_RELS_PART_NAME.to_string());
            let mut relationship_ids_to_strip = Vec::<String>::new();
            if let Some(relationship_id) = removed_worksheet.relationship_id.as_ref() {
                relationship_ids_to_strip.push(relationship_id.clone());
            }
            if !relationship_ids_to_strip.is_empty()
                && let Some(workbook_rels_xml) = runtime
                    .loaded
                    .package
                    .part(workbook_rels_part_name.as_str())
                    .map(|part| part.bytes.clone())
            {
                runtime.loaded.package.replace_part_bytes(
                    workbook_rels_part_name.as_str(),
                    strip_relationship_entries_by_id(
                        workbook_rels_xml.as_slice(),
                        &relationship_ids_to_strip,
                    )?,
                )?;
            }

            let mut package_parts_to_remove = BTreeSet::<String>::new();
            let mut content_type_overrides_to_strip = Vec::<String>::new();
            if let Some(part_uri) = removed_worksheet.part_uri.as_ref() {
                package_parts_to_remove.insert(part_uri.clone());
                content_type_overrides_to_strip.push(part_uri.clone());
                if removed_support_parts.is_none() {
                    package_parts_to_remove.insert(worksheet_relationships_part_uri_for(part_uri));
                }
            }
            if let Some(relationships_part_uri) = removed_support_parts
                .as_ref()
                .and_then(|support_parts| support_parts.relationships_part_uri.as_deref())
            {
                package_parts_to_remove.insert(relationships_part_uri.to_string());
            }
            for part_uri in drawing_chart_part_uris_to_remove {
                package_parts_to_remove.insert(part_uri.clone());
                content_type_overrides_to_strip.push(part_uri);
            }
            for part_uri in package_parts_to_remove {
                runtime.loaded.package.remove_part(part_uri.as_str());
            }
            if !content_type_overrides_to_strip.is_empty()
                && let Some(content_types_xml) = runtime
                    .loaded
                    .package
                    .part(CONTENT_TYPES_PART_NAME)
                    .map(|part| part.bytes.clone())
            {
                runtime.loaded.package.replace_part_bytes(
                    CONTENT_TYPES_PART_NAME,
                    strip_content_type_overrides(
                        content_types_xml.as_slice(),
                        &content_type_overrides_to_strip,
                    )?,
                )?;
            }

            runtime.dirty = true;
            (
                removed_chart_object_ids.into_iter().collect::<Vec<_>>(),
                removed_chart_ids_for_handles,
            )
        };

        self.invalidate_workbook_calc_chain(workbook)?;
        self.invalidate_sheet_object_handles(workbook, sheet_id);
        for chart_object_id in removed_chart_object_ids {
            self.stale_chart_object_handles_for_id(workbook, chart_object_id);
        }
        for chart_id in removed_chart_ids {
            self.stale_chart_handles_for_chart(workbook, chart_id);
        }
        if deleted_was_active {
            self.set_selection(workbook, replacement_sheet_id, Rect::single_cell(1, 1));
        }
        if let Some((chart_workbook, chart_id, _)) = self.active_chart
            && chart_workbook == workbook
            && self.chart_model(workbook, chart_id).is_err()
        {
            self.active_chart = None;
        }

        Ok(true)
    }

    fn resolve_workbook_item(&self, args: &[OmValue]) -> OmResult<OmValue> {
        if args.len() != 1 {
            return Err(OmError::invalid_argument(
                "Workbooks.Item expects a single workbook index or name",
            ));
        }

        let workbook = match &args[0] {
            OmValue::Number(index) => {
                let index = coerce_positive_index(*index, "Workbooks.Item index")?;
                self.workbooks
                    .keys()
                    .nth(index as usize - 1)
                    .copied()
                    .map(|handle| WorkbookHandle(ObjectHandle(handle)))
            }
            OmValue::Text(name) => self
                .workbooks
                .iter()
                .find(|(_, runtime)| {
                    runtime
                        .loaded
                        .state
                        .model
                        .display_name
                        .eq_ignore_ascii_case(name)
                })
                .map(|(&handle, _)| WorkbookHandle(ObjectHandle(handle))),
            _ => {
                return Err(OmError::type_mismatch(
                    "Workbooks.Item expects a numeric index or workbook name",
                ));
            }
        }
        .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "workbook item not found"))?;

        Ok(OmValue::Object(workbook.0))
    }

    fn resolve_sheet_collection_item(
        &mut self,
        workbook: WorkbookHandle,
        collection_kind: RuntimeSheetCollectionKind,
        args: &[OmValue],
    ) -> OmResult<OmValue> {
        let collection_name = collection_kind.member_name();
        if args.len() != 1 {
            return Err(OmError::invalid_argument(format!(
                "{collection_name}.Item expects a single sheet index or name"
            )));
        }

        let sheet_id = match &args[0] {
            OmValue::Number(index) => {
                let index =
                    coerce_positive_index(*index, &format!("{collection_name}.Item index"))?;
                self.runtime_workbook(workbook)?
                    .loaded
                    .state
                    .worksheets
                    .iter()
                    .filter(|worksheet| collection_kind.includes(worksheet.kind))
                    .nth(index as usize - 1)
                    .map(|worksheet| worksheet.id)
            }
            OmValue::Text(name) => self
                .runtime_workbook(workbook)?
                .loaded
                .state
                .worksheets
                .iter()
                .filter(|worksheet| collection_kind.includes(worksheet.kind))
                .find(|worksheet| worksheet.name.eq_ignore_ascii_case(name))
                .map(|worksheet| worksheet.id),
            _ => {
                return Err(OmError::type_mismatch(format!(
                    "{collection_name}.Item expects a numeric index or sheet name"
                )));
            }
        }
        .ok_or_else(|| {
            OmError::new(
                OmErrorCode::NotFound,
                format!("{collection_name} item not found"),
            )
        })?;

        if collection_kind == RuntimeSheetCollectionKind::Charts {
            let chart_id = self
                .runtime_workbook(workbook)?
                .loaded
                .state
                .chart_sheets
                .get(&sheet_id)
                .map(|binding| binding.chart_id)
                .ok_or_else(|| {
                    OmError::new(
                        OmErrorCode::InvalidState,
                        "chart sheet is missing a chart binding",
                    )
                })?;
            return Ok(OmValue::Object(
                self.register_chart_handle(workbook, chart_id),
            ));
        }

        if collection_kind == RuntimeSheetCollectionKind::Sheets {
            return Ok(OmValue::Object(
                self.register_sheet_object_handle(workbook, sheet_id)?,
            ));
        }

        Ok(OmValue::Object(
            self.register_worksheet_handle(workbook, sheet_id).0,
        ))
    }

    fn register_worksheet_handle(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
    ) -> WorksheetHandle {
        WorksheetHandle(self.register_object(RuntimeObjectKind::Worksheet { workbook, sheet_id }))
    }

    fn register_sheet_object_handle(
        &mut self,
        workbook: WorkbookHandle,
        sheet_id: SheetId,
    ) -> OmResult<ObjectHandle> {
        let chart_id = {
            let state = &self.runtime_workbook(workbook)?.loaded.state;
            let worksheet = state
                .worksheets
                .iter()
                .find(|worksheet| worksheet.id == sheet_id)
                .ok_or_else(|| OmError::new(OmErrorCode::NotFound, "unknown worksheet"))?;
            if worksheet.kind == SheetKind::ChartSheet {
                Some(
                    state
                        .chart_sheets
                        .get(&sheet_id)
                        .map(|binding| binding.chart_id)
                        .ok_or_else(|| {
                            OmError::new(
                                OmErrorCode::InvalidState,
                                "chart sheet is missing a chart binding",
                            )
                        })?,
                )
            } else {
                None
            }
        };
        Ok(match chart_id {
            Some(chart_id) => self.register_chart_handle(workbook, chart_id),
            None => self.register_worksheet_handle(workbook, sheet_id).0,
        })
    }

