    let relationship_targets = relationship_targets
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let mut reader = Reader::from_reader(Cursor::new(rels_xml));
    reader.config_mut().trim_text(false);
    let mut writer = Writer::new(Cursor::new(Vec::new()));
