    #[test]
    fn pinned_runtime_registry_exposes_recent_chart_members() {
        let runtime = ExcelRuntime::new();
        let series_collection = runtime
            .dispatch_registry()
            .focus_surfaces
            .iter()
            .find(|surface| surface.name == "SeriesCollection")
            .expect("SeriesCollection focus surface");
        let add = series_collection
            .members
            .iter()
            .find(|member| member.name == "Add")
            .expect("SeriesCollection.Add focus member");
        assert!(matches!(add.support, office_idl::SupportState::Stub));
        let plot_area = runtime
            .dispatch_registry()
            .focus_surfaces
            .iter()
            .find(|surface| surface.name == "PlotArea")
            .expect("PlotArea focus surface");
        for member_name in ["Clear", "ClearContents"] {
            let member = plot_area
                .members
                .iter()
                .find(|member| member.name == member_name)
                .unwrap_or_else(|| panic!("PlotArea.{member_name} focus member"));
            assert!(matches!(member.support, office_idl::SupportState::Stub));
        }
        let chart = runtime
            .dispatch_registry()
            .focus_surfaces
            .iter()
            .find(|surface| surface.name == "Chart")
            .expect("Chart focus surface");
        let location = chart
            .members
            .iter()
            .find(|member| member.name == "Location")
            .expect("Chart.Location focus member");
        assert!(matches!(location.support, office_idl::SupportState::Stub));
        let chart_object = runtime
            .dispatch_registry()
            .focus_surfaces
            .iter()
            .find(|surface| surface.name == "ChartObject")
            .expect("ChartObject focus surface");
        for member_name in [
            "IncrementLeft",
            "IncrementTop",
            "IncrementRotation",
            "ScaleWidth",
            "ScaleHeight",
        ] {
            assert!(
                !chart_object
                    .members
                    .iter()
                    .any(|member| member.name == member_name),
                "ChartObject.{member_name} should stay off the direct focus surface"
            );
        }
        let shape_range = runtime
            .dispatch_registry()
            .focus_surfaces
            .iter()
            .find(|surface| surface.name == "ShapeRange")
            .expect("ShapeRange focus surface");
        for member_name in [
            "IncrementLeft",
            "IncrementTop",
            "IncrementRotation",
            "ScaleWidth",
            "ScaleHeight",
        ] {
            let member = shape_range
                .members
                .iter()
                .find(|member| member.name == member_name)
                .unwrap_or_else(|| panic!("ShapeRange.{member_name} focus member"));
            assert!(matches!(member.support, office_idl::SupportState::Stub));
        }
    }

    #[test]
    fn opens_and_saves_detected_format() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open workbook");

        assert_eq!(
            runtime
                .workbook_model(workbook)
                .expect("model")
                .display_name,
            "Workbook"
        );
        assert_eq!(
            runtime.worksheets(workbook).expect("worksheets")[0].name,
            "Sheet1"
        );
        assert!(runtime.is_read_only(workbook).expect("read_only"));
        assert!(supports_format(FileFormat::Xlsx));

        let bytes = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook");
        let reparsed = OpcPackage::from_bytes(&bytes).expect("reparse saved workbook");
        assert!(reparsed.contains("customXml/item1.xml"));

        runtime.close_workbook(workbook).expect("close workbook");
    }

    #[test]
    fn gets_and_sets_range_values_for_mutable_workbook() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let sheet_id = runtime.worksheets(workbook).expect("worksheets")[0].id;

        let initial = runtime
            .get_range_values(GetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 1,
                        row_last: 1,
                        col_first: 1,
                        col_last: 3,
                    },
                ),
            })
            .expect("initial range");
        assert_eq!(initial.values[0], OmValue::Number(42.0));
        assert_eq!(initial.values[1], OmValue::Text("SHARED".to_string()));
        assert_eq!(initial.values[2], OmValue::Text("shared".to_string()));

        runtime
            .set_range_values(SetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 2,
                        row_last: 2,
                        col_first: 1,
                        col_last: 2,
                    },
                ),
                values: OmArray::new(
                    1,
                    2,
                    vec![OmValue::Text("changed".to_string()), OmValue::Bool(true)],
                )
                .expect("values"),
            })
            .expect("set range");

        let updated = runtime
            .get_range_values(GetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 2,
                        row_last: 2,
                        col_first: 1,
                        col_last: 2,
                    },
                ),
            })
            .expect("updated range");
        assert_eq!(updated.values[0], OmValue::Text("changed".to_string()));
        assert_eq!(updated.values[1], OmValue::Bool(true));

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, office_common::LoadOptions::default())
            .expect("reopen saved workbook");
        let reopened_sheet_id = reopened.state.worksheets[0].id;
        assert_eq!(
            reopened
                .state
                .cell(reopened_sheet_id, 2, 1)
                .expect("A2")
                .value,
            office_common::CellValue::Text("changed".to_string())
        );
        assert_eq!(
            reopened
                .state
                .cell(reopened_sheet_id, 2, 2)
                .expect("B2")
                .value,
            office_common::CellValue::Bool(true)
        );
    }

