    #[test]
    fn root_application_dispatch_exposes_active_workbook_sheet_and_workbooks() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");

        let application = runtime.root_application();
        let active_workbook = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveWorkbook", &[])
                .expect("ActiveWorkbook"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let active_cell = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveCell", &[])
                .expect("ActiveCell"),
        );
        let selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection"),
        );
        let workbooks = expect_object_handle(
            runtime
                .dispatch_get(application, "Workbooks", &[])
                .expect("Workbooks"),
        );
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(active_workbook, "Worksheets", &[])
                .expect("Worksheets"),
        );
        let workbook_item = expect_object_handle(
            runtime
                .dispatch_invoke(workbooks, "Item", &[OmValue::Number(1.0)])
                .expect("Workbooks.Item(1)"),
        );
        let worksheet_item = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );

        assert_eq!(workbook.0, active_workbook);
        assert_eq!(active_workbook, workbook_item);
        assert_ne!(application, active_sheet);
        assert_ne!(application, workbooks);
        assert_ne!(active_workbook, worksheets);
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("sheet name")
            ),
            "Sheet1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(worksheet_item, "Name", &[])
                    .expect("worksheet item name")
            ),
            "Sheet1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell, "Address", &[])
                    .expect("active cell address")
            ),
            "$A$1"
        );
        let active_cell_parent = expect_object_handle(
            runtime
                .dispatch_get(active_cell, "Parent", &[])
                .expect("active cell parent"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell_parent, "Name", &[])
                    .expect("active cell parent name")
            ),
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("active sheet name")
            )
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection, "Address", &[])
                    .expect("selection address")
            ),
            "$A$1"
        );

        let updated_selection = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1:C1".to_string())])
                .expect("Range(B1:C1)"),
        );
        let selection_after_range = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Range"),
        );
        let active_cell_after_range = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveCell", &[])
                .expect("ActiveCell after Range"),
        );
        let selection_after_cells = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Cells",
                    &[OmValue::Number(2.0), OmValue::Number(2.0)],
                )
                .expect("Cells(2, 2)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(updated_selection, "Address", &[])
                    .expect("updated selection address")
            ),
            "$B$1:$C$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_after_range, "Address", &[])
                    .expect("Selection after Range address")
            ),
            "$B$1:$C$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell_after_range, "Address", &[])
                    .expect("ActiveCell after Range address")
            ),
            "$B$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_after_cells, "Address", &[])
                    .expect("Cells(2, 2) address")
            ),
            "$B$2"
        );
        let selection_after_cells_handle = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Cells"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_after_cells_handle, "Address", &[])
                    .expect("Selection after Cells address")
            ),
            "$B$2"
        );
    }

    #[test]
    fn workbook_names_add_lookup_refers_to_range_and_delete() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime.create_workbook().expect("workbook");

        let names = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Names", &[])
                .expect("Workbook.Names"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(names, "Count", &[])
                    .expect("Names.Count before add")
            ),
            0.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(names, "Creator", &[])
                    .expect("Names.Creator")
            ),
            f64::from(super::XL_CREATOR_CODE)
        );
        assert_eq!(
            runtime
                .dispatch_get(names, "Creator", &[OmValue::Missing])
                .expect_err("Names.Creator rejects args")
                .code,
            OmErrorCode::InvalidArgument
        );

        let name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("Total".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                    ],
                )
                .expect("Names.Add"),
        );
        assert_eq!(
            expect_object_handle(
                runtime
                    .dispatch_get(name, "Parent", &[])
                    .expect("workbook Name.Parent")
            ),
            workbook.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(name, "Creator", &[])
                    .expect("Name.Creator")
            ),
            f64::from(super::XL_CREATOR_CODE)
        );
        assert_eq!(
            runtime
                .dispatch_get(name, "Creator", &[OmValue::Missing])
                .expect_err("Name.Creator rejects args")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            expect_text(runtime.dispatch_get(name, "Name", &[]).expect("Name.Name")),
            "Total"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(name, "RefersTo", &[])
                    .expect("Name.RefersTo")
            ),
            "=Sheet1!$A$1"
        );

        let item = expect_object_handle(
            runtime
                .dispatch_get(names, "Item", &[OmValue::Text("total".to_string())])
                .expect("Names.Item(total)"),
        );
        let refers_to_range = expect_object_handle(
            runtime
                .dispatch_get(item, "RefersToRange", &[])
                .expect("Name.RefersToRange"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(refers_to_range, "Address", &[])
                    .expect("RefersToRange.Address")
            ),
            "$A$1"
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after add")
        ));

        runtime
            .dispatch_invoke(name, "Delete", &[])
            .expect("Name.Delete");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(names, "Count", &[])
                    .expect("Names.Count after delete")
            ),
            0.0
        );
    }

    #[test]
    fn name_name_setter_renames_defined_name_and_lookup_key() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime.create_workbook().expect("workbook");

        let names = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Names", &[])
                .expect("Workbook.Names"),
        );
        let name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("Total".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                    ],
                )
                .expect("Names.Add Total"),
        );
        runtime
            .dispatch_invoke(
                names,
                "Add",
                &[
                    OmValue::Text("TakenName".to_string()),
                    OmValue::Text("=Sheet1!$B$1".to_string()),
                ],
            )
            .expect("Names.Add TakenName");

        runtime
            .dispatch_set(workbook.0, "Saved", OmValue::Bool(true), &[])
            .expect("clear dirty state before Name.Name set");
        runtime
            .dispatch_set(
                name,
                "Name",
                OmValue::Text("RevenueTotal".to_string()),
                &[],
            )
            .expect("Name.Name set");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(name, "Name", &[])
                    .expect("Name.Name after set")
            ),
            "RevenueTotal"
        );
        assert_eq!(
            runtime
                .dispatch_get(names, "Item", &[OmValue::Text("Total".to_string())])
                .expect_err("old Names.Item lookup should fail after Name.Name set")
                .code,
            OmErrorCode::NotFound
        );
        let renamed_item = expect_object_handle(
            runtime
                .dispatch_get(
                    names,
                    "Item",
                    &[OmValue::Text("revenuetotal".to_string())],
                )
                .expect("new Names.Item lookup after Name.Name set"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(renamed_item, "RefersTo", &[])
                    .expect("renamed Name.RefersTo")
            ),
            "=Sheet1!$A$1"
        );
        {
            let runtime_workbook = runtime.runtime_workbook(workbook).expect("runtime workbook");
            let defined_name = runtime_workbook
                .loaded
                .state
                .defined_names
                .lookup_in_scope(office_common::NameScope::Workbook, "revenuetotal")
                .expect("renamed defined name");
            assert_eq!(defined_name.display_name, "RevenueTotal");
            assert_eq!(defined_name.canonical_name, "REVENUETOTAL");
            assert_eq!(defined_name.refers_to.text, "Sheet1!$A$1");
        }
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Name.Name set")
        ));

        runtime
            .dispatch_set(workbook.0, "Saved", OmValue::Bool(true), &[])
            .expect("clear dirty state before same Name.Name set");
        runtime
            .dispatch_set(
                name,
                "Name",
                OmValue::Text("RevenueTotal".to_string()),
                &[],
            )
            .expect("same Name.Name set");
        assert!(expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after same Name.Name set")
        ));

        runtime
            .dispatch_set(
                name,
                "Name",
                OmValue::Text("revenuetotal".to_string()),
                &[],
            )
            .expect("case-only Name.Name set");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(name, "Name", &[])
                    .expect("Name.Name after case-only set")
            ),
            "revenuetotal"
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after Name.Name setter");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved workbook package");
        let workbook_xml = String::from_utf8(
            saved_package
                .part("xl/workbook.xml")
                .expect("saved workbook xml")
                .bytes
                .clone(),
        )
        .expect("workbook xml utf8");
        assert!(workbook_xml
            .contains(r#"<definedName name="revenuetotal">Sheet1!$A$1</definedName>"#));

        assert_eq!(
            runtime
                .dispatch_set(name, "Name", OmValue::Number(1.0), &[])
                .expect_err("Name.Name rejects non-text")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    name,
                    "Name",
                    OmValue::Text("A1".to_string()),
                    &[],
                )
                .expect_err("Name.Name rejects invalid names")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    name,
                    "Name",
                    OmValue::Text("TakenName".to_string()),
                    &[],
                )
                .expect_err("Name.Name rejects duplicates")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    name,
                    "Name",
                    OmValue::Text("AnotherName".to_string()),
                    &[OmValue::Missing],
                )
                .expect_err("Name.Name rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn names_add_visible_false_creates_hidden_defined_name() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime.create_workbook().expect("workbook");

        let names = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Names", &[])
                .expect("Workbook.Names"),
        );
        let hidden_name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("HiddenTotal".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                        OmValue::Bool(false),
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                    ],
                )
                .expect("Names.Add hidden"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(hidden_name, "Name", &[])
                    .expect("hidden Name.Name")
            ),
            "HiddenTotal"
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(hidden_name, "Visible", &[])
                .expect("hidden Name.Visible")
        ));
        let runtime_workbook = runtime.runtime_workbook(workbook).expect("runtime workbook");
        let defined_name = runtime_workbook
            .loaded
            .state
            .defined_names
            .lookup_in_scope(office_common::NameScope::Workbook, "hiddentotal")
            .expect("hidden defined name");
        assert!(defined_name.metadata.hidden);
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after hidden name")
        ));

        assert_eq!(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("BadVisible".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                        OmValue::Text("no".to_string()),
                    ],
                )
                .expect_err("Names.Add Visible rejects text")
                .code,
            OmErrorCode::TypeMismatch
        );
        let command_macro_name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("CommandMacro".to_string()),
                        OmValue::Text("=Sheet1!$B$1".to_string()),
                        OmValue::Missing,
                        OmValue::Number(2.0),
                        OmValue::Text("Z".to_string()),
                        OmValue::Number(10.0),
                    ],
                )
                .expect("Names.Add command macro"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(command_macro_name, "Name", &[])
                    .expect("command macro Name.Name")
            ),
            "CommandMacro"
        );
        let worksheet_function_name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("WorksheetFunction".to_string()),
                        OmValue::Text("=Sheet1!$C$1".to_string()),
                        OmValue::Missing,
                        OmValue::Number(1.0),
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Text("Math & Trig".to_string()),
                    ],
                )
                .expect("Names.Add function category local"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(worksheet_function_name, "Name", &[])
                    .expect("worksheet function Name.Name")
            ),
            "WorksheetFunction"
        );
        {
            let runtime_workbook = runtime.runtime_workbook(workbook).expect("runtime workbook");
            let command_macro = runtime_workbook
                .loaded
                .state
                .defined_names
                .lookup_in_scope(office_common::NameScope::Workbook, "commandmacro")
                .expect("command macro defined name");
            assert!(!command_macro.metadata.function);
            assert!(command_macro.metadata.vb_procedure);
            assert_eq!(
                command_macro.metadata.shortcut_key.as_deref(),
                Some("Z")
            );
            assert_eq!(command_macro.metadata.function_group_id, Some(10));

            let worksheet_function = runtime_workbook
                .loaded
                .state
                .defined_names
                .lookup_in_scope(office_common::NameScope::Workbook, "worksheetfunction")
                .expect("worksheet function defined name");
            assert!(worksheet_function.metadata.function);
            assert!(!worksheet_function.metadata.vb_procedure);
            assert_eq!(worksheet_function.metadata.function_group_id, Some(3));
            assert_eq!(worksheet_function.metadata.shortcut_key, None);
        }
        assert_eq!(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("BadShortcut".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                        OmValue::Missing,
                        OmValue::Number(1.0),
                        OmValue::Text("Z".to_string()),
                    ],
                )
                .expect_err("Names.Add ShortcutKey requires command macro")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("BadCategory".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                        OmValue::Missing,
                        OmValue::Number(1.0),
                        OmValue::Missing,
                        OmValue::Text("Custom Bucket".to_string()),
                    ],
                )
                .expect_err("Names.Add custom category remains unsupported")
                .code,
            OmErrorCode::Unsupported
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after hidden name");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved workbook package");
        let workbook_xml = String::from_utf8(
            saved_package
                .part("xl/workbook.xml")
                .expect("saved workbook xml")
                .bytes
                .clone(),
        )
        .expect("workbook xml utf8");
        assert!(workbook_xml.contains(
            r#"<definedName name="HiddenTotal" hidden="1">Sheet1!$A$1</definedName>"#
        ));
        assert!(workbook_xml.contains(
            r#"<definedName name="CommandMacro" vbProcedure="1" functionGroupId="10" shortcutKey="Z">Sheet1!$B$1</definedName>"#
        ));
        assert!(workbook_xml.contains(
            r#"<definedName name="WorksheetFunction" function="1" functionGroupId="3">Sheet1!$C$1</definedName>"#
        ));
    }

    #[test]
    fn name_visible_setter_updates_hidden_metadata() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime.create_workbook().expect("workbook");

        let names = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Names", &[])
                .expect("Workbook.Names"),
        );
        let name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("ToggleVisible".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                    ],
                )
                .expect("Names.Add"),
        );
        assert!(expect_bool(
            runtime
                .dispatch_get(name, "Visible", &[])
                .expect("Name.Visible before set")
        ));

        runtime
            .dispatch_set(name, "Visible", OmValue::Bool(false), &[])
            .expect("Name.Visible false");
        assert!(!expect_bool(
            runtime
                .dispatch_get(name, "Visible", &[])
                .expect("Name.Visible after false")
        ));
        let runtime_workbook = runtime.runtime_workbook(workbook).expect("runtime workbook");
        let defined_name = runtime_workbook
            .loaded
            .state
            .defined_names
            .lookup_in_scope(office_common::NameScope::Workbook, "togglevisible")
            .expect("defined name");
        assert!(defined_name.metadata.hidden);
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Name.Visible")
        ));

        assert_eq!(
            runtime
                .dispatch_set(name, "Visible", OmValue::Text("no".to_string()), &[])
                .expect_err("Name.Visible rejects text")
                .code,
            OmErrorCode::TypeMismatch
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after hidden setter");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved workbook package");
        let workbook_xml = String::from_utf8(
            saved_package
                .part("xl/workbook.xml")
                .expect("saved workbook xml")
                .bytes
                .clone(),
        )
        .expect("workbook xml utf8");
        assert!(workbook_xml.contains(
            r#"<definedName name="ToggleVisible" hidden="1">Sheet1!$A$1</definedName>"#
        ));

        runtime
            .dispatch_set(name, "Visible", OmValue::Bool(true), &[])
            .expect("Name.Visible true");
        assert!(expect_bool(
            runtime
                .dispatch_get(name, "Visible", &[])
                .expect("Name.Visible after true")
        ));
        let runtime_workbook = runtime.runtime_workbook(workbook).expect("runtime workbook");
        let defined_name = runtime_workbook
            .loaded
            .state
            .defined_names
            .lookup_in_scope(office_common::NameScope::Workbook, "togglevisible")
            .expect("defined name after visible true");
        assert!(!defined_name.metadata.hidden);
    }

    #[test]
    fn name_refers_to_setters_update_source_and_range() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime.create_workbook().expect("workbook");

        let names = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Names", &[])
                .expect("Workbook.Names"),
        );
        let name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("MutableTotal".to_string()),
                        OmValue::Text("=Sheet1!$A$1".to_string()),
                    ],
                )
                .expect("Names.Add"),
        );

        runtime
            .dispatch_set(workbook.0, "Saved", OmValue::Bool(true), &[])
            .expect("clear dirty state before RefersTo set");
        runtime
            .dispatch_set(
                name,
                "RefersTo",
                OmValue::Text("=Sheet1!$B$2".to_string()),
                &[],
            )
            .expect("Name.RefersTo set");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(name, "RefersTo", &[])
                    .expect("Name.RefersTo after set")
            ),
            "=Sheet1!$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(name, "RefersToR1C1", &[])
                    .expect("Name.RefersToR1C1 after A1 set")
            ),
            "=Sheet1!R2C2"
        );
        let refers_to_range = expect_object_handle(
            runtime
                .dispatch_get(name, "RefersToRange", &[])
                .expect("Name.RefersToRange after A1 set"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(refers_to_range, "Address", &[])
                    .expect("RefersToRange.Address after A1 set")
            ),
            "$B$2"
        );
        {
            let runtime_workbook = runtime.runtime_workbook(workbook).expect("runtime workbook");
            let defined_name = runtime_workbook
                .loaded
                .state
                .defined_names
                .lookup_in_scope(office_common::NameScope::Workbook, "mutabletotal")
                .expect("defined name after A1 set");
            assert_eq!(defined_name.refers_to.text, "Sheet1!$B$2");
            assert!(!defined_name.refers_to.is_r1c1);
        }
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after RefersTo set")
        ));

        runtime
            .dispatch_set(workbook.0, "Saved", OmValue::Bool(true), &[])
            .expect("clear dirty state before same RefersTo set");
        runtime
            .dispatch_set(
                name,
                "RefersToLocal",
                OmValue::Text("=Sheet1!$B$2".to_string()),
                &[],
            )
            .expect("Name.RefersToLocal same set");
        assert!(expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after same RefersToLocal set")
        ));

        runtime
            .dispatch_set(
                name,
                "RefersToR1C1",
                OmValue::Text("=Sheet1!R3C3".to_string()),
                &[],
            )
            .expect("Name.RefersToR1C1 set");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(name, "RefersTo", &[])
                    .expect("Name.RefersTo after R1C1 set")
            ),
            "=Sheet1!$C$3"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(name, "RefersToR1C1Local", &[])
                    .expect("Name.RefersToR1C1Local after R1C1 set")
            ),
            "=Sheet1!R3C3"
        );
        let r1c1_refers_to_range = expect_object_handle(
            runtime
                .dispatch_get(name, "RefersToRange", &[])
                .expect("Name.RefersToRange after R1C1 set"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(r1c1_refers_to_range, "Address", &[])
                    .expect("RefersToRange.Address after R1C1 set")
            ),
            "$C$3"
        );
        {
            let runtime_workbook = runtime.runtime_workbook(workbook).expect("runtime workbook");
            let defined_name = runtime_workbook
                .loaded
                .state
                .defined_names
                .lookup_in_scope(office_common::NameScope::Workbook, "mutabletotal")
                .expect("defined name after R1C1 set");
            assert_eq!(defined_name.refers_to.text, "Sheet1!R3C3");
            assert!(defined_name.refers_to.is_r1c1);
        }

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after RefersTo setters");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved workbook package");
        let workbook_xml = String::from_utf8(
            saved_package
                .part("xl/workbook.xml")
                .expect("saved workbook xml")
                .bytes
                .clone(),
        )
        .expect("workbook xml utf8");
        assert!(workbook_xml
            .contains(r#"<definedName name="MutableTotal">Sheet1!R3C3</definedName>"#));

        assert_eq!(
            runtime
                .dispatch_set(name, "RefersTo", OmValue::Number(1.0), &[])
                .expect_err("Name.RefersTo rejects non-text")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    name,
                    "RefersTo",
                    OmValue::Text("=Sheet1!$A$1".to_string()),
                    &[OmValue::Missing],
                )
                .expect_err("Name.RefersTo rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

