    #[test]
    fn application_calculate_updates_basic_formula_cached_values() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let a1_a2 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:A2".to_string())])
                .expect("Range(A1:A2)"),
        );
        let b1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Range(B1)"),
        );
        let b2 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B2".to_string())])
                .expect("Range(B2)"),
        );
        let c1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C1".to_string())])
                .expect("Range(C1)"),
        );

        runtime
            .dispatch_set(
                a1_a2,
                "Value2",
                OmValue::Array(
                    OmArray::new(2, 1, vec![OmValue::Number(2.0), OmValue::Number(3.0)])
                        .expect("values"),
                ),
                &[],
            )
            .expect("set source values");
        runtime
            .dispatch_set(b1, "Formula", OmValue::Text("=A1+A2*4".to_string()), &[])
            .expect("set B1 Formula");
        runtime
            .dispatch_set(
                b2,
                "Formula",
                OmValue::Text("=SUM(A1:A2, 5)".to_string()),
                &[],
            )
            .expect("set B2 Formula");
        runtime
            .dispatch_set(
                c1,
                "FormulaR1C1",
                OmValue::Text("=RC[-2]+R[1]C[-2]".to_string()),
                &[],
            )
            .expect("set C1 FormulaR1C1");

        assert_eq!(
            runtime
                .dispatch_get(b1, "Value2", &[])
                .expect("B1 Value2 before Calculate"),
            OmValue::Empty
        );
        runtime
            .dispatch_invoke(runtime.root_application(), "Calculate", &[])
            .expect("Application.Calculate");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(b1, "Value2", &[])
                    .expect("B1 Value2 after Calculate")
            ),
            14.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(b2, "Value2", &[])
                    .expect("B2 Value2 after Calculate")
            ),
            10.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(c1, "Value2", &[])
                    .expect("C1 Value2 after Calculate")
            ),
            5.0
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved remains dirty after formula edits")
        ));
    }

    #[test]
    fn application_calculate_updates_basic_aggregate_functions() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:A4".to_string())])
                .expect("Range(A1:A4)"),
        );
        let formulas = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1:B4".to_string())])
                .expect("Range(B1:B4)"),
        );

        runtime
            .dispatch_set(
                source,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        4,
                        1,
                        vec![
                            OmValue::Number(2.0),
                            OmValue::Number(8.0),
                            OmValue::Number(5.0),
                            OmValue::Text("ignored".to_string()),
                        ],
                    )
                    .expect("source values"),
                ),
                &[],
            )
            .expect("set aggregate source values");
        runtime
            .dispatch_set(
                formulas,
                "Formula",
                OmValue::Array(
                    OmArray::new(
                        4,
                        1,
                        vec![
                            OmValue::Text("=MIN(A1:A4)".to_string()),
                            OmValue::Text("=MAX(A1:A4)".to_string()),
                            OmValue::Text("=AVERAGE(A1:A4)".to_string()),
                            OmValue::Text("=COUNT(A1:A4)".to_string()),
                        ],
                    )
                    .expect("aggregate formulas"),
                ),
                &[],
            )
            .expect("set aggregate formulas");

        runtime
            .dispatch_invoke(runtime.root_application(), "Calculate", &[])
            .expect("Application.Calculate");

        let values = runtime
            .dispatch_get(formulas, "Value2", &[])
            .expect("aggregate values after Calculate");
        let OmValue::Array(values) = values else {
            panic!("expected aggregate value array");
        };
        assert_eq!(
            values.values,
            vec![
                OmValue::Number(2.0),
                OmValue::Number(8.0),
                OmValue::Number(5.0),
                OmValue::Number(3.0),
            ]
        );
    }

