    #[test]
    fn application_separator_dispatch_roundtrips_and_rejects_invalid_values() {
        let mut runtime = ExcelRuntime::new();
        let application = runtime.root_application();

        assert!(expect_bool(
            runtime
                .dispatch_get(application, "UseSystemSeparators", &[])
                .expect("Application.UseSystemSeparators default")
        ));
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application, "DecimalSeparator", &[])
                    .expect("Application.DecimalSeparator default")
            ),
            "."
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application, "ThousandsSeparator", &[])
                    .expect("Application.ThousandsSeparator default")
            ),
            ","
        );

        runtime
            .dispatch_set(
                application,
                "UseSystemSeparators",
                OmValue::Bool(false),
                &[],
            )
            .expect("Application.UseSystemSeparators = false");
        runtime
            .dispatch_set(
                application,
                "DecimalSeparator",
                OmValue::Text(",".to_string()),
                &[],
            )
            .expect("Application.DecimalSeparator = comma");
        runtime
            .dispatch_set(
                application,
                "ThousandsSeparator",
                OmValue::Text(".".to_string()),
                &[],
            )
            .expect("Application.ThousandsSeparator = period");

        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "UseSystemSeparators", &[])
                .expect("Application.UseSystemSeparators after false")
        ));
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application, "DecimalSeparator", &[])
                    .expect("Application.DecimalSeparator after set")
            ),
            ","
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application, "ThousandsSeparator", &[])
                    .expect("Application.ThousandsSeparator after set")
            ),
            "."
        );

        assert_eq!(
            runtime
                .dispatch_set(
                    application,
                    "UseSystemSeparators",
                    OmValue::Text("bad".to_string()),
                    &[]
                )
                .expect_err("Application.UseSystemSeparators should reject non-bool values")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_set(application, "DecimalSeparator", OmValue::Bool(true), &[])
                .expect_err("Application.DecimalSeparator should reject non-text values")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_set(application, "ThousandsSeparator", OmValue::Bool(true), &[])
                .expect_err("Application.ThousandsSeparator should reject non-text values")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "UseSystemSeparators", &[OmValue::Number(1.0)])
                .expect_err("Application.UseSystemSeparators should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "DecimalSeparator", &[OmValue::Number(1.0)])
                .expect_err("Application.DecimalSeparator should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "ThousandsSeparator", &[OmValue::Number(1.0)])
                .expect_err("Application.ThousandsSeparator should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn application_international_dispatch_reports_separator_settings() {
        let mut runtime = ExcelRuntime::new();
        let application = runtime.root_application();

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_DECIMAL_SEPARATOR))]
                    )
                    .expect("Application.International(xlDecimalSeparator)")
            ),
            "."
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_THOUSANDS_SEPARATOR))]
                    )
                    .expect("Application.International(xlThousandsSeparator)")
            ),
            ","
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_LIST_SEPARATOR))]
                    )
                    .expect("Application.International(xlListSeparator)")
            ),
            ","
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_COUNTRY_CODE))]
                    )
                    .expect("Application.International(xlCountryCode)")
            ),
            1.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_DATE_SEPARATOR))]
                    )
                    .expect("Application.International(xlDateSeparator)")
            ),
            "/"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_TIME_SEPARATOR))]
                    )
                    .expect("Application.International(xlTimeSeparator)")
            ),
            ":"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_UPPER_CASE_ROW_LETTER))]
                    )
                    .expect("Application.International(xlUpperCaseRowLetter)")
            ),
            "R"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_UPPER_CASE_COLUMN_LETTER))]
                    )
                    .expect("Application.International(xlUpperCaseColumnLetter)")
            ),
            "C"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_CURRENCY_CODE))]
                    )
                    .expect("Application.International(xlCurrencyCode)")
            ),
            "$"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_CURRENCY_DIGITS))]
                    )
                    .expect("Application.International(xlCurrencyDigits)")
            ),
            2.0
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(
                    application,
                    "International",
                    &[OmValue::Number(f64::from(XL_24_HOUR_CLOCK))]
                )
                .expect("Application.International(xl24HourClock)")
        ));
        assert!(expect_bool(
            runtime
                .dispatch_get(
                    application,
                    "International",
                    &[OmValue::Number(f64::from(XL_4_DIGIT_YEARS))]
                )
                .expect("Application.International(xl4DigitYears)")
        ));
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_COLUMN_SEPARATOR))]
                    )
                    .expect("Application.International(xlColumnSeparator)")
            ),
            ","
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_ROW_SEPARATOR))]
                    )
                    .expect("Application.International(xlRowSeparator)")
            ),
            ";"
        );

        runtime
            .dispatch_set(
                application,
                "DecimalSeparator",
                OmValue::Text(",".to_string()),
                &[],
            )
            .expect("Application.DecimalSeparator = comma");
        runtime
            .dispatch_set(
                application,
                "ThousandsSeparator",
                OmValue::Text(".".to_string()),
                &[],
            )
            .expect("Application.ThousandsSeparator = period");

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_DECIMAL_SEPARATOR))]
                    )
                    .expect("Application.International decimal after set")
            ),
            ","
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_THOUSANDS_SEPARATOR))]
                    )
                    .expect("Application.International thousands after set")
            ),
            "."
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_LIST_SEPARATOR))]
                    )
                    .expect("Application.International list separator after set")
            ),
            ";"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        application,
                        "International",
                        &[OmValue::Number(f64::from(XL_COLUMN_SEPARATOR))]
                    )
                    .expect("Application.International column separator after set")
            ),
            ";"
        );

        assert_eq!(
            runtime
                .dispatch_get(application, "International", &[])
                .expect_err("Application.International should require an index")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_get(
                    application,
                    "International",
                    &[OmValue::Text("bad".to_string())]
                )
                .expect_err("Application.International should reject non-numeric indexes")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "International", &[OmValue::Number(3.5)])
                .expect_err("Application.International should reject fractional indexes")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "International", &[OmValue::Number(99.0)])
                .expect_err("Application.International should reject unsupported indexes")
                .code,
            OmErrorCode::Unsupported
        );
    }

