    #[test]
    fn range_multi_area_clear_methods_apply_each_area() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let clear_formats_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("E2,F3:G3".to_string())],
                )
                .expect("Range(E2,F3:G3)"),
        );
        let clear_contents_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("H2,I3:J3".to_string())],
                )
                .expect("Range(H2,I3:J3)"),
        );
        let clear_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("K2,L3:M3".to_string())],
                )
                .expect("Range(K2,L3:M3)"),
        );
        runtime
            .dispatch_set(
                clear_formats_range,
                "Value2",
                OmValue::Text("kept".to_string()),
                &[],
            )
            .expect("seed clear-format values");
        runtime
            .dispatch_set(
                clear_contents_range,
                "Formula",
                OmValue::Text("=ROW()".to_string()),
                &[],
            )
            .expect("seed clear-contents formulas");
        runtime
            .dispatch_set(
                clear_range,
                "Value2",
                OmValue::Text("removed".to_string()),
                &[],
            )
            .expect("seed clear values");
        let sheet_id = runtime
            .runtime_workbook(workbook)
            .expect("runtime workbook")
            .loaded
            .state
            .worksheets
            .first()
            .expect("worksheet")
            .id;
        {
            let worksheet = runtime
                .runtime_workbook_mut(workbook)
                .expect("runtime workbook mut")
                .loaded
                .state
                .worksheet_data_for_sheet_mut(sheet_id)
                .expect("worksheet data");
            for key in [
                (2, 5),
                (3, 6),
                (3, 7),
                (2, 8),
                (3, 9),
                (3, 10),
                (2, 11),
                (3, 12),
                (3, 13),
            ] {
                worksheet.cells.get_mut(&key).expect("seeded cell").style_id = Some(StyleId(0));
            }
        }
        runtime
            .dispatch_set(workbook.0, "Saved", OmValue::Bool(true), &[])
            .expect("reset Workbook.Saved before multi-area clear");

        assert_eq!(
            runtime
                .dispatch_invoke(clear_formats_range, "ClearFormats", &[])
                .expect("multi-area ClearFormats"),
            OmValue::Empty
        );
        for address in ["E2", "F3", "G3"] {
            let cell = expect_object_handle(
                runtime
                    .dispatch_invoke(active_sheet, "Range", &[OmValue::Text(address.to_string())])
                    .expect("cell range after multi-area ClearFormats"),
            );
            assert_eq!(
                expect_text(
                    runtime
                        .dispatch_get(cell, "Value2", &[])
                        .expect("cell Value2 after multi-area ClearFormats")
                ),
                "kept"
            );
        }
        {
            let worksheet = runtime
                .runtime_workbook(workbook)
                .expect("runtime workbook after ClearFormats")
                .loaded
                .state
                .worksheet_data_for_sheet(sheet_id)
                .expect("worksheet data after ClearFormats");
            for key in [(2, 5), (3, 6), (3, 7)] {
                assert_eq!(
                    worksheet
                        .cells
                        .get(&key)
                        .expect("format-cleared cell")
                        .style_id,
                    None
                );
            }
        }

        assert_eq!(
            runtime
                .dispatch_invoke(clear_contents_range, "ClearContents", &[])
                .expect("multi-area ClearContents"),
            OmValue::Empty
        );
        for address in ["H2", "I3", "J3"] {
            let cell = expect_object_handle(
                runtime
                    .dispatch_invoke(active_sheet, "Range", &[OmValue::Text(address.to_string())])
                    .expect("cell range after multi-area ClearContents"),
            );
            assert_eq!(
                runtime
                    .dispatch_get(cell, "Formula", &[])
                    .expect("cell Formula after multi-area ClearContents"),
                OmValue::Empty
            );
        }
        {
            let worksheet = runtime
                .runtime_workbook(workbook)
                .expect("runtime workbook after ClearContents")
                .loaded
                .state
                .worksheet_data_for_sheet(sheet_id)
                .expect("worksheet data after ClearContents");
            for key in [(2, 8), (3, 9), (3, 10)] {
                assert_eq!(
                    worksheet
                        .cells
                        .get(&key)
                        .expect("contents-cleared style shell")
                        .style_id,
                    Some(StyleId(0))
                );
            }
        }

        assert_eq!(
            runtime
                .dispatch_invoke(clear_range, "Clear", &[])
                .expect("multi-area Clear"),
            OmValue::Empty
        );
        {
            let worksheet = runtime
                .runtime_workbook(workbook)
                .expect("runtime workbook after Clear")
                .loaded
                .state
                .worksheet_data_for_sheet(sheet_id)
                .expect("worksheet data after Clear");
            for key in [(2, 11), (3, 12), (3, 13)] {
                assert!(
                    worksheet.cells.get(&key).is_none(),
                    "Range.Clear should remove multi-area cell {key:?}"
                );
            }
        }
        assert_eq!(
            runtime
                .dispatch_invoke(clear_range, "Clear", &[OmValue::Bool(true)])
                .expect_err("multi-area Clear rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after multi-area clear")
        ));
    }

    #[test]
    fn range_dispatch_rows_and_columns_project_count_over_same_rect() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );
        let rows = expect_object_handle(
            runtime
                .dispatch_get(range, "Rows", &[])
                .expect("Range.Rows"),
        );
        let columns = expect_object_handle(
            runtime
                .dispatch_get(range, "Columns", &[])
                .expect("Range.Columns"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(rows, "Address", &[])
                    .expect("Rows.Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(columns, "Address", &[])
                    .expect("Columns.Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(range, "Count", &[])
                    .expect("Range.Count")
            ),
            4.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(rows, "Count", &[])
                    .expect("Rows.Count")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(columns, "Count", &[])
                    .expect("Columns.Count")
            ),
            2.0
        );
        let rows_columns = expect_object_handle(
            runtime
                .dispatch_get(rows, "Columns", &[])
                .expect("Rows.Columns"),
        );
        let columns_rows = expect_object_handle(
            runtime
                .dispatch_get(columns, "Rows", &[])
                .expect("Columns.Rows"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(rows_columns, "Count", &[])
                    .expect("Rows.Columns.Count")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(columns_rows, "Count", &[])
                    .expect("Columns.Rows.Count")
            ),
            2.0
        );
        let rows_parent = expect_object_handle(
            runtime
                .dispatch_get(rows, "Parent", &[])
                .expect("Rows.Parent"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(rows_parent, "Name", &[])
                    .expect("Rows.Parent.Name")
            ),
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet.Name")
            )
        );
    }

    #[test]
    fn range_item_dispatch_supports_2d_ranges_and_row_column_projections() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );
        let rows = expect_object_handle(
            runtime
                .dispatch_get(range, "Rows", &[])
                .expect("Range.Rows"),
        );
        let columns = expect_object_handle(
            runtime
                .dispatch_get(range, "Columns", &[])
                .expect("Range.Columns"),
        );
        let second_cell = expect_object_handle(
            runtime
                .dispatch_invoke(range, "Item", &[OmValue::Number(2.0), OmValue::Number(2.0)])
                .expect("Range.Item(2, 2)"),
        );
        let linear_second_cell = expect_object_handle(
            runtime
                .dispatch_invoke(range, "Item", &[OmValue::Number(2.0)])
                .expect("Range.Item(2)"),
        );
        let second_row = expect_object_handle(
            runtime
                .dispatch_invoke(rows, "Item", &[OmValue::Number(2.0)])
                .expect("Rows.Item(2)"),
        );
        let second_column = expect_object_handle(
            runtime
                .dispatch_invoke(columns, "Item", &[OmValue::Number(2.0)])
                .expect("Columns.Item(2)"),
        );
        let single_row_range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("Range(A1:B1)"),
        );
        let single_row_item = expect_object_handle(
            runtime
                .dispatch_invoke(single_row_range, "Item", &[OmValue::Number(2.0)])
                .expect("Range(A1:B1).Item(2)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_cell, "Address", &[])
                    .expect("Range.Item(2, 2).Address")
            ),
            "$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(linear_second_cell, "Address", &[])
                    .expect("Range.Item(2).Address")
            ),
            "$B$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_row, "Address", &[])
                    .expect("Rows.Item(2).Address")
            ),
            "$A$2:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_column, "Address", &[])
                    .expect("Columns.Item(2).Address")
            ),
            "$B$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(single_row_item, "Address", &[])
                    .expect("Range(A1:B1).Item(2).Address")
            ),
            "$B$1"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_cell, "Count", &[])
                    .expect("Range.Item(2, 2).Count")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_row, "Count", &[])
                    .expect("Rows.Item(2).Count")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_column, "Count", &[])
                    .expect("Columns.Item(2).Count")
            ),
            2.0
        );

        assert_eq!(
            runtime
                .dispatch_invoke(range, "Item", &[OmValue::Number(5.0)])
                .expect_err("Range.Item(5) should be out of bounds")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(rows, "Item", &[OmValue::Number(3.0)])
                .expect_err("Rows.Item(3) should be out of bounds")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn range_item_dispatch_supports_multi_area_row_column_projections() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let workbook_id = runtime.workbook_model(workbook).expect("workbook model").id;
        let sheet_id = runtime.worksheets(workbook).expect("worksheets")[0].id;
        let range = RangeSet::new(
            workbook_id,
            vec![
                RangeArea::new(
                    SheetScope::Single(sheet_id),
                    Rect {
                        row_first: 3,
                        row_last: 4,
                        col_first: 3,
                        col_last: 4,
                    },
                )
                .expect("first area"),
                RangeArea::new(
                    SheetScope::Single(sheet_id),
                    Rect {
                        row_first: 1,
                        row_last: 1,
                        col_first: 1,
                        col_last: 2,
                    },
                )
                .expect("second area"),
            ],
        )
        .expect("multi-area range");
        let rows = runtime
            .register_projected_range_set_handle(workbook, range.clone(), RangeProjection::Rows)
            .0;
        let columns = runtime
            .register_projected_range_set_handle(workbook, range, RangeProjection::Columns)
            .0;
        let second_row = expect_object_handle(
            runtime
                .dispatch_invoke(rows, "Item", &[OmValue::Number(2.0)])
                .expect("multi-area Rows.Item(2)"),
        );
        let second_column = expect_object_handle(
            runtime
                .dispatch_invoke(columns, "Item", &[OmValue::Number(2.0)])
                .expect("multi-area Columns.Item(2)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_row, "Address", &[])
                    .expect("multi-area Rows.Item(2).Address")
            ),
            "$C$4:$D$4"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_column, "Address", &[])
                    .expect("multi-area Columns.Item(2).Address")
            ),
            "$D$3:$D$4"
        );
        assert_eq!(
            runtime
                .dispatch_invoke(rows, "Item", &[OmValue::Number(3.0)])
                .expect_err("multi-area Rows.Item(3) should be out of bounds")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(columns, "Item", &[OmValue::Number(3.0)])
                .expect_err("multi-area Columns.Item(3) should be out of bounds")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn range_projection_properties_accept_direct_index_args() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );
        let second_row = expect_object_handle(
            runtime
                .dispatch_get(range, "Rows", &[OmValue::Number(2.0)])
                .expect("Range.Rows(2)"),
        );
        let second_column = expect_object_handle(
            runtime
                .dispatch_get(range, "Columns", &[OmValue::Number(2.0)])
                .expect("Range.Columns(2)"),
        );
        let linear_second_cell = expect_object_handle(
            runtime
                .dispatch_get(range, "Cells", &[OmValue::Number(2.0)])
                .expect("Range.Cells(2)"),
        );
        let indexed_cell = expect_object_handle(
            runtime
                .dispatch_get(
                    range,
                    "Cells",
                    &[OmValue::Number(2.0), OmValue::Number(2.0)],
                )
                .expect("Range.Cells(2, 2)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_row, "Address", &[])
                    .expect("Range.Rows(2).Address")
            ),
            "$A$2:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_column, "Address", &[])
                    .expect("Range.Columns(2).Address")
            ),
            "$B$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(linear_second_cell, "Address", &[])
                    .expect("Range.Cells(2).Address")
            ),
            "$B$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(indexed_cell, "Address", &[])
                    .expect("Range.Cells(2, 2).Address")
            ),
            "$B$2"
        );
        assert_eq!(
            runtime
                .dispatch_get(range, "Rows", &[OmValue::Number(3.0)])
                .expect_err("Range.Rows(3) should be out of bounds")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_get(range, "Columns", &[OmValue::Text("B".to_string())])
                .expect_err("Range.Columns(\"B\") should be rejected")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_get(range, "Cells", &[OmValue::Number(0.0)])
                .expect_err("Range.Cells(0) should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn range_dispatch_current_region_expands_contiguous_region_and_preserves_blank_seed() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let formula_cell = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Range(B1)"),
        );
        let partial_region = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("Range(A1:B1)"),
        );
        let formula_current_region = expect_object_handle(
            runtime
                .dispatch_get(formula_cell, "CurrentRegion", &[])
                .expect("B1.CurrentRegion"),
        );
        let partial_current_region = expect_object_handle(
            runtime
                .dispatch_get(partial_region, "CurrentRegion", &[])
                .expect("A1:B1.CurrentRegion"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(formula_current_region, "Address", &[])
                    .expect("B1.CurrentRegion.Address")
            ),
            "$A$1:$C$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(partial_current_region, "Address", &[])
                    .expect("A1:B1.CurrentRegion.Address")
            ),
            "$A$1:$C$1"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(formula_current_region, "Count", &[])
                    .expect("B1.CurrentRegion.Count")
            ),
            3.0
        );

        let blank_workbook = runtime.create_workbook().expect("blank workbook");
        let blank_worksheets = expect_object_handle(
            runtime
                .dispatch_get(blank_workbook.0, "Worksheets", &[])
                .expect("blank worksheets"),
        );
        let blank_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(blank_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("blank worksheet"),
        );
        let blank_seed = expect_object_handle(
            runtime
                .dispatch_invoke(blank_sheet, "Range", &[OmValue::Text("B2".to_string())])
                .expect("blank Range(B2)"),
        );
        let blank_current_region = expect_object_handle(
            runtime
                .dispatch_get(blank_seed, "CurrentRegion", &[])
                .expect("blank B2.CurrentRegion"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(blank_current_region, "Address", &[])
                    .expect("blank B2.CurrentRegion.Address")
            ),
            "$B$2"
        );
    }

    #[test]
    fn range_multi_area_current_region_expands_each_area_in_order() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime.create_workbook().expect("blank workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Worksheets"),
        );
        let worksheet = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheet"),
        );
        let left_region = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );
        let right_region = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("D1:E2".to_string())])
                .expect("Range(D1:E2)"),
        );
        runtime
            .dispatch_set(
                left_region,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        2,
                        2,
                        vec![
                            OmValue::Number(1.0),
                            OmValue::Number(2.0),
                            OmValue::Number(3.0),
                            OmValue::Number(4.0),
                        ],
                    )
                    .expect("left region values"),
                ),
                &[],
            )
            .expect("A1:B2.Value2");
        runtime
            .dispatch_set(
                right_region,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        2,
                        2,
                        vec![
                            OmValue::Number(5.0),
                            OmValue::Number(6.0),
                            OmValue::Number(7.0),
                            OmValue::Number(8.0),
                        ],
                    )
                    .expect("right region values"),
                ),
                &[],
            )
            .expect("D1:E2.Value2");

        let seeds = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1,D1".to_string())])
                .expect("Range(A1,D1)"),
        );
        let current_regions = expect_object_handle(
            runtime
                .dispatch_get(seeds, "CurrentRegion", &[])
                .expect("Range(A1,D1).CurrentRegion"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(current_regions, "Address", &[])
                    .expect("CurrentRegion.Address")
            ),
            "$A$1:$B$2,$D$1:$E$2"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(current_regions, "Count", &[])
                    .expect("CurrentRegion.Count")
            ),
            8.0
        );
        let areas = expect_object_handle(
            runtime
                .dispatch_get(current_regions, "Areas", &[])
                .expect("CurrentRegion.Areas"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(areas, "Count", &[])
                    .expect("CurrentRegion.Areas.Count")
            ),
            2.0
        );
    }

