    #[test]
    fn range_dispatch_formula_reads_formula_text_and_persists_formula_sets() {
        let mut runtime = ExcelRuntime::new();
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let base_dir = std::env::temp_dir().join(format!("ootd-range-formula-{unique}"));
        fs::create_dir_all(&base_dir).expect("create formula fixture dir");
        let source_path = base_dir.join("source.xlsx");
        let target_path = base_dir.join("formula-target.xlsx");
        fs::write(&source_path, synthetic_workbook_bytes()).expect("write source workbook");

        let workbooks = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "Workbooks", &[])
                .expect("Workbooks"),
        );
        let workbook = expect_object_handle(
            runtime
                .dispatch_invoke(
                    workbooks,
                    "Open",
                    &[OmValue::Text(source_path.to_string_lossy().into_owned())],
                )
                .expect("Workbooks.Open"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let formula_cell = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Range(B1)"),
        );
        let constant_cell = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Range(A1)"),
        );
        let new_formula_cell = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C2".to_string())])
                .expect("Range(C2)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(formula_cell, "Formula", &[])
                    .expect("B1 Formula")
            ),
            r#"=UPPER("shared")"#
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(constant_cell, "Formula", &[])
                    .expect("A1 Formula")
            ),
            42.0
        );

        runtime
            .dispatch_set(
                new_formula_cell,
                "Formula",
                OmValue::Text("=SUM(A1:B1)".to_string()),
                &[],
            )
            .expect("set C2 Formula");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(new_formula_cell, "Formula", &[])
                    .expect("C2 Formula")
            ),
            "=SUM(A1:B1)"
        );
        assert_eq!(
            runtime
                .dispatch_get(new_formula_cell, "Value", &[])
                .expect("C2 Value after Formula"),
            OmValue::Empty
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook, "Saved", &[])
                .expect("Workbook.Saved after Formula set")
        ));

        runtime
            .dispatch_invoke(
                workbook,
                "SaveAs",
                &[OmValue::Text(target_path.to_string_lossy().into_owned())],
            )
            .expect("Workbook.SaveAs");

        let reopened = ExcelRuntime::new()
            .codec
            .load(
                &fs::read(&target_path).expect("read formula workbook"),
                LoadOptions::default(),
            )
            .expect("reload formula workbook");
        let reopened_sheet_id = reopened.state.worksheets[0].id;
        let reopened_formula = reopened
            .state
            .cell(reopened_sheet_id, 2, 3)
            .expect("C2 reopened");
        assert_eq!(
            reopened_formula.formula.as_ref().expect("C2 formula").text,
            "SUM(A1:B1)"
        );
        assert_eq!(reopened_formula.value, CellValue::Blank);

        fs::remove_dir_all(&base_dir).expect("cleanup formula fixture");
    }

    #[test]
    fn range_dispatch_formula_r1c1_roundtrips_and_marks_formula_source() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let sheet_id = runtime.worksheets(workbook).expect("worksheets")[0].id;
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let existing_formula = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Range(B1)"),
        );
        let c2_d2 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C2:D2".to_string())])
                .expect("Range(C2:D2)"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(existing_formula, "FormulaR1C1", &[])
                    .expect("B1 FormulaR1C1")
            ),
            r#"=UPPER("shared")"#
        );

        runtime
            .dispatch_set(
                c2_d2,
                "FormulaR1C1",
                OmValue::Array(
                    OmArray::new(
                        1,
                        2,
                        vec![
                            OmValue::Text("=RC[-2]+R[-1]C[-1]".to_string()),
                            OmValue::Text("literal".to_string()),
                        ],
                    )
                    .expect("C2:D2 formulas"),
                ),
                &[],
            )
            .expect("set C2:D2 FormulaR1C1");

        let OmValue::Array(formulas) = runtime
            .dispatch_get(c2_d2, "FormulaR1C1", &[])
            .expect("C2:D2 FormulaR1C1")
        else {
            panic!("expected FormulaR1C1 array");
        };
        assert_eq!(
            formulas.values,
            vec![
                OmValue::Text("=RC[-2]+R[-1]C[-1]".to_string()),
                OmValue::Text("literal".to_string()),
            ]
        );

        let state = runtime.workbook_state(workbook).expect("workbook state");
        let c2 = state.cell(sheet_id, 2, 3).expect("C2");
        let c2_formula = c2.formula.as_ref().expect("C2 formula");
        assert_eq!(c2_formula.text, "RC[-2]+R[-1]C[-1]");
        assert!(c2_formula.is_r1c1);
        let d2 = state.cell(sheet_id, 2, 4).expect("D2");
        assert_eq!(d2.value, CellValue::Text("literal".to_string()));
        assert!(d2.formula.is_none());
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after FormulaR1C1 set")
        ));

        let mut read_only_runtime = ExcelRuntime::new();
        read_only_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only workbook");
        let read_only_sheet = expect_object_handle(
            read_only_runtime
                .dispatch_get(read_only_runtime.root_application(), "ActiveSheet", &[])
                .expect("read-only ActiveSheet"),
        );
        let read_only_cell = expect_object_handle(
            read_only_runtime
                .dispatch_invoke(read_only_sheet, "Range", &[OmValue::Text("C2".to_string())])
                .expect("read-only Range(C2)"),
        );
        assert_eq!(
            read_only_runtime
                .dispatch_set(
                    read_only_cell,
                    "FormulaR1C1",
                    OmValue::Text("=R1C1".to_string()),
                    &[],
                )
                .expect_err("Range.FormulaR1C1 should reject read-only workbooks")
                .code,
            OmErrorCode::InvalidState
        );
    }

    #[test]
    fn range_formula_getters_convert_between_a1_and_r1c1_references() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let c2 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C2".to_string())])
                .expect("Range(C2)"),
        );
        let d3 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D3".to_string())])
                .expect("Range(D3)"),
        );

        runtime
            .dispatch_set(
                c2,
                "Formula",
                OmValue::Text(
                    r#"=A1+$B1+B$1+$B$1&"A1"&LOG10(A1)+SUM(A:A)+SUM($B:$C)+SUM(1:1)+SUM($2:$3)"#
                        .to_string(),
                ),
                &[],
            )
            .expect("set C2 Formula");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(c2, "FormulaR1C1", &[])
                    .expect("C2 FormulaR1C1 from A1 formula")
            ),
            r#"=R[-1]C[-2]+R[-1]C2+R1C[-1]+R1C2&"A1"&LOG10(R[-1]C[-2])+SUM(C[-2])+SUM(C2:C3)+SUM(R[-1])+SUM(R2:R3)"#
        );

        runtime
            .dispatch_set(
                d3,
                "FormulaR1C1",
                OmValue::Text(
                    r#"=RC[-2]+R1C1+R[-1]C&"R1C1"&ROW()+SUM(C[-2])+SUM(C1:C2)+SUM(R[-1])+SUM(R1:R2)"#
                        .to_string(),
                ),
                &[],
            )
            .expect("set D3 FormulaR1C1");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(d3, "Formula", &[])
                    .expect("D3 Formula from R1C1 formula")
            ),
            r#"=B3+$A$1+D2&"R1C1"&ROW()+SUM(B:B)+SUM($A:$B)+SUM(2:2)+SUM($1:$2)"#
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after formula conversion set")
        ));
    }

    #[test]
    fn range_dispatch_formula2_aliases_formula_storage_paths() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let sheet_id = runtime.worksheets(workbook).expect("worksheets")[0].id;
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let c3 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C3".to_string())])
                .expect("Range(C3)"),
        );
        let d3 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D3".to_string())])
                .expect("Range(D3)"),
        );

        runtime
            .dispatch_set(
                c3,
                "Formula2",
                OmValue::Text("=SUM(A1:B1)".to_string()),
                &[],
            )
            .expect("set C3 Formula2");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(c3, "Formula2", &[])
                    .expect("C3 Formula2")
            ),
            "=SUM(A1:B1)"
        );
        let c3_formula = runtime
            .workbook_state(workbook)
            .expect("workbook state")
            .cell(sheet_id, 3, 3)
            .expect("C3")
            .formula
            .as_ref()
            .expect("C3 formula")
            .clone();
        assert_eq!(c3_formula.text, "SUM(A1:B1)");
        assert!(!c3_formula.is_r1c1);

        runtime
            .dispatch_set(
                d3,
                "Formula2R1C1",
                OmValue::Text("=RC[-1]*2".to_string()),
                &[],
            )
            .expect("set D3 Formula2R1C1");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(d3, "Formula2R1C1", &[])
                    .expect("D3 Formula2R1C1")
            ),
            "=RC[-1]*2"
        );
        let d3_formula = runtime
            .workbook_state(workbook)
            .expect("workbook state")
            .cell(sheet_id, 3, 4)
            .expect("D3")
            .formula
            .as_ref()
            .expect("D3 formula")
            .clone();
        assert_eq!(d3_formula.text, "RC[-1]*2");
        assert!(d3_formula.is_r1c1);
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Formula2 set")
        ));
    }

