    #[test]
    fn range_copy_rejects_invalid_destinations() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let active_workbook = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveWorkbook", &[])
                .expect("ActiveWorkbook"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("Range(A1:B1)"),
        );
        let mismatched_destination = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A2:C2".to_string())])
                .expect("Range(A2:C2)"),
        );

        assert_eq!(
            runtime
                .dispatch_invoke(source, "Copy", &[OmValue::Text("A2".to_string())])
                .expect_err("Range.Copy should reject non-object Destination")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(source, "Copy", &[OmValue::Object(active_workbook)])
                .expect_err("Range.Copy should reject non-Range objects")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(source, "Copy", &[OmValue::Object(mismatched_destination)])
                .expect_err("Range.Copy should reject mismatched destination size")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    source,
                    "Copy",
                    &[OmValue::Missing, OmValue::Object(mismatched_destination)]
                )
                .expect_err("Range.Copy should reject extra args")
                .code,
            OmErrorCode::InvalidArgument
        );
        let single_cell_destination = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("E5".to_string())])
                .expect("Range(E5)"),
        );
        let multi_area_source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1,C1".to_string())])
                .expect("Range(A1,C1)"),
        );
        let multi_area_destination = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("E5,G5".to_string())])
                .expect("Range(E5,G5)"),
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    multi_area_source,
                    "Copy",
                    &[OmValue::Object(single_cell_destination)]
                )
                .expect_err("Range.Copy should reject multi-area source materialization")
                .code,
            OmErrorCode::Unsupported
        );
        assert_eq!(
            runtime
                .dispatch_invoke(source, "Copy", &[OmValue::Object(multi_area_destination)])
                .expect_err("Range.Copy should reject multi-area Destination materialization")
                .code,
            OmErrorCode::Unsupported
        );
    }

    #[test]
    fn range_cut_sets_cut_copy_mode_and_moves_to_destination_range() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("Range(A1:B1)"),
        );
        let destination = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D2".to_string())])
                .expect("Range(D2)"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(source, "Cut", &[])
                .expect("Range.Cut without destination"),
            OmValue::Empty
        ));
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode after Range.Cut")
            ),
            f64::from(super::XL_CUT)
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(source, "Cut", &[OmValue::Object(destination)])
                .expect("Range.Cut Destination"),
            OmValue::Empty
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after destination cut")
        ));

        let a1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Range(A1)"),
        );
        let b1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Range(B1)"),
        );
        let d2 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D2".to_string())])
                .expect("Range(D2)"),
        );
        let e2 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("E2".to_string())])
                .expect("Range(E2)"),
        );
        assert_eq!(
            runtime
                .dispatch_get(a1, "Value", &[])
                .expect("A1 Value after cut"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_get(b1, "Value", &[])
                .expect("B1 Value after cut"),
            OmValue::Empty
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(d2, "Value", &[])
                    .expect("D2 Value after cut")
            ),
            42.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(e2, "Formula", &[])
                    .expect("E2 Formula after cut")
            ),
            r#"=UPPER("shared")"#
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Range.Cut")
        ));
    }

    #[test]
    fn range_cut_destination_supports_cross_workbook_ranges() {
        let mut runtime = ExcelRuntime::new();
        let source_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open source workbook");
        let destination_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open destination workbook");
        let source_worksheets = expect_object_handle(
            runtime
                .dispatch_get(source_workbook.0, "Worksheets", &[])
                .expect("source Workbook.Worksheets"),
        );
        let source_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(source_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("source Worksheets.Item(1)"),
        );
        let destination_worksheets = expect_object_handle(
            runtime
                .dispatch_get(destination_workbook.0, "Worksheets", &[])
                .expect("destination Workbook.Worksheets"),
        );
        let destination_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(destination_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("destination Worksheets.Item(1)"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(source_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("source Range(A1:B1)"),
        );
        let destination = expect_object_handle(
            runtime
                .dispatch_invoke(
                    destination_sheet,
                    "Range",
                    &[OmValue::Text("C3".to_string())],
                )
                .expect("destination Range(C3)"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(source, "Cut", &[OmValue::Object(destination)])
                .expect("Range.Cut cross-workbook Destination"),
            OmValue::Empty
        ));

        let source_a1 = expect_object_handle(
            runtime
                .dispatch_invoke(source_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("source Range(A1)"),
        );
        let source_b1 = expect_object_handle(
            runtime
                .dispatch_invoke(source_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("source Range(B1)"),
        );
        let destination_c3 = expect_object_handle(
            runtime
                .dispatch_invoke(
                    destination_sheet,
                    "Range",
                    &[OmValue::Text("C3".to_string())],
                )
                .expect("destination Range(C3)"),
        );
        let destination_d3 = expect_object_handle(
            runtime
                .dispatch_invoke(
                    destination_sheet,
                    "Range",
                    &[OmValue::Text("D3".to_string())],
                )
                .expect("destination Range(D3)"),
        );
        assert_eq!(
            runtime
                .dispatch_get(source_a1, "Value", &[])
                .expect("source A1 Value after cut"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_get(source_b1, "Value", &[])
                .expect("source B1 Value after cut"),
            OmValue::Empty
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(destination_c3, "Value", &[])
                    .expect("destination C3 Value after cut")
            ),
            42.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(destination_d3, "Formula", &[])
                    .expect("destination D3 Formula after cut")
            ),
            r#"=UPPER("shared")"#
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(source_workbook.0, "Saved", &[])
                .expect("source Workbook.Saved after Range.Cut")
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(destination_workbook.0, "Saved", &[])
                .expect("destination Workbook.Saved after Range.Cut")
        ));
    }

