    #[test]
    fn loaded_chart_child_select_methods_activate_embedded_chart() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let chart_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "ChartArea", &[])
                .expect("Chart.ChartArea"),
        );
        let plot_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "PlotArea", &[])
                .expect("Chart.PlotArea"),
        );
        let chart_title = expect_object_handle(
            runtime
                .dispatch_get(chart, "ChartTitle", &[])
                .expect("Chart.ChartTitle"),
        );
        let legend = expect_object_handle(
            runtime
                .dispatch_get(chart, "Legend", &[])
                .expect("Chart.Legend"),
        );
        let category_axis = expect_object_handle(
            runtime
                .dispatch_get(
                    chart,
                    "Axes",
                    &[OmValue::Number(f64::from(super::XL_CATEGORY))],
                )
                .expect("Chart.Axes(xlCategory)"),
        );
        let axis_title = expect_object_handle(
            runtime
                .dispatch_get(category_axis, "AxisTitle", &[])
                .expect("Axis.AxisTitle"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1)"),
        );

        for (target, label) in [
            (chart_area, "ChartArea.Select"),
            (plot_area, "PlotArea.Select"),
            (chart_title, "ChartTitle.Select"),
            (legend, "Legend.Select"),
            (category_axis, "Axis.Select"),
            (axis_title, "AxisTitle.Select"),
            (series, "Series.Select"),
        ] {
            runtime
                .dispatch_invoke(worksheet, "Activate", &[])
                .expect("Worksheet.Activate clears ActiveChart");
            assert_eq!(
                runtime
                    .dispatch_get(runtime.root_application(), "ActiveChart", &[])
                    .expect("ActiveChart after Worksheet.Activate"),
                OmValue::Empty
            );
            runtime
                .dispatch_invoke(target, "Select", &[])
                .unwrap_or_else(|error| panic!("{label} failed: {error:?}"));
            let active_chart = expect_object_handle(
                runtime
                    .dispatch_get(runtime.root_application(), "ActiveChart", &[])
                    .unwrap_or_else(|error| panic!("ActiveChart after {label} failed: {error:?}")),
            );
            assert_eq!(
                expect_text(
                    runtime
                        .dispatch_get(active_chart, "Name", &[])
                        .unwrap_or_else(|error| panic!(
                            "ActiveChart.Name after {label} failed: {error:?}"
                        ))
                ),
                "Embedded Revenue Chart"
            );
        }

        assert_eq!(
            runtime
                .dispatch_invoke(chart_title, "Select", &[OmValue::Bool(true)])
                .expect_err("ChartTitle.Select rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn worksheet_delete_removes_chart_sheet_parts_and_bindings() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let charts = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Charts", &[])
                .expect("Workbook.Charts"),
        );
        runtime
            .dispatch_invoke(charts, "Add", &[])
            .expect("Charts.Add");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(charts, "Count", &[])
                    .expect("Charts.Count after Add")
            ),
            1.0
        );
        let chart_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet after Charts.Add"),
        );
        runtime
            .dispatch_set(application, "DisplayAlerts", OmValue::Bool(false), &[])
            .expect("disable DisplayAlerts");
        assert_eq!(
            runtime
                .dispatch_invoke(chart_sheet, "Delete", &[])
                .expect("delete chart sheet"),
            OmValue::Bool(true)
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(charts, "Count", &[])
                    .expect("Charts.Count after Delete")
            ),
            0.0
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after chart sheet delete");
        let saved_package =
            OpcPackage::from_bytes(&saved).expect("saved chart sheet delete package");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen chart sheet delete workbook");

        assert!(!saved_package.contains("xl/chartsheets/sheet1.xml"));
        assert!(!saved_package.contains("xl/chartsheets/_rels/sheet1.xml.rels"));
        assert!(!saved_package.contains("xl/drawings/drawing1.xml"));
        assert!(!saved_package.contains("xl/drawings/_rels/drawing1.xml.rels"));
        assert!(!saved_package.contains("xl/charts/chart1.xml"));
        assert_eq!(
            reopened
                .state
                .worksheets
                .iter()
                .map(|worksheet| worksheet.name.clone())
                .collect::<Vec<_>>(),
            vec!["Sheet1".to_string()]
        );
        assert!(reopened.state.chart_sheets.is_empty());
        assert!(reopened.state.drawings.is_empty());
        assert!(reopened.state.charts.is_empty());
    }

    #[test]
    fn chart_delete_removes_persisted_chart_sheet_support_parts() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_support_parts_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with embedded chart support parts");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        runtime
            .dispatch_invoke(
                chart,
                "Move",
                &[OmValue::Missing, OmValue::Object(worksheet)],
            )
            .expect("embedded Chart.Move after worksheet");
        let moved_saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after support-part Chart.Move");
        let moved_package = OpcPackage::from_bytes(&moved_saved).expect("moved package");
        assert!(
            moved_package.parts().iter().any(|part| {
                part.name.starts_with("xl/charts/style")
                    && part.name.ends_with(".xml")
                    && String::from_utf8_lossy(&part.bytes).contains(r#"id="404""#)
            }),
            "moved chart sheet style support part should exist before delete"
        );
        assert!(
            moved_package.parts().iter().any(|part| {
                part.name.starts_with("xl/charts/colors")
                    && part.name.ends_with(".xml")
                    && String::from_utf8_lossy(&part.bytes).contains(r#"id="404""#)
            }),
            "moved chart sheet color support part should exist before delete"
        );

        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: moved_saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen moved chart sheet support workbook");
        let application = runtime.root_application();
        let charts = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Charts", &[])
                .expect("Workbook.Charts"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_invoke(charts, "Item", &[OmValue::Number(1.0)])
                .expect("Charts.Item(1)"),
        );
        runtime
            .dispatch_set(application, "DisplayAlerts", OmValue::Bool(false), &[])
            .expect("disable DisplayAlerts");
        assert_eq!(
            runtime
                .dispatch_invoke(chart, "Delete", &[])
                .expect("Chart.Delete"),
            OmValue::Bool(true)
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after support-part Chart.Delete");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        assert!(!saved_package.contains("xl/chartsheets/sheet1.xml"));
        assert!(!saved_package.contains("xl/chartsheets/_rels/sheet1.xml.rels"));
        assert!(!saved_package.contains("xl/drawings/drawing1.xml"));
        assert!(!saved_package.contains("xl/drawings/_rels/drawing1.xml.rels"));
        assert!(!saved_package.contains("xl/charts/chart2.xml"));
        assert!(!saved_package.contains("xl/charts/_rels/chart2.xml.rels"));
        assert!(
            !saved_package
                .parts()
                .iter()
                .any(|part| part.name.starts_with("xl/charts/style"))
        );
        assert!(
            !saved_package
                .parts()
                .iter()
                .any(|part| part.name.starts_with("xl/charts/colors"))
        );
        let saved_content_types = String::from_utf8(
            saved_package
                .part("[Content_Types].xml")
                .expect("saved content types")
                .bytes
                .clone(),
        )
        .expect("content types utf8");
        assert!(!saved_content_types.contains("/xl/chartsheets/sheet1.xml"));
        assert!(!saved_content_types.contains("/xl/drawings/drawing1.xml"));
        assert!(!saved_content_types.contains("/xl/charts/chart2.xml"));
        assert!(!saved_content_types.contains("/xl/charts/style"));
        assert!(!saved_content_types.contains("/xl/charts/colors"));

        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen chart sheet support delete workbook");
        assert!(reopened.state.chart_sheets.is_empty());
        assert!(reopened.state.drawings.is_empty());
        assert!(reopened.state.charts.is_empty());
    }

    #[test]
    fn chartobject_visible_roundtrips_non_visual_hidden_attr() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );

        assert_eq!(
            runtime
                .dispatch_get(chart_object, "Visible", &[])
                .expect("initial ChartObject.Visible"),
            OmValue::Bool(false)
        );
        runtime
            .dispatch_set(chart_object, "Visible", OmValue::Bool(true), &[])
            .expect("set ChartObject.Visible true");
        assert_eq!(
            runtime
                .dispatch_get(chart_object, "Visible", &[])
                .expect("ChartObject.Visible after true"),
            OmValue::Bool(true)
        );
        let visible_bytes = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save visible chart object");
        let visible_package = OpcPackage::from_bytes(&visible_bytes).expect("visible package");
        let visible_drawing = String::from_utf8(
            visible_package
                .part("xl/drawings/drawing1.xml")
                .expect("visible drawing part")
                .bytes
                .clone(),
        )
        .expect("visible drawing utf8");
        assert!(!visible_drawing.contains(r#"hidden="1""#));

        runtime
            .dispatch_set(chart_object, "Visible", OmValue::Bool(false), &[])
            .expect("set ChartObject.Visible false");
        assert_eq!(
            runtime
                .dispatch_get(chart_object, "Visible", &[])
                .expect("ChartObject.Visible after false"),
            OmValue::Bool(false)
        );
        let hidden_bytes = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save hidden chart object");
        let hidden_package = OpcPackage::from_bytes(&hidden_bytes).expect("hidden package");
        let hidden_drawing = String::from_utf8(
            hidden_package
                .part("xl/drawings/drawing1.xml")
                .expect("hidden drawing part")
                .bytes
                .clone(),
        )
        .expect("hidden drawing utf8");
        assert!(hidden_drawing.contains(r#"hidden="1""#));

        let invalid_visible = runtime
            .dispatch_set(chart_object, "Visible", OmValue::Number(1.0), &[])
            .expect_err("ChartObject.Visible should reject non-bool");
        assert_eq!(invalid_visible.code, OmErrorCode::TypeMismatch);
    }

    #[test]
    fn chartobjects_visible_sets_each_chart_object() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let first_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let second_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(24.0),
                        OmValue::Number(30.0),
                        OmValue::Number(180.0),
                        OmValue::Number(90.0),
                    ],
                )
                .expect("ChartObjects.Add second chart"),
        );

        assert_eq!(
            runtime
                .dispatch_get(chart_objects, "Visible", &[])
                .expect("mixed ChartObjects.Visible"),
            OmValue::Bool(false)
        );
        assert_eq!(
            runtime
                .dispatch_get(second_chart_object, "Visible", &[])
                .expect("new ChartObject.Visible"),
            OmValue::Bool(true)
        );
        runtime
            .dispatch_set(chart_objects, "Visible", OmValue::Bool(true), &[])
            .expect("set ChartObjects.Visible true");
        assert_eq!(
            runtime
                .dispatch_get(chart_objects, "Visible", &[])
                .expect("ChartObjects.Visible after true"),
            OmValue::Bool(true)
        );
        assert_eq!(
            runtime
                .dispatch_get(first_chart_object, "Visible", &[])
                .expect("first ChartObject.Visible after true"),
            OmValue::Bool(true)
        );
        assert_eq!(
            runtime
                .dispatch_get(second_chart_object, "Visible", &[])
                .expect("second ChartObject.Visible after true"),
            OmValue::Bool(true)
        );

        runtime
            .dispatch_set(chart_objects, "Visible", OmValue::Bool(false), &[])
            .expect("set ChartObjects.Visible false");
        assert_eq!(
            runtime
                .dispatch_get(first_chart_object, "Visible", &[])
                .expect("first ChartObject.Visible after false"),
            OmValue::Bool(false)
        );
        assert_eq!(
            runtime
                .dispatch_get(second_chart_object, "Visible", &[])
                .expect("second ChartObject.Visible after false"),
            OmValue::Bool(false)
        );
        let hidden_bytes = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save hidden chart objects");
        let hidden_package = OpcPackage::from_bytes(&hidden_bytes).expect("hidden package");
        let hidden_drawing = String::from_utf8(
            hidden_package
                .part("xl/drawings/drawing1.xml")
                .expect("hidden drawing part")
                .bytes
                .clone(),
        )
        .expect("hidden drawing utf8");
        assert_eq!(hidden_drawing.matches(r#"hidden="1""#).count(), 2);

        let invalid_visible = runtime
            .dispatch_set(chart_objects, "Visible", OmValue::Number(1.0), &[])
            .expect_err("ChartObjects.Visible should reject non-bool");
        assert_eq!(invalid_visible.code, OmErrorCode::TypeMismatch);
    }

    #[test]
    fn chartobjects_geometry_setters_transform_collection_bounds() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let first_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let second_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(24.0),
                        OmValue::Number(30.0),
                        OmValue::Number(180.0),
                        OmValue::Number(90.0),
                    ],
                )
                .expect("ChartObjects.Add second chart"),
        );

        runtime
            .dispatch_set(chart_objects, "Left", OmValue::Number(12.0), &[])
            .expect("set ChartObjects.Left");
        runtime
            .dispatch_set(chart_objects, "Top", OmValue::Number(23.0), &[])
            .expect("set ChartObjects.Top");
        runtime
            .dispatch_set(chart_objects, "Width", OmValue::Number(404.0), &[])
            .expect("set ChartObjects.Width");
        runtime
            .dispatch_set(chart_objects, "Height", OmValue::Number(234.0), &[])
            .expect("set ChartObjects.Height");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Left", &[])
                    .expect("ChartObjects.Left after set")
            ),
            12.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Top", &[])
                    .expect("ChartObjects.Top after set")
            ),
            23.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Width", &[])
                    .expect("ChartObjects.Width after set")
            ),
            404.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Height", &[])
                    .expect("ChartObjects.Height after set")
            ),
            234.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Left", &[])
                    .expect("first ChartObject.Left after collection set")
            ),
            12.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Top", &[])
                    .expect("first ChartObject.Top after collection set")
            ),
            23.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Width", &[])
                    .expect("first ChartObject.Width after collection set")
            ),
            200.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Height", &[])
                    .expect("first ChartObject.Height after collection set")
            ),
            100.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Left", &[])
                    .expect("second ChartObject.Left after collection set")
            ),
            56.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Top", &[])
                    .expect("second ChartObject.Top after collection set")
            ),
            77.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Width", &[])
                    .expect("second ChartObject.Width after collection set")
            ),
            360.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Height", &[])
                    .expect("second ChartObject.Height after collection set")
            ),
            180.0
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after ChartObjects geometry set")
        ));

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save chart objects geometry");
        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen chart objects geometry");
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("reopened Workbook.Worksheets(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        assert_eq!(
            expect_number(
                reopened_runtime
                    .dispatch_get(reopened_chart_objects, "Width", &[])
                    .expect("reopened ChartObjects.Width")
            ),
            404.0
        );
        assert_eq!(
            expect_number(
                reopened_runtime
                    .dispatch_get(reopened_chart_objects, "Height", &[])
                    .expect("reopened ChartObjects.Height")
            ),
            234.0
        );

        let invalid_width = reopened_runtime
            .dispatch_set(reopened_chart_objects, "Width", OmValue::Number(-1.0), &[])
            .expect_err("ChartObjects.Width should reject negative values");
        assert_eq!(invalid_width.code, OmErrorCode::InvalidArgument);
        let invalid_left = reopened_runtime
            .dispatch_set(
                reopened_chart_objects,
                "Left",
                OmValue::Text("12".to_string()),
                &[],
            )
            .expect_err("ChartObjects.Left should reject non-number");
        assert_eq!(invalid_left.code, OmErrorCode::TypeMismatch);
    }

