    #[test]
    fn shaperange_zorder_reorders_single_chart_object() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let first_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let first_shape_range = expect_object_handle(
            runtime
                .dispatch_get(first_chart_object, "ShapeRange", &[])
                .expect("ChartObject.ShapeRange"),
        );
        let second_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(24.0),
                        OmValue::Number(30.0),
                        OmValue::Number(180.0),
                        OmValue::Number(90.0),
                    ],
                )
                .expect("ChartObjects.Add second chart"),
        );
        let third_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(48.0),
                        OmValue::Number(60.0),
                        OmValue::Number(120.0),
                        OmValue::Number(80.0),
                    ],
                )
                .expect("ChartObjects.Add third chart"),
        );

        runtime
            .dispatch_invoke(
                first_shape_range,
                "ZOrder",
                &[OmValue::Number(f64::from(super::MSO_BRING_FORWARD))],
            )
            .expect("ShapeRange.ZOrder msoBringForward");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "ZOrder", &[])
                    .expect("first chart object z-order after bring forward")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_shape_range, "ZOrderPosition", &[])
                    .expect("ShapeRange.ZOrderPosition after bring forward")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "ZOrder", &[])
                    .expect("second chart object z-order after bring forward")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(third_chart_object, "ZOrder", &[])
                    .expect("third chart object z-order after bring forward")
            ),
            3.0
        );

        runtime
            .dispatch_invoke(
                first_shape_range,
                "ZOrder",
                &[OmValue::Number(f64::from(super::MSO_SEND_BACKWARD))],
            )
            .expect("ShapeRange.ZOrder msoSendBackward");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "ZOrder", &[])
                    .expect("first chart object z-order after send backward")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_shape_range, "ZOrderPosition", &[])
                    .expect("ShapeRange.ZOrderPosition after send backward")
            ),
            1.0
        );

        runtime
            .dispatch_invoke(
                first_shape_range,
                "ZOrder",
                &[OmValue::Number(f64::from(super::MSO_BRING_TO_FRONT))],
            )
            .expect("ShapeRange.ZOrder msoBringToFront");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "ZOrder", &[])
                    .expect("first chart object z-order after bring to front")
            ),
            3.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_shape_range, "ZOrderPosition", &[])
                    .expect("ShapeRange.ZOrderPosition after bring to front")
            ),
            3.0
        );

        runtime
            .dispatch_invoke(
                first_shape_range,
                "ZOrder",
                &[OmValue::Number(f64::from(super::MSO_SEND_TO_BACK))],
            )
            .expect("ShapeRange.ZOrder msoSendToBack");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "ZOrder", &[])
                    .expect("first chart object z-order after send to back")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_shape_range, "ZOrderPosition", &[])
                    .expect("ShapeRange.ZOrderPosition after send to back")
            ),
            1.0
        );

        assert_eq!(
            runtime
                .dispatch_invoke(
                    first_shape_range,
                    "ZOrder",
                    &[OmValue::Text("front".to_string())],
                )
                .expect_err("ShapeRange.ZOrder rejects non-number")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    first_shape_range,
                    "ZOrder",
                    &[OmValue::Number(f64::from(super::MSO_SEND_BEHIND_TEXT))],
                )
                .expect_err("ShapeRange.ZOrder rejects text wrapping command")
                .code,
            OmErrorCode::Unsupported
        );
        let all_shapes = expect_object_handle(
            runtime
                .dispatch_get(chart_objects, "ShapeRange", &[])
                .expect("ChartObjects.ShapeRange"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(all_shapes, "ZOrderPosition", &[])
                    .expect("multi ShapeRange.ZOrderPosition")
            ),
            f64::from(super::MSO_SHAPE_MIXED)
        );
        assert_eq!(
            runtime
                .dispatch_get(all_shapes, "ZOrderPosition", &[OmValue::Missing])
                .expect_err("ShapeRange.ZOrderPosition rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(all_shapes, "ZOrder", &[])
                .expect_err("ShapeRange.ZOrder rejects missing command")
                .code,
            OmErrorCode::InvalidArgument
        );
        let selected_shapes = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Item",
                    &[OmValue::Array(
                        OmArray::new(1, 2, vec![OmValue::Number(1.0), OmValue::Number(2.0)])
                            .expect("selected z-order array"),
                    )],
                )
                .expect("ChartObjects.Item(array) for multi ZOrder"),
        );
        runtime
            .dispatch_invoke(
                selected_shapes,
                "ZOrder",
                &[OmValue::Number(f64::from(super::MSO_BRING_TO_FRONT))],
            )
            .expect("multi ShapeRange.ZOrder msoBringToFront");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(third_chart_object, "ZOrder", &[])
                    .expect("third chart object z-order after multi bring to front")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "ZOrder", &[])
                    .expect("first chart object z-order after multi bring to front")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "ZOrder", &[])
                    .expect("second chart object z-order after multi bring to front")
            ),
            3.0
        );
        runtime
            .dispatch_invoke(
                selected_shapes,
                "ZOrder",
                &[OmValue::Number(f64::from(super::MSO_SEND_BACKWARD))],
            )
            .expect("multi ShapeRange.ZOrder msoSendBackward");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "ZOrder", &[])
                    .expect("first chart object z-order after multi send backward")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "ZOrder", &[])
                    .expect("second chart object z-order after multi send backward")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(third_chart_object, "ZOrder", &[])
                    .expect("third chart object z-order after multi send backward")
            ),
            3.0
        );
    }

    #[test]
    fn shaperange_increment_moves_chart_objects() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let first_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let second_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(24.0),
                        OmValue::Number(30.0),
                        OmValue::Number(180.0),
                        OmValue::Number(90.0),
                    ],
                )
                .expect("ChartObjects.Add second chart"),
        );
        let shape_range = expect_object_handle(
            runtime
                .dispatch_get(chart_objects, "ShapeRange", &[])
                .expect("ChartObjects.ShapeRange"),
        );
        let first_left = expect_number(
            runtime
                .dispatch_get(first_chart_object, "Left", &[])
                .expect("first ChartObject.Left before increment"),
        );
        let first_top = expect_number(
            runtime
                .dispatch_get(first_chart_object, "Top", &[])
                .expect("first ChartObject.Top before increment"),
        );
        let second_left = expect_number(
            runtime
                .dispatch_get(second_chart_object, "Left", &[])
                .expect("second ChartObject.Left before increment"),
        );
        let second_top = expect_number(
            runtime
                .dispatch_get(second_chart_object, "Top", &[])
                .expect("second ChartObject.Top before increment"),
        );

        runtime
            .dispatch_invoke(shape_range, "IncrementLeft", &[OmValue::Number(12.5)])
            .expect("ShapeRange.IncrementLeft");
        runtime
            .dispatch_invoke(shape_range, "IncrementTop", &[OmValue::Number(-5.0)])
            .expect("ShapeRange.IncrementTop");
        let first_shape = expect_object_handle(
            runtime
                .dispatch_get(first_chart_object, "ShapeRange", &[])
                .expect("first ChartObject.ShapeRange"),
        );
        let second_shape = expect_object_handle(
            runtime
                .dispatch_get(second_chart_object, "ShapeRange", &[])
                .expect("second ChartObject.ShapeRange"),
        );
        runtime
            .dispatch_invoke(shape_range, "IncrementRotation", &[OmValue::Number(15.0)])
            .expect("ShapeRange.IncrementRotation");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Left", &[])
                    .expect("first ChartObject.Left after range increment")
            ),
            first_left + 12.5
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Top", &[])
                    .expect("first ChartObject.Top after range increment")
            ),
            first_top - 5.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Left", &[])
                    .expect("second ChartObject.Left after range increment")
            ),
            second_left + 12.5
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Top", &[])
                    .expect("second ChartObject.Top after range increment")
            ),
            second_top - 5.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_shape, "Rotation", &[])
                    .expect("first ShapeRange.Rotation after range increment")
            ),
            15.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_shape, "Rotation", &[])
                    .expect("second ShapeRange.Rotation after range increment")
            ),
            15.0
        );
        runtime
            .dispatch_invoke(second_shape, "IncrementLeft", &[OmValue::Number(-4.0)])
            .expect("single ShapeRange.IncrementLeft");
        runtime
            .dispatch_invoke(second_shape, "IncrementTop", &[OmValue::Number(2.0)])
            .expect("single ShapeRange.IncrementTop");
        assert_eq!(
            runtime
                .dispatch_invoke(
                    second_chart_object,
                    "IncrementRotation",
                    &[OmValue::Number(7.5)],
                )
                .expect_err("ChartObject.IncrementRotation stays off the direct OM surface")
                .code,
            OmErrorCode::Unsupported
        );
        runtime
            .dispatch_invoke(second_shape, "IncrementRotation", &[OmValue::Number(7.5)])
            .expect("single ShapeRange.IncrementRotation");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Left", &[])
                    .expect("first ChartObject.Left after single increment")
            ),
            first_left + 12.5
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Left", &[])
                    .expect("second ChartObject.Left after single increment")
            ),
            second_left + 8.5
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_chart_object, "Top", &[])
                    .expect("second ChartObject.Top after single increment")
            ),
            second_top - 3.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_shape, "Rotation", &[])
                    .expect("second ShapeRange.Rotation after single increment")
            ),
            22.5
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(shape_range, "Rotation", &[])
                    .expect("mixed ShapeRange.Rotation after single increment")
            ),
            f64::from(super::MSO_SHAPE_MIXED)
        );

        assert_eq!(
            runtime
                .dispatch_invoke(
                    shape_range,
                    "IncrementLeft",
                    &[OmValue::Text("wide".to_string())],
                )
                .expect_err("ShapeRange.IncrementLeft rejects non-number")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(shape_range, "IncrementTop", &[OmValue::Number(f64::NAN)])
                .expect_err("ShapeRange.IncrementTop rejects NaN")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    shape_range,
                    "IncrementRotation",
                    &[OmValue::Text("turn".to_string())],
                )
                .expect_err("ShapeRange.IncrementRotation rejects non-number")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    shape_range,
                    "IncrementRotation",
                    &[OmValue::Number(f64::NAN)],
                )
                .expect_err("ShapeRange.IncrementRotation rejects NaN")
                .code,
            OmErrorCode::InvalidArgument
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook with ShapeRange.IncrementRotation");
        let saved_package =
            OpcPackage::from_bytes(&saved).expect("saved ShapeRange.IncrementRotation package");
        let saved_drawing = String::from_utf8(
            saved_package
                .part("xl/drawings/drawing1.xml")
                .expect("saved ShapeRange.IncrementRotation drawing part")
                .bytes
                .clone(),
        )
        .expect("saved ShapeRange.IncrementRotation drawing XML utf8");
        assert!(saved_drawing.contains(r#"rot="900000""#));
        assert!(saved_drawing.contains(r#"rot="1350000""#));
    }

    #[test]
    fn shaperange_scale_methods_resize_from_requested_anchor() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        runtime
            .dispatch_invoke(
                chart_objects,
                "Add",
                &[
                    OmValue::Number(240.0),
                    OmValue::Number(60.0),
                    OmValue::Number(140.0),
                    OmValue::Number(80.0),
                ],
            )
            .expect("ChartObjects.Add second chart");
        let shape_range = expect_object_handle(
            runtime
                .dispatch_get(chart_objects, "ShapeRange", &[])
                .expect("ChartObjects.ShapeRange"),
        );
        let assert_close = |actual: f64, expected: f64| {
            assert!(
                (actual - expected).abs() < 1e-3,
                "expected {actual} to be close to {expected}"
            );
        };

        let original_left = expect_number(
            runtime
                .dispatch_get(shape_range, "Left", &[])
                .expect("ShapeRange.Left before ScaleWidth"),
        );
        let original_width = expect_number(
            runtime
                .dispatch_get(shape_range, "Width", &[])
                .expect("ShapeRange.Width before ScaleWidth"),
        );
        runtime
            .dispatch_invoke(
                shape_range,
                "ScaleWidth",
                &[
                    OmValue::Number(1.5),
                    OmValue::Number(f64::from(super::MSO_FALSE)),
                    OmValue::Number(f64::from(super::MSO_SCALE_FROM_TOP_LEFT)),
                ],
            )
            .expect("ShapeRange.ScaleWidth from top-left");
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(shape_range, "Left", &[])
                    .expect("ShapeRange.Left after top-left ScaleWidth"),
            ),
            original_left,
        );
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(shape_range, "Width", &[])
                    .expect("ShapeRange.Width after top-left ScaleWidth"),
            ),
            original_width * 1.5,
        );

        let middle_top = expect_number(
            runtime
                .dispatch_get(shape_range, "Top", &[])
                .expect("ShapeRange.Top before ScaleHeight"),
        );
        let middle_height = expect_number(
            runtime
                .dispatch_get(shape_range, "Height", &[])
                .expect("ShapeRange.Height before ScaleHeight"),
        );
        runtime
            .dispatch_invoke(
                shape_range,
                "ScaleHeight",
                &[
                    OmValue::Number(0.5),
                    OmValue::Bool(false),
                    OmValue::Number(f64::from(super::MSO_SCALE_FROM_MIDDLE)),
                ],
            )
            .expect("ShapeRange.ScaleHeight from middle");
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(shape_range, "Top", &[])
                    .expect("ShapeRange.Top after middle ScaleHeight"),
            ),
            middle_top + middle_height * 0.25,
        );
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(shape_range, "Height", &[])
                    .expect("ShapeRange.Height after middle ScaleHeight"),
            ),
            middle_height * 0.5,
        );

        let bottom_right_left = expect_number(
            runtime
                .dispatch_get(shape_range, "Left", &[])
                .expect("ShapeRange.Left before bottom-right ScaleWidth"),
        );
        let bottom_right_width = expect_number(
            runtime
                .dispatch_get(shape_range, "Width", &[])
                .expect("ShapeRange.Width before bottom-right ScaleWidth"),
        );
        runtime
            .dispatch_invoke(
                shape_range,
                "ScaleWidth",
                &[
                    OmValue::Number(0.5),
                    OmValue::Number(f64::from(super::MSO_TRUE)),
                    OmValue::Number(f64::from(super::MSO_SCALE_FROM_BOTTOM_RIGHT)),
                ],
            )
            .expect("ShapeRange.ScaleWidth from bottom-right");
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(shape_range, "Left", &[])
                    .expect("ShapeRange.Left after bottom-right ScaleWidth"),
            ),
            bottom_right_left + bottom_right_width * 0.5,
        );
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(shape_range, "Width", &[])
                    .expect("ShapeRange.Width after bottom-right ScaleWidth"),
            ),
            bottom_right_width * 0.5,
        );

        let first_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1) before single ShapeRange scale"),
        );
        let first_chart_shape_range = expect_object_handle(
            runtime
                .dispatch_get(first_chart_object, "ShapeRange", &[])
                .expect("ChartObject.ShapeRange before single scale"),
        );
        let direct_left = expect_number(
            runtime
                .dispatch_get(first_chart_object, "Left", &[])
                .expect("ChartObject.Left before single ShapeRange ScaleWidth"),
        );
        let direct_width = expect_number(
            runtime
                .dispatch_get(first_chart_object, "Width", &[])
                .expect("ChartObject.Width before single ShapeRange ScaleWidth"),
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    first_chart_object,
                    "ScaleWidth",
                    &[
                        OmValue::Number(2.0),
                        OmValue::Bool(false),
                        OmValue::Number(f64::from(super::MSO_SCALE_FROM_TOP_LEFT)),
                    ],
                )
                .expect_err("ChartObject.ScaleWidth stays off the direct OM surface")
                .code,
            OmErrorCode::Unsupported
        );
        runtime
            .dispatch_invoke(
                first_chart_shape_range,
                "ScaleWidth",
                &[
                    OmValue::Number(2.0),
                    OmValue::Bool(false),
                    OmValue::Number(f64::from(super::MSO_SCALE_FROM_TOP_LEFT)),
                ],
            )
            .expect("single ShapeRange.ScaleWidth from top-left");
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Left", &[])
                    .expect("ChartObject.Left after single ShapeRange ScaleWidth"),
            ),
            direct_left,
        );
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Width", &[])
                    .expect("ChartObject.Width after single ShapeRange ScaleWidth"),
            ),
            direct_width * 2.0,
        );

        let direct_top = expect_number(
            runtime
                .dispatch_get(first_chart_object, "Top", &[])
                .expect("ChartObject.Top before single ShapeRange ScaleHeight"),
        );
        let direct_height = expect_number(
            runtime
                .dispatch_get(first_chart_object, "Height", &[])
                .expect("ChartObject.Height before single ShapeRange ScaleHeight"),
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    first_chart_object,
                    "ScaleHeight",
                    &[
                        OmValue::Number(0.5),
                        OmValue::Bool(false),
                        OmValue::Number(f64::from(super::MSO_SCALE_FROM_MIDDLE)),
                    ],
                )
                .expect_err("ChartObject.ScaleHeight stays off the direct OM surface")
                .code,
            OmErrorCode::Unsupported
        );
        runtime
            .dispatch_invoke(
                first_chart_shape_range,
                "ScaleHeight",
                &[
                    OmValue::Number(0.5),
                    OmValue::Bool(false),
                    OmValue::Number(f64::from(super::MSO_SCALE_FROM_MIDDLE)),
                ],
            )
            .expect("single ShapeRange.ScaleHeight from middle");
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Top", &[])
                    .expect("ChartObject.Top after single ShapeRange ScaleHeight"),
            ),
            direct_top + direct_height * 0.25,
        );
        assert_close(
            expect_number(
                runtime
                    .dispatch_get(first_chart_object, "Height", &[])
                    .expect("ChartObject.Height after single ShapeRange ScaleHeight"),
            ),
            direct_height * 0.5,
        );

        assert_eq!(
            runtime
                .dispatch_invoke(
                    shape_range,
                    "ScaleWidth",
                    &[
                        OmValue::Text("wide".to_string()),
                        OmValue::Bool(false),
                        OmValue::Missing,
                    ],
                )
                .expect_err("ShapeRange.ScaleWidth rejects non-number factor")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    shape_range,
                    "ScaleHeight",
                    &[
                        OmValue::Number(1.0),
                        OmValue::Bool(false),
                        OmValue::Number(99.0),
                    ],
                )
                .expect_err("ShapeRange.ScaleHeight rejects invalid scale")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn shaperange_action_methods_use_shape_semantics() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let application = runtime.root_application();
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let shape_range = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "ShapeRange", &[])
                .expect("ChartObject.ShapeRange"),
        );

        for (member, args, expected_mode) in [
            ("Copy", Vec::new(), super::XL_COPY),
            (
                "CopyPicture",
                vec![
                    OmValue::Missing,
                    OmValue::Number(f64::from(super::XL_PICTURE)),
                ],
                super::XL_COPY,
            ),
            ("Cut", Vec::new(), super::XL_CUT),
        ] {
            runtime
                .dispatch_set(application, "CutCopyMode", OmValue::Bool(false), &[])
                .expect("reset Application.CutCopyMode");
            assert_eq!(
                runtime
                    .dispatch_invoke(shape_range, member, &args)
                    .unwrap_or_else(|error| {
                        panic!("ShapeRange.{member} should set headless cut/copy mode: {error:?}")
                    }),
                OmValue::Empty
            );
            assert_eq!(
                expect_number(
                    runtime
                        .dispatch_get(application, "CutCopyMode", &[])
                        .expect("Application.CutCopyMode after ShapeRange method")
                ),
                f64::from(expected_mode)
            );
        }

        runtime
            .dispatch_invoke(shape_range, "Select", &[])
            .expect("ShapeRange.Select");
        let active_chart = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after ShapeRange.Select"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_chart, "Name", &[])
                    .expect("ActiveChart.Name after ShapeRange.Select")
            ),
            "Embedded Revenue Chart"
        );
        runtime
            .dispatch_invoke(shape_range, "Select", &[OmValue::Bool(false)])
            .expect("ShapeRange.Select with Replace");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_chart, "Name", &[])
                    .expect("ActiveChart.Name after ShapeRange.Select Replace")
            ),
            "Embedded Revenue Chart"
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    shape_range,
                    "Select",
                    &[OmValue::Text("replace".to_string())],
                )
                .expect_err("ShapeRange.Select rejects non-boolean Replace")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    shape_range,
                    "Select",
                    &[OmValue::Bool(true), OmValue::Missing],
                )
                .expect_err("ShapeRange.Select rejects extra arguments")
                .code,
            OmErrorCode::InvalidArgument
        );

        let duplicated_shape = expect_object_handle(
            runtime
                .dispatch_invoke(shape_range, "Duplicate", &[])
                .expect("ShapeRange.Duplicate"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(duplicated_shape, "Count", &[])
                    .expect("duplicated ShapeRange.Count")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Count", &[])
                    .expect("ChartObjects.Count after ShapeRange.Duplicate")
            ),
            2.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(duplicated_shape, "Name", &[])
                    .expect("duplicated ShapeRange.Name")
            ),
            "Chart 2"
        );

        assert_eq!(
            runtime
                .dispatch_invoke(duplicated_shape, "Delete", &[])
                .expect("ShapeRange.Delete"),
            OmValue::Empty
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Count", &[])
                    .expect("ChartObjects.Count after ShapeRange.Delete")
            ),
            1.0
        );
        assert_eq!(
            runtime
                .dispatch_get(duplicated_shape, "Count", &[])
                .expect_err("deleted ShapeRange handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_invoke(shape_range, "Delete", &[OmValue::Missing])
                .expect_err("ShapeRange.Delete rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(shape_range, "Duplicate", &[OmValue::Missing])
                .expect_err("ShapeRange.Duplicate rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

