    #[test]
    fn chart_paste_uses_copied_range_source_and_validates_type() {
        let mut runtime = ExcelRuntime::new();
        let application = runtime.root_application();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("B2:C4".to_string())])
                .expect("Worksheet.Range(B2:C4)"),
        );
        runtime
            .dispatch_set(
                source,
                "Value",
                OmValue::Array(
                    OmArray::new(
                        3,
                        2,
                        vec![
                            OmValue::Number(10.0),
                            OmValue::Number(20.0),
                            OmValue::Number(30.0),
                            OmValue::Number(40.0),
                            OmValue::Number(50.0),
                            OmValue::Number(60.0),
                        ],
                    )
                    .expect("chart paste seed values array"),
                ),
                &[],
            )
            .expect("seed chart paste source values");

        runtime
            .dispatch_invoke(source, "Copy", &[])
            .expect("Range.Copy before Chart.Paste");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode after Range.Copy")
            ),
            f64::from(super::XL_COPY)
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    chart,
                    "Paste",
                    &[OmValue::Number(f64::from(super::XL_PASTE_FORMULAS))],
                )
                .expect("Chart.Paste xlPasteFormulas"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Chart.Paste"),
            OmValue::Bool(false)
        );
        assert_eq!(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Chart.Paste source data"),
            OmValue::Bool(false)
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection after Chart.Paste"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1) after Chart.Paste"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Values", &[])
                    .expect("Series.Values after Chart.Paste")
            ),
            "=Sheet1!$B$2:$C$4"
        );

        runtime
            .dispatch_invoke(source, "Copy", &[])
            .expect("Range.Copy before Chart.Paste formulas and number formats");
        assert_eq!(
            runtime
                .dispatch_invoke(
                    chart,
                    "Paste",
                    &[OmValue::Number(f64::from(
                        super::XL_PASTE_FORMULAS_AND_NUMBER_FORMATS,
                    ))],
                )
                .expect("Chart.Paste xlPasteFormulasAndNumberFormats"),
            OmValue::Empty
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection after Chart.Paste formulas and number formats"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1) after Chart.Paste formulas and number formats"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Values", &[])
                    .expect("Series.Values after Chart.Paste formulas and number formats")
            ),
            "=Sheet1!$B$2:$C$4"
        );

        for (paste_type, label) in [
            (super::XL_PASTE_ALL_EXCEPT_BORDERS, "xlPasteAllExceptBorders"),
            (
                super::XL_PASTE_ALL_USING_SOURCE_THEME,
                "xlPasteAllUsingSourceTheme",
            ),
            (
                super::XL_PASTE_ALL_MERGING_CONDITIONAL_FORMATS,
                "xlPasteAllMergingConditionalFormats",
            ),
        ] {
            runtime
                .dispatch_invoke(source, "Copy", &[])
                .unwrap_or_else(|_| panic!("Range.Copy before Chart.Paste {label}"));
            assert_eq!(
                runtime
                    .dispatch_invoke(
                        chart,
                        "Paste",
                        &[OmValue::Number(f64::from(paste_type))],
                    )
                    .unwrap_or_else(|_| panic!("Chart.Paste {label}")),
                OmValue::Empty
            );
            let series_collection = expect_object_handle(
                runtime
                    .dispatch_get(chart, "SeriesCollection", &[])
                    .unwrap_or_else(|_| panic!("Chart.SeriesCollection after Chart.Paste {label}")),
            );
            let series = expect_object_handle(
                runtime
                    .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                    .unwrap_or_else(|_| {
                        panic!("SeriesCollection.Item(1) after Chart.Paste {label}")
                    }),
            );
            assert_eq!(
                expect_text(
                    runtime
                        .dispatch_get(series, "Values", &[])
                        .unwrap_or_else(|_| panic!("Series.Values after Chart.Paste {label}"))
                ),
                "=Sheet1!$B$2:$C$4"
            );
        }

        runtime
            .dispatch_invoke(source, "Copy", &[])
            .expect("Range.Copy before Chart.Paste formats");
        assert_eq!(
            runtime
                .dispatch_invoke(
                    chart,
                    "Paste",
                    &[OmValue::Number(f64::from(super::XL_PASTE_FORMATS))],
                )
                .expect("Chart.Paste xlPasteFormats"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Chart.Paste formats"),
            OmValue::Bool(false)
        );

        runtime
            .dispatch_invoke(source, "Copy", &[])
            .expect("Range.Copy before Chart.Paste values");
        assert_eq!(
            runtime
                .dispatch_invoke(
                    chart,
                    "Paste",
                    &[OmValue::Number(f64::from(super::XL_PASTE_VALUES))],
                )
                .expect("Chart.Paste xlPasteValues"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Chart.Paste values"),
            OmValue::Bool(false)
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection after Chart.Paste values"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1) after Chart.Paste values"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Values", &[])
                    .expect("Series.Values after Chart.Paste values")
            ),
            "={10,20;30,40;50,60}"
        );

        runtime
            .dispatch_invoke(source, "Copy", &[])
            .expect("Range.Copy before Chart.Paste values and number formats");
        assert_eq!(
            runtime
                .dispatch_invoke(
                    chart,
                    "Paste",
                    &[OmValue::Number(f64::from(
                        super::XL_PASTE_VALUES_AND_NUMBER_FORMATS,
                    ))],
                )
                .expect("Chart.Paste xlPasteValuesAndNumberFormats"),
            OmValue::Empty
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection after Chart.Paste values and number formats"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1) after Chart.Paste values and number formats"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Values", &[])
                    .expect("Series.Values after Chart.Paste values and number formats")
            ),
            "={10,20;30,40;50,60}"
        );

        for (paste_type, label) in [
            (super::XL_PASTE_COMMENTS, "xlPasteComments"),
            (super::XL_PASTE_VALIDATION, "xlPasteValidation"),
            (super::XL_PASTE_COLUMN_WIDTHS, "xlPasteColumnWidths"),
        ] {
            runtime
                .dispatch_invoke(source, "Copy", &[])
                .unwrap_or_else(|_| panic!("Range.Copy before Chart.Paste {label}"));
            assert_eq!(
                runtime
                    .dispatch_invoke(
                        chart,
                        "Paste",
                        &[OmValue::Number(f64::from(paste_type))],
                    )
                    .unwrap_or_else(|_| panic!("Chart.Paste {label}")),
                OmValue::Empty
            );
            assert_eq!(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .unwrap_or_else(|_| {
                        panic!("Application.CutCopyMode after Chart.Paste {label}")
                    }),
                OmValue::Bool(false)
            );
            let series_collection = expect_object_handle(
                runtime
                    .dispatch_get(chart, "SeriesCollection", &[])
                    .unwrap_or_else(|_| panic!("Chart.SeriesCollection after Chart.Paste {label}")),
            );
            let series = expect_object_handle(
                runtime
                    .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                    .unwrap_or_else(|_| {
                        panic!("SeriesCollection.Item(1) after Chart.Paste {label}")
                    }),
            );
            assert_eq!(
                expect_text(
                    runtime
                        .dispatch_get(series, "Values", &[])
                        .unwrap_or_else(|_| panic!("Series.Values after Chart.Paste {label}"))
                ),
                "={10,20;30,40;50,60}"
            );
        }

        assert_eq!(
            runtime
                .dispatch_invoke(chart, "Paste", &[])
                .expect_err("Chart.Paste requires clipboard")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    chart,
                    "Paste",
                    &[OmValue::Number(99_999.0)],
                )
                .expect_err("Chart.Paste rejects unsupported Type")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(chart, "Paste", &[OmValue::Text("bad".to_string())])
                .expect_err("Chart.Paste rejects non-numeric Type")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(chart, "Paste", &[OmValue::Missing, OmValue::Missing],)
                .expect_err("Chart.Paste rejects too many arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn chart_paste_preserves_multi_area_copied_range_source() {
        let mut runtime = ExcelRuntime::new();
        let application = runtime.root_application();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheet,
                    "Range",
                    &[OmValue::Text("A1:A3,C1:C3".to_string())],
                )
                .expect("Worksheet.Range(A1:A3,C1:C3)"),
        );

        runtime
            .dispatch_invoke(source, "Copy", &[])
            .expect("multi-area Range.Copy before Chart.Paste");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode after multi-area Range.Copy")
            ),
            f64::from(super::XL_COPY)
        );
        assert_eq!(
            runtime
                .dispatch_invoke(chart, "Paste", &[])
                .expect("Chart.Paste multi-area source"),
            OmValue::Empty
        );

        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection after multi-area Chart.Paste"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1) after multi-area Chart.Paste"),
        );
        assert_eq!(
            runtime
                .dispatch_get(series, "Values", &[])
                .expect("Series.Values after multi-area Chart.Paste"),
            OmValue::Text("=Sheet1!$A$1:$A$3,Sheet1!$C$1:$C$3".to_string())
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Formula", &[])
                    .expect("Series.Formula after multi-area Chart.Paste")
            ),
            "=SERIES(,,(Sheet1!$A$1:$A$3,Sheet1!$C$1:$C$3),1)"
        );

        let state = runtime
            .workbook_state(workbook)
            .expect("workbook state after multi-area Chart.Paste");
        let sheet_id = state.worksheets[0].id;
        let chart_model = state.charts.values().next().expect("chart model");
        let values = chart_model.series[0]
            .values
            .as_ref()
            .expect("series values");
        let Some(ReferenceTarget::Range(range)) = values.resolved.as_ref() else {
            panic!("multi-area Chart.Paste values should keep a resolved range");
        };
        assert_eq!(range.areas().len(), 2);
        assert_eq!(range.areas()[0].scope, SheetScope::Single(sheet_id));
        assert_eq!(
            range.areas()[0].rect,
            Rect {
                row_first: 1,
                row_last: 3,
                col_first: 1,
                col_last: 1,
            }
        );
        assert_eq!(range.areas()[1].scope, SheetScope::Single(sheet_id));
        assert_eq!(
            range.areas()[1].rect,
            Rect {
                row_first: 1,
                row_last: 3,
                col_first: 3,
                col_last: 3,
            }
        );
    }

