    #[test]
    fn chart_series_formula_setter_rebalances_plot_order() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("ChartObjects.Add"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        let first_series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries first"),
        );
        let second_series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries second"),
        );

        runtime
            .dispatch_set(
                second_series,
                "Formula",
                OmValue::Text(
                    "=SERIES(Sheet1!$C$1,Sheet1!$A$1:$A$3,Sheet1!$B$1:$B$3,1)".to_string(),
                ),
                &[],
            )
            .expect("set second Series.Formula plot order");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_series, "PlotOrder", &[])
                    .expect("first Series.PlotOrder")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_series, "PlotOrder", &[])
                    .expect("second Series.PlotOrder")
            ),
            1.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(first_series, "Formula", &[])
                    .expect("first Series.Formula")
            ),
            "=SERIES(,,,2)"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(second_series, "Formula", &[])
                    .expect("second Series.Formula")
            ),
            "=SERIES(Sheet1!$C$1,Sheet1!$A$1:$A$3,Sheet1!$B$1:$B$3,1)"
        );
    }

    #[test]
    fn chart_set_source_data_uses_range_source_for_first_series() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let worksheet = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        let source_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B3".to_string())])
                .expect("Worksheet.Range(A1:B3)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("ChartObjects.Add"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        runtime
            .dispatch_invoke(chart, "SetSourceData", &[OmValue::Object(source_range)])
            .expect("Chart.SetSourceData");
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(series_collection, "Count", &[])
                    .expect("SeriesCollection.Count")
            ),
            1.0
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1)"),
        );
        assert_eq!(
            runtime
                .dispatch_get(series, "Values", &[])
                .expect("Series.Values"),
            OmValue::Text("=Sheet1!$A$1:$B$3".to_string())
        );
        {
            let state = runtime
                .workbook_state(workbook)
                .expect("workbook state after Chart.SetSourceData");
            let sheet_id = state.worksheets[0].id;
            let chart = state.charts.values().next().expect("chart model");
            let values = chart.series[0].values.as_ref().expect("series values");
            let Some(ReferenceTarget::Range(range)) = values.resolved.as_ref() else {
                panic!("SetSourceData values should keep a resolved range");
            };
            assert_eq!(range.workbook_id(), state.model.id);
            assert_eq!(range.areas().len(), 1);
            assert_eq!(range.areas()[0].scope, SheetScope::Single(sheet_id));
            assert_eq!(
                range.areas()[0].rect,
                Rect {
                    row_first: 1,
                    row_last: 3,
                    col_first: 1,
                    col_last: 2,
                }
            );
        }
        runtime
            .dispatch_set(
                worksheet,
                "Name",
                OmValue::Text("Data 2026".to_string()),
                &[],
            )
            .expect("rename chart source worksheet");
        assert_eq!(
            runtime
                .dispatch_get(series, "Values", &[])
                .expect("Series.Values after source sheet rename"),
            OmValue::Text("='Data 2026'!$A$1:$B$3".to_string())
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after Chart.SetSourceData");
        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after Chart.SetSourceData");
        let reopened_worksheets = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[])
                .expect("reopened Workbook.Worksheets"),
        );
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("reopened Worksheets.Item(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        let reopened_series_collection = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart, "SeriesCollection", &[])
                .expect("reopened Chart.SeriesCollection"),
        );
        let reopened_series = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("reopened SeriesCollection.Item(1)"),
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_series, "Values", &[])
                .expect("reopened Series.Values"),
            OmValue::Text("='Data 2026'!$A$1:$B$3".to_string())
        );
    }

